#!/usr/bin/env python3
"""
Smart Irrigation System for Raspberry Pi.

Controls a solenoid valve based on capacitive analog soil moisture
readings from an MCP3008 SPI ADC (bus 0, device 0, CE0, channel 0).
Exposes a JSON command interface over TCP on the specified port.
"""

import argparse
import json
import logging
import signal
import socket
import sys
import time

import spidev
from gpiozero import OutputDevice

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_spi = None
_valve = None
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _cleanup():
    """Release hardware resources."""
    global _spi, _valve
    if _valve is not None:
        try:
            _valve.close()
        except Exception:
            pass
        _valve = None
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None


def _parse_args():
    parser = argparse.ArgumentParser(
        description="Smart Irrigation System for Raspberry Pi"
    )
    parser.add_argument(
        "--moisture_threshold", type=int, default=30,
        help="Soil moisture threshold below which irrigation starts (0-1023)"
    )
    parser.add_argument(
        "--web_port", type=int, default=8080,
        help="TCP port for the JSON command interface"
    )
    parser.add_argument(
        "--log_file", type=str, default="irrigation.log",
        help="Path to the log file"
    )
    parser.add_argument(
        "--valve_pin", type=int, default=17,
        help="BCM GPIO pin number for the solenoid valve (default 17)"
    )
    parser.add_argument(
        "--spi_channel", type=int, default=0,
        help="MCP3008 channel (0-7) for the soil moisture sensor"
    )
    return parser.parse_args()


def _setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Starting Smart Irrigation System")


def _init_spi(channel):
    """Open SPI bus 0, device 0, CE0, and return the spidev.SpiDev handle."""
    global _spi
    try:
        _spi = spidev.SpiDev()
        _spi.open(0, 0)
        _spi.max_speed_hz = 1_000_000
        _spi.mode = 0
        logging.info("SPI initialized: bus 0, device 0, CE0")
        return _spi
    except Exception as exc:
        logging.error(f"Failed to initialize SPI: {exc}")
        raise


def _read_moisture(spi, channel):
    """
    Read a 10-bit value from the MCP3008 on the given channel.

    Returns the raw 10-bit integer (0-1023).  Raises RuntimeError on SPI
    errors or on sensor-absent conditions (all zeros or all ones).
    """
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}; must be 0-7")

    try:
        # MCP3008 single-ended read: start bit, config byte, padding
        resp = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
    except Exception as exc:
        raise RuntimeError(f"SPI transfer failed on channel {channel}: {exc}")

    if len(resp) != 3:
        raise RuntimeError(f"Unexpected SPI response length: {len(resp)}")

    value = ((resp[1] & 0x03) << 8) | resp[2]

    if value == 0:
        raise RuntimeError(
            f"Sensor-absent or shorted to GND on channel {channel} "
            "(all zeros)"
        )
    if value == 1023:
        raise RuntimeError(
            f"Sensor-absent or shorted to VDD on channel {channel} "
            "(all ones)"
        )

    return value


def _control_valve(valve, moisture, threshold, hysteresis):
    """Decide whether the valve should be open or closed.

    Returns True when the valve is open, False when closed.
    """
    if moisture < threshold:
        if not valve.is_active:
            valve.on()
            logging.info(
                f"Moisture {moisture} < threshold {threshold}; "
                "valve OPENED"
            )
        return True
    if moisture > threshold + hysteresis:
        if valve.is_active:
            valve.off()
            logging.info(
                f"Moisture {moisture} > threshold+{hysteresis}; "
                "valve CLOSED"
            )
        return False
    return valve.is_active


def _handle_client(conn, addr, valve, threshold, spi, channel):
    """Process a single TCP connection, handling JSON commands."""
    with conn:
        logging.info(f"Connection from {addr}")
        try:
            data = conn.recv(1024)
            if not data:
                return

            request = data.decode("utf-8", errors="replace").strip()
            logging.info(f"Received: {request}")

            try:
                cmd = json.loads(request)
            except json.JSONDecodeError:
                conn.sendall(b'{"error": "Invalid JSON"}\n')
                return

            if not isinstance(cmd, dict):
                conn.sendall(b'{"error": "Command must be a JSON object"}\n')
                return

            action = cmd.get("action")
            if action == "get_status":
                try:
                    moisture = _read_moisture(spi, channel)
                    valve_state = valve.is_active
                    status = {
                        "moisture": moisture,
                        "valve": valve_state,
                        "threshold": threshold,
                    }
                    conn.sendall(json.dumps(status).encode("utf-8") + b"\n")
                except RuntimeError as exc:
                    logging.error(f"Sensor read error: {exc}")
                    conn.sendall(
                        json.dumps({"error": str(exc)}).encode("utf-8") + b"\n"
                    )
                except Exception as exc:
                    logging.error(f"Unexpected error in get_status: {exc}")
                    conn.sendall(
                        json.dumps({"error": "Internal error"}).encode("utf-8") + b"\n"
                    )

            elif action == "toggle_valve":
                try:
                    valve_state = not valve.is_active
                    if valve_state:
                        valve.on()
                    else:
                        valve.off()
                    logging.info("Valve state toggled by command")
                    conn.sendall(
                        json.dumps({"valve": valve_state}).encode("utf-8") + b"\n"
                    )
                except Exception as exc:
                    logging.error(f"Failed to toggle valve: {exc}")
                    conn.sendall(
                        json.dumps({"error": str(exc)}).encode("utf-8") + b"\n"
                    )

            else:
                conn.sendall(
                    json.dumps({"error": "Unknown action"}).encode("utf-8") + b"\n"
                )

        except socket.timeout:
            logging.warning("Client connection timed out")
        except ConnectionResetError:
            logging.warning("Client closed connection unexpectedly")
        except Exception as exc:
            logging.error(f"Error handling client {addr}: {exc}")


def _run_server(web_port, valve, threshold, spi, channel):
    """Run the TCP command server until interrupted."""
    global _running
    server = None
    try:
        server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server.bind(("", web_port))
        server.listen(5)
        server.settimeout(1.0)
        logging.info(f"Listening on port {web_port}")

        while _running:
            try:
                conn, addr = server.accept()
            except socket.timeout:
                continue
            _handle_client(conn, addr, valve, threshold, spi, channel)

    except OSError as exc:
        logging.error(f"Socket error on port {web_port}: {exc}")
    except Exception as exc:
        logging.error(f"Unexpected server error: {exc}")
    finally:
        if server is not None:
            try:
                server.close()
            except Exception:
                pass


def main():
    args = _parse_args()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _setup_logging(args.log_file)

    try:
        _init_spi(args.spi_channel)
    except Exception:
        logging.error("Cannot continue without SPI; aborting.")
        _cleanup()
        sys.exit(1)

    try:
        _valve = OutputDevice(args.valve_pin, active_high=True, initial_value=False)
        logging.info(f"Valve initialized on BCM GPIO {args.valve_pin}")
    except Exception as exc:
        logging.error(f"Failed to initialize valve on pin {args.valve_pin}: {exc}")
        _cleanup()
        sys.exit(1)

    logging.info(
        f"Configuration: threshold={args.moisture_threshold}, "
        f"port={args.web_port}, log={args.log_file}, "
        f"valve_pin={args.valve_pin}, spi_channel={args.spi_channel}"
    )

    try:
        while _running:
            try:
                moisture = _read_moisture(_spi, args.spi_channel)
                logging.info(f"Moisture: {moisture}")
                _control_valve(_valve, moisture, args.moisture_threshold, 10)
            except RuntimeError as exc:
                logging.error(f"Sensor read error: {exc}")
            except Exception as exc:
                logging.error(f"Unexpected error in main loop: {exc}")

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)

    except Exception as exc:
        logging.error(f"Fatal error: {exc}")
    finally:
        _cleanup()
        logging.info("Smart Irrigation System stopped")


if __name__ == "__main__":
    main()

