import sys
import time
import logging
import threading

import smbus2
import RPi.GPIO as GPIO

try:
    from adafruit_lsm303 import LSM303
    from adafruit_lsm303_accel import Acceleration
    from adafruit_lsm303dlh_mag import MagneticField
except ImportError as e:
    print(f"Failed to import Adafruit LSM303 libraries: {e}")
    print("Install with: pip install adafruit-circuitpython-lsm303")
    sys.exit(1)

try:
    from adafruit_ads1x15.ads1015 import ADS1015
    from adafruit_ads1x15.analog_in import AnalogIn
except ImportError as e:
    print(f"Failed to import Adafruit ADS1015 libraries: {e}")
    print("Install with: pip install adafruit-circuitpython-ads1x15")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

class MotorDriver:
    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.pwm = None
        self._lock = threading.Lock()
        self._running = False

    def setup(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in (self.dir_pin, self.step_pin, self.ms0_pin, self.ms1_pin):
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        self.pwm = GPIO.PWM(self.step_pin, 500)
        self.pwm.start(0)
        self._running = True

    def set_resolution(self, resolution):
        if resolution == "Full":
            GPIO.output(self.ms0_pin, GPIO.HIGH)
            GPIO.output(self.ms1_pin, GPIO.LOW)
        elif resolution == "Half":
            GPIO.output(self.ms0_pin, GPIO.LOW)
            GPIO.output(self.ms1_pin, GPIO.HIGH)
        elif resolution == "1/4":
            GPIO.output(self.ms0_pin, GPIO.HIGH)
            GPIO.output(self.ms1_pin, GPIO.HIGH)
        else:
            raise ValueError(f"Invalid resolution: {resolution}")

    def rotate(self, clockwise=True, steps=100, duty_cycle=128):
        with self._lock:
            if not self._running or self.pwm is None:
                logging.error("Motor driver not initialized; cannot rotate.")
                return
            GPIO.output(self.dir_pin, GPIO.HIGH if clockwise else GPIO.LOW)
            self.set_resolution("Full")
            self.pwm.ChangeDutyCycle(duty_cycle)
            time.sleep(0.01)
            for _ in range(steps):
                self.pwm.ChangeDutyCycle(duty_cycle)
                time.sleep(0.001)
            self.pwm.ChangeDutyCycle(0)

    def stop(self):
        with self._lock:
            if self.pwm is not None:
                self.pwm.ChangeDutyCycle(0)
                self.pwm.stop()
            self._running = False

class ADCManager:
    def __init__(self, i2c_bus, address=0x48, gain=1):
        self.i2c_bus = i2c_bus
        self.address = address
        self.gain = gain
        self.adc = None
        self.channel = None

    def setup(self):
        try:
            self.adc = ADS1015(self.i2c_bus, address=self.address, gain=self.gain)
            self.channel = AnalogIn(self.adc, 0)
        except Exception as e:
            logging.error(f"Failed to initialize ADS1015: {e}")
            raise

    def read_channel(self):
        if self.channel is None:
            raise RuntimeError("ADC not initialized")
        return self.channel.voltage

class SensorManager:
    def __init__(self, i2c_bus):
        self.i2c_bus = i2c_bus
        self.lsm303 = None

    def setup(self):
        try:
            self.lsm303 = LSM303(self.i2c_bus)
        except Exception as e:
            logging.error(f"Failed to initialize LSM303: {e}")
            raise

    def get_acceleration(self):
        if self.lsm303 is None:
            raise RuntimeError("LSM303 not initialized")
        return Acceleration(self.lsm303.acceleration)

    def get_magnetic_field(self):
        if self.lsm303 is None:
            raise RuntimeError("LSM303 not initialized")
        return MagneticField(self.lsm303.magnetic)

def calculate_heading(magnetic_field):
    x, y, _ = magnetic_field
    heading_rad = -math.atan2(y, x)
    heading_deg = math.degrees(heading_rad) % 360
    return heading_deg

def calculate_inclination(acceleration):
    x, y, z = acceleration
    inclination_xz = math.degrees(math.atan2(x, z))
    inclination_yz = math.degrees(math.atan2(y, z))
    return inclination_xz, inclination_yz

def main():
    dir_pin = 20
    step_pin = 21
    ms0_pin = 14
    ms1_pin = 15
    I2C_BUS = 1
    ADC_ADDRESS = 0x48
    ADC_GAIN = 1

    motor_driver = MotorDriver(dir_pin, step_pin, ms0_pin, ms1_pin)
    i2c_bus = None
    adc_manager = None
    sensor_manager = None

    def cleanup(signum=None, frame=None):
        logging.info("Cleaning up resources...")
        if motor_driver.pwm is not None:
            motor_driver.stop()
        if i2c_bus is not None:
            try:
                i2c_bus.close()
            except Exception:
                pass
        GPIO.cleanup()
        logging.info("Cleanup complete.")
        sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        motor_driver.setup()
        adc_manager = ADCManager(i2c_bus, ADC_ADDRESS, ADC_GAIN)
        adc_manager.setup()
        sensor_manager = SensorManager(i2c_bus)
        sensor_manager.setup()
    except Exception as e:
        logging.error(f"Failed to initialize sensors or motor driver: {e}")
        cleanup()
        sys.exit(1)

