                logging.info(f"ADC Voltage: {voltage:.3f} V, PWM Duty Cycle: {duty_cycle}")
            except Exception as e:
                logging.error(f"ADC read error: {e}")

            try:
                acceleration = sensor_manager.get_acceleration()
                magnetic_field = sensor_manager.get_magnetic_field()
                heading = calculate_heading(magnetic_field)
                inclination_xz, inclination_yz = calculate_inclination(acceleration)
                logging.info(f"Acceleration: {acceleration}, Heading: {heading:.2f} deg, Inclination XZ: {inclination_xz:.2f} deg, Inclination YZ: {inclination_yz:.2f} deg")
            except Exception as e:
                logging.error(f"Sensor read error: {e}")

            time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

