import csv
import signal
import sys
import time
from datetime import datetime, timezone

import spidev

# Constants
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1200000
ADC_CHANNEL = 2
ADC_MAX_VALUE = 1023
DRY_VALUE = 820
WET_VALUE = 400
LOG_FILE = "soil_moisture_log.csv"
NUM_SAMPLES = 25
SAMPLE_INTERVAL_S = 1.0


class SoilMoistureSensor:
    """Reads soil moisture via an MCP3008 ADC on a Raspberry Pi SPI bus."""

    def __init__(self, bus=SPI_BUS, device=SPI_DEVICE, max_speed_hz=SPI_MAX_SPEED_HZ):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(bus, device)
            self.spi.max_speed_hz = max_speed_hz
            self.spi.mode = 0
            self.spi.bits_per_word = 8
        except Exception as exc:
            raise RuntimeError(f"Failed to open SPI bus {bus} device {device}: {exc}") from exc

        self.recent_readings = []
        self._running = True

    def read_adc(self, channel):
        """Read a single-ended channel from the MCP3008 and return a 10-bit int."""
        if not 0 <= channel <= 7:
            raise ValueError(f"Invalid ADC channel {channel}; must be 0-7.")
        if len(self.recent_readings) >= 10:
            self.recent_readings = self.recent_readings[-9:]

        # MCP3008 single-ended read: start bit, single-ended mode bit, channel bits
        tx = [0x01, (0x08 | channel) << 4, 0x00]
        try:
            rx = self.spi.xfer2(tx)
        except Exception as exc:
            raise RuntimeError(f"SPI transfer failed on channel {channel}: {exc}") from exc

        if len(rx) != 3:
            raise RuntimeError(f"Unexpected SPI response length: {len(rx)} bytes.")

        raw = ((rx[1] & 0x03) << 8) | rx[2]
        self.recent_readings.append(raw)
        return raw

    def convert_to_percentage(self, raw_value):
        """Map a raw ADC value to a moisture percentage (0-100)."""
        if raw_value <= WET_VALUE:
            return 100.0
        if raw_value >= DRY_VALUE:
            return 0.0
        return ((DRY_VALUE - raw_value) / (DRY_VALUE - WET_VALUE)) * 100.0

    def get_rolling_stats(self):
        """Return mean and standard deviation of the recent readings."""
        if not self.recent_readings:
            return 0.0, 0.0
        mean = sum(self.recent_readings) / len(self.recent_readings)
        variance = sum((x - mean) ** 2 for x in self.recent_readings) / len(self.recent_readings)
        return mean, variance ** 0.5

    def close(self):
        """Release the SPI device."""
        try:
            self.spi.close()
        except Exception:
            pass


def log_reading(log_file, timestamp, moisture_percentage):
    """Append a timestamped moisture reading to the CSV log file."""
    try:
        with open(log_file, "a", newline="") as fh:
            writer = csv.writer(fh)
            writer.writerow([timestamp, f"{moisture_percentage:.2f}"])
    except OSError as exc:
        print(f"Error writing to log file: {exc}", file=sys.stderr)


def _signal_handler(signum, frame, sensor, log_fh):
    """Handle SIGINT/SIGTERM by closing resources and exiting."""
    print(f"\nReceived signal {signum}, shutting down...")
    sensor._running = False
    if log_fh is not None:
        try:
            log_fh.close()
        except Exception:
            pass
    sys.exit(0)


def main():
    sensor = None
    log_fh = None
    try:
        sensor = SoilMoistureSensor()
    except RuntimeError as exc:
        print(f"Fatal: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        log_fh = open(LOG_FILE, "w", newline="")
        writer = csv.writer(log_fh)
        writer.writerow(["timestamp", "moisture_percentage"])
        log_fh.flush()
    except OSError as exc:
        print(f"Fatal: cannot open log file {LOG_FILE}: {exc}", file=sys.stderr)
        sensor.close()
        sys.exit(1)

    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, sensor, log_fh))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, sensor, log_fh))

    try:
        for i in range(NUM_SAMPLES):
            if not sensor._running:
                break

            try:
                raw = sensor.read_adc(ADC_CHANNEL)
            except RuntimeError as exc:
                print(f"Sample {i}: SPI read error: {exc}", file=sys.stderr)
                log_reading(LOG_FILE, datetime.now(timezone.utc).isoformat(), "ERROR")
                time.sleep(SAMPLE_INTERVAL_S)
                continue

            # Detect sensor-absent / no-signal conditions
            if raw == 0 or raw == ADC_MAX_VALUE:
                print(f"Sample {i}: sensor absent or no signal (raw={raw})", file=sys.stderr)
                log_reading(LOG_FILE, datetime.now(timezone.utc).isoformat(), "N/A")
            else:
                percentage = sensor.convert_to_percentage(raw)
                log_reading(LOG_FILE, datetime.now(timezone.utc).isoformat(), percentage)
                mean, std = sensor.get_rolling_stats()
                print(f"Sample {i}: raw={raw}  moisture={percentage:.2f}%  "
                      f"mean={mean:.2f}  std={std:.2f}")

            time.sleep(SAMPLE_INTERVAL_S)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if log_fh is not None:
            try:
                log_fh.close()
            except Exception:
                pass
        sensor.close()


if __name__ == "__main__":
    main()

