            logging.error("Failed to open I2C bus %d: %s", self.i2c_bus_number, exc)
            raise

        try:
            self.adc = ADS1115(self.i2c_bus, address=0x48)
            self.adc.gain = 1
            self.adc.mode = ADS1115.MODE_CONTINUOUS
            logging.info("ADS1115 initialized (gain=1, continuous mode).")
        except Exception as exc:
            logging.error("Failed to initialize ADS1115: %s", exc)
            self.close()
            raise

        try:
            self.ch0 = AnalogIn(self.adc, ADS1115.P0)
            self.ch1 = AnalogIn(self.adc, ADS1115.P1)
            logging.info("AnalogIn objects created for channels 0 and 1.")
        except Exception as exc:
            logging.error("Failed to create AnalogIn objects: %s", exc)
            self.close()
            raise

        self.running = True
        logging.info("Oscilloscope initialized and running.")

    def read_channels(self) -> tuple[float, float]:
        """Read voltage values from channels 0 and 1."""
        if self.ch0 is None or self.ch1 is None:
            raise RuntimeError("AnalogIn objects not initialized.")
        return self.ch0.voltage, self.ch1.voltage

    def run(self) -> None:
        """Continuously sample and print ADC values until stopped."""
        if not self.running:
            logging.warning("run() called but Oscilloscope is not running.")
            return

        logging.info("Starting continuous sampling at %.1f Hz.", self.sample_rate_hz)

        try:
            while self.running:
                loop_start = time.monotonic()
                try:
                    ch0_v, ch1_v = self.read_channels()
                    print(f"{time.monotonic():.6f},{ch0_v:.4f},{ch1_v:.4f}")
                    sys.stdout.flush()
                except Exception as exc:
                    logging.error("Error reading ADC channels: %s", exc)
                elapsed = time.monotonic() - loop_start
                sleep_time = (1.0 / self.sample_rate_hz) - elapsed
                if sleep_time > 0:
                    time.sleep(sleep_time)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received. Stopping oscilloscope.")
        except Exception as exc:
            logging.error("Unexpected error in run loop: %s", exc)
        finally:
            self.stop()

    def stop(self) -> None:
        """Stop the sampling loop and release resources."""
        self.running = False
        self.close()

    def close(self) -> None:
        """Release ADC, channel, and I2C bus resources."""
        if self.ch0 is not None:
            try:
                self.ch0.deinit()
            except Exception as exc:
                logging.error("Error deinitializing ch0: %s", exc)
            self.ch0 = None
        if self.ch1 is not None:
            try:
                self.ch1.deinit()
            except Exception as exc:
                logging.error("Error deinitializing ch1: %s", exc)
            self.ch1 = None
        if self.adc is not None:
            try:
                self.adc = None
            except Exception as exc:
                logging.error("Error releasing ADC: %s", exc)
        if self.i2c_bus is not None:
            try:
                self.i2c_bus.close()
            except Exception as exc:
                logging.error("Error closing I2C bus: %s", exc)
            self.i2c_bus = None
        logging.info("Oscilloscope resources released.")


def main() -> None:
    osc = Oscilloscope(i2c_bus=1, sample_rate_hz=10.0)

    def signal_handler(signum, frame):
        logging.info("Signal %d received. Stopping oscilloscope.", signum)
        osc.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

