import argparse
import logging
import queue
import signal
import sys
import threading
import time

import spidev
import RPi.GPIO as GPIO

# Constants
DEFAULT_SAMPLE_RATE = 1000
DEFAULT_THRESHOLD = 500
DEFAULT_GPIO_PINS = [17, 27, 22]
DEFAULT_CHANNELS = [0, 1, 2]
DEFAULT_SPI_SPEED = 1000000
DEBOUNCE_DELAY = 0.1  # seconds


class SoundSensor:
    """
    Represents a sound sensor connected to a Raspberry Pi, supporting both
    digital (e.g. KY-038) and analog (via MCP3008 ADC) inputs.
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate,
                 gpio_pins, channels, spi_speed=DEFAULT_SPI_SPEED,
                 log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.last_state = None
        self.last_event_time = 0.0
        self.running = False
        self._lock = threading.Lock()

        self._setup_logging()
        self._setup_gpio()
        self._setup_spi()

    def _setup_logging(self):
        if self.log_queue:
            logging.basicConfig(
                level=logging.INFO,
                format='%(asctime)s - %(levelname)s - %(message)s',
                handlers=[
                    logging.StreamHandler(sys.stdout),
                    logging.handlers.QueueHandler(self.log_queue)
                ]
            )
        else:
            logging.basicConfig(
                level=logging.INFO,
                format='%(asctime)s - %(levelname)s - %(message)s'
            )

    def _setup_gpio(self):
        if self.sensor_type == 'digital':
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            for pin in self.gpio_pins:
                try:
                    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                except Exception as e:
                    logging.error(f"GPIO setup failed for pin {pin}: {e}")
                    raise

    def _setup_spi(self):
        if self.sensor_type == 'analog':
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                logging.error(f"SPI setup failed: {e}")
                raise

    def _read_mcp3008(self, channel):
        if not 0 <= channel <= 7:
            raise ValueError(f"Invalid MCP3008 channel: {channel}")
        if not self.spi:
            raise RuntimeError("SPI not initialized")
        try:
            # MCP3008 single-ended read: start bit, mode bit, channel bits
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"SPI read failed on channel {channel}: {e}")
            raise

    def _read_digital(self, pin):
        try:
            return GPIO.input(pin)
        except Exception as e:
            logging.error(f"GPIO read failed on pin {pin}: {e}")
            raise

    def _debounce(self, value):
        now = time.time()
        if value != self.last_state:
            self.last_state = value
            self.last_event_time = now
            return True
        if now - self.last_event_time < DEBOUNCE_DELAY:
            return False
        return True

    def _detect_event(self):
        if self.sensor_type == 'digital':
            for pin in self.gpio_pins:
                try:
                    value = self._read_digital(pin)
                    if value == 1 and self._debounce(value):
                        logging.info(
                            f"Sensor {self.sensor_id} (digital) "
                            f"on pin {pin} triggered event."
                        )
                        return True
                except Exception as e:
                    logging.error(f"Error reading digital sensor: {e}")
        elif self.sensor_type == 'analog':
            for channel in self.channels:
                try:
                    value = self._read_mcp3008(channel)
                    if value >= self.threshold and self._debounce(value):
                        logging.info(
                            f"Sensor {self.sensor_id} (analog) "
                            f"on channel {channel} triggered event "
                            f"(value={value})."
                        )
                        return True
                except Exception as e:
                    logging.error(f"Error reading analog sensor: {e}")
        return False

    def run(self):
        self.running = True
        self.last_state = None
        self.last_event_time = 0.0
        try:
            while self.running:
                try:
                    if self._detect_event():
                        if self.log_queue:
                            self.log_queue.put(
                                f"Sensor {self.sensor_id} event detected."
                            )
                except Exception as e:
                    logging.error(f"Error in sensor loop: {e}")
                time.sleep(1.0 / self.sample_rate)
        except KeyboardInterrupt:
            logging.info(f"Sensor {self.sensor_id} stopped by user.")
        finally:
            self.stop()

    def stop(self):
        with self._lock:
            if not self.running:
                return
            self.running = False
        if self.spi:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Error closing SPI: {e}")
        if self.sensor_type == 'digital':
            try:
                GPIO.cleanup(self.gpio_pins)
            except Exception as e:
                logging.error(f"Error cleaning up GPIO: {e}")

    def get_status(self):
        return {
            'sensor_id': self.sensor_id,
            'sensor_type': self.sensor_type,
            'threshold': self.threshold,
            'sample_rate': self.sample_rate,
            'gpio_pins': self.gpio_pins,
            'channels': self.channels,
            'spi_speed': self.spi_speed,
            'running': self.running,
        }


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Sound sensor monitoring program for Raspberry Pi."
    )
    parser.add_argument(
        "--sensor_type", required=True,
        choices=['digital', 'analog'],
        help="Type of sound sensor (digital or analog)."
    )
    parser.add_argument(
        "--threshold", type=int, default=DEFAULT_THRESHOLD,
        help="Threshold for analog sound sensor (0-1023)."
    )
    parser.add_argument(
        "--sample_rate", type=int, default=DEFAULT_SAMPLE_RATE,
        help="Sampling rate in Hz."
    )
    parser.add_argument(
        "--log_file", type=str,
        help="Path to the log file."
    )
    parser.add_argument(
        "--gpio_pins", type=int, nargs='+', default=DEFAULT_GPIO_PINS,
        help="GPIO pins for digital sound sensors (BCM numbering)."
    )
    parser.add_argument(
        "--channels", type=int, nargs='+', default=DEFAULT_CHANNELS,
        help="MCP3008 channels for analog sound sensors."
    )
    parser.add_argument(
        "--spi_speed", type=int, default=DEFAULT_SPI_SPEED,
        help="SPI speed in Hz."
    )
    parser.add_argument(
        "--sensor_ids", type=str, nargs='+', required=True,
        help="Unique identifiers for each sensor."
    )
    return parser.parse_args()


def main():
    args = parse_arguments()

    log_queue = None
    if args.log_file:
        log_queue = queue.Queue()
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            handlers=[
                logging.StreamHandler(sys.stdout),
                logging.handlers.QueueHandler(log_queue)
            ]
        )

    sensors = []
    for sensor_id in args.sensor_ids:
        try:
            sensor = SoundSensor(
                sensor_id,
                args.sensor_type,
                args.threshold,
                args.sample_rate,
                args.gpio_pins,
                args.channels,
                args.spi_speed,
                log_queue
            )
            sensors.append(sensor)
        except Exception as e:
            logging.error(f"Failed to initialize sensor {sensor_id}: {e}")
            continue

    if not sensors:
        logging.error("No sensors initialized. Exiting.")
        return

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run, daemon=True)
        threads.append(thread)
        thread.start()

    def signal_handler(signum, frame):
        logging.info(f"Received signal {signum}, shutting down.")
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join(timeout=2.0)
        if log_queue:
            while not log_queue.empty():
                try:
                    record = log_queue.get_nowait()
                    print(record)
                except queue.Empty:
                    break
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        signal_handler(signal.SIGINT, None)


if __name__ == "__main__":
    main()

