import time
import signal
import smbus2


class ADS1x15:
    """Minimal driver for an ADS1x15 (e.g. ADS1115) ADC on a Raspberry Pi.

    Supports single-ended channels 0-3 and PGA settings of 6144, 4096,
    2048, 1024, 512, or 256 mV.
    """

    # Register addresses (ADS1115 / ADS1015)
    REG_CONVERSION = 0x00
    REG_CONFIG = 0x01

    # Config register bit fields (ADS1115)
    CONFIG_OS_START = 0x8000
    CONFIG_OS_READY = 0x8000
    CONFIG_MUX_OFFSET = 12
    CONFIG_PGA_OFFSET = 9
    CONFIG_MODE_SINGLE = 0x0100
    CONFIG_DR_128SPS = 0x0080
    CONFIG_CQUE_NONE = 0x0003

    # PGA values in millivolts
    _PGA_MV = {
        6144: 0x0000,
        4096: 0x0200,
        2048: 0x0400,
        1024: 0x0600,
        512: 0x0800,
        256: 0x0A00,
    }

    def __init__(self, address=0x48, busnum=1):
        self.address = address
        self._bus = None
        try:
            self._bus = smbus2.SMBus(busnum)
        except OSError as exc:
            raise RuntimeError(
                f"Failed to open I2C bus {busnum} for ADS1x15 at 0x{address:02X}: {exc}"
            ) from exc

    def __del__(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except Exception:
                pass
            self._bus = None

    def _write_config(self, config_word):
        """Write a 16-bit config word to the ADS1x15 config register."""
        if self._bus is None:
            raise RuntimeError("I2C bus is not open")
        try:
            self._bus.write_word_data(self.address, self.REG_CONFIG, config_word)
        except OSError as exc:
            raise RuntimeError(
                f"I2C write to ADS1x15 config register failed: {exc}"
            ) from exc

    def _read_conversion(self):
        """Read the 16-bit conversion result from the ADS1x15."""
        if self._bus is None:
            raise RuntimeError("I2C bus is not open")
        try:
            raw = self._bus.read_word_data(self.address, self.REG_CONVERSION)
        except OSError as exc:
            raise RuntimeError(
                f"I2C read from ADS1x15 conversion register failed: {exc}"
            ) from exc
        # SMBus returns little-endian; ADS1x15 is big-endian.
        return ((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF)

    def read(self, channel, pga_mv):
        """Read a single-ended channel and return the voltage in millivolts.

        Args:
            channel: Single-ended channel 0-3.
            pga_mv:  PGA setting in millivolts (6144, 4096, 2048, 1024, 512, 256).

        Returns:
            float: Voltage in millivolts.

        Raises:
            ValueError: Invalid channel or PGA setting.
            RuntimeError: I2C communication failure.
        """
        if not 0 <= channel <= 3:
            raise ValueError(f"Invalid channel {channel}; must be 0-3.")
        if pga_mv not in self._PGA_MV:
            raise ValueError(
                f"Invalid PGA {pga_mv} mV; must be one of {list(self._PGA_MV.keys())}."
            )

        config = (
            self.CONFIG_OS_START
            | (channel << self.CONFIG_MUX_OFFSET)
            | self._PGA_MV[pga_mv]
            | self.CONFIG_MODE_SINGLE
            | self.CONFIG_DR_128SPS
            | self.CONFIG_CQUE_NONE
        )

        self._write_config(config)

        # Wait for the conversion to complete (OS bit clears).
        deadline = time.monotonic() + 0.1
        while True:
            status = self._read_config()
            if not (status & self.CONFIG_OS_READY):
                break
            if time.monotonic() > deadline:
                raise RuntimeError("ADS1x15 conversion did not complete within 100 ms.")
            time.sleep(0.001)

        raw = self._read_conversion()
        # Convert to signed 16-bit.
        if raw >= 0x8000:
            raw -= 0x10000
        return raw * (pga_mv / 32768.0)


# ---------------------------------------------------------------------------
# Signal handling for clean shutdown
# ---------------------------------------------------------------------------
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


if __name__ == "__main__":
    try:
        adc = ADS1x15(address=0x48, busnum=1)
        while _running:
            try:
                voltage_mv = adc.read(channel=0, pga_mv=6144)
                print(f"Channel 0 voltage: {voltage_mv:.3f} mV")
            except (ValueError, RuntimeError) as exc:
                print(f"Read error: {exc}")
            time.sleep(1.0)
    except RuntimeError as exc:
        print(f"Initialization error: {exc}")
    finally:
        print("Exiting.")

