import cv2
import signal
import sys
import time
from functools import partial

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2")
    sys.exit(1)

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def detect_faces_and_eyes(image, face_cascade, eye_cascade):
    """Detects faces and eyes in an image using Haar cascades."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(
        gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
    )
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (0, 255, 0), 2)
        roi_gray = gray[y : y + h, x : x + w]
        eyes = eye_cascade.detectMultiScale(
            roi_gray, scaleFactor=1.1, minNeighbors=3, minSize=(20, 20)
        )
        for (ex, ey, ew, eh) in eyes:
            cv2.rectangle(
                image, (x + ex, y + ey), (x + ex + ew, y + ey + eh), (0, 0, 255), 2
            )
    return image

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Load Haar cascade classifiers
    face_cascade_path = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
    eye_cascade_path = cv2.data.haarcascades + "haarcascade_eye.xml"

    try:
        face_cascade = cv2.CascadeClassifier(face_cascade_path)
        eye_cascade = cv2.CascadeClassifier(eye_cascade_path)
    except Exception as e:
        print(f"Error loading cascade classifiers: {e}")
        sys.exit(1)

    if face_cascade.empty() or eye_cascade.empty():
        print("Error: Could not load cascade classifiers. Check file paths.")
        sys.exit(1)

    # Initialize Picamera2
    picam2 = Picamera2()
    try:
        config = picam2.create_preview_configuration(
            main={"format": "BGR888", "size": (640, 480)}
        )
        picam2.configure(config)
        picam2.start()
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

    try:
        while _running:
            try:
                image = picam2.capture_array()
            except Exception as e:
                print(f"Error capturing frame: {e}")
                time.sleep(0.1)
                continue

            if image is None:
                print("Warning: Captured frame is None, skipping.")
                continue

            processed_image = detect_faces_and_eyes(image, face_cascade, eye_cascade)
            cv2.imshow("Face and Eye Detection", processed_image)

            if cv2.waitKey(1) & 0xFF == ord("q"):
                break
    finally:
        try:
            picam2.stop()
        except Exception:
            pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

