        led.off()
    except Exception as e:
        print(f"Error controlling LED: {e}")
        traceback.print_exc()


def control_feeder_door(state):
    if door is None:
        return
    try:
        if state:
            door.on()
        else:
            door.off()
    except Exception as e:
        print(f"Error controlling feeder door: {e}")
        traceback.print_exc()


def cleanup(signum=None, frame=None):
    global running, picam2, led, door
    running = False
    print("\nCleaning up resources...")
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if door is not None:
        try:
            door.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


