    config = load_config()
    if config is None:
        return

    if config.get("gpio_door_control"):
        if OutputDevice is None:
            print("Warning: gpiozero not installed; door control disabled.")
        else:
            try:
                door = OutputDevice(config["gpio_door_control"])
            except Exception as e:
                print(f"Error initializing door GPIO: {e}")
                traceback.print_exc()
                door = None

