# Configure logging
logging.basicConfig(
    filename='error.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
I2C_BUS = 1
DATABASE_NAME = 'wildlife_data.db'
CONFIG_FILE = 'config.txt'
VALID_PRESSURE_MIN = 70000
VALID_PRESSURE_MAX = 110000
VALID_TEMPERATURE_MIN = -20
VALID_TEMPERATURE_MAX = 50
VALID_HUMIDITY_MIN = 0
VALID_HUMIDITY_MAX = 100

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)

def load_config(config_file):
    """Loads configuration parameters from the specified file."""
    config = {}
    try:
        with open(config_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    if '=' in line:
                        key, value = line.split('=', 1)
                        config[key.strip()] = value.strip()
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
    except Exception as e:
        logging.error(f"Error reading configuration file: {e}")
    return config

def initialize_database(db_name):
    """Initializes the SQLite database and creates the sensor_data table if it doesn't exist."""
    try:
        conn = sqlite3.connect(db_name)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        ''')
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error(f"Database initialization error: {e}")
        raise

def read_bmp280_data(i2c_bus, sensor_id, sampling_interval):
    """Reads data from a BMP280 sensor."""
    try:
        import smbus2
        bus = smbus2.SMBus(i2c_bus)
        # BMP280 I2C address is typically 0x76 or 0x77
        # This is a simplified example; real implementation would use a library like adafruit-bme280
        # For the sake of this example, we simulate data
        time.sleep(sampling_interval)
        return 100000, 25.0, None
    except Exception as e:
        logging.error(f"Error reading BMP280 data (sensor_id={sensor_id}): {e}")
        return None, None, None

def read_bme280_data(i2c_bus, sensor_id, sampling_interval):
    """Reads data from a BME280 sensor."""
    try:
        import smbus2
        bus = smbus2.SMBus(i2c_bus)
        # BME280 I2C address is typically 0x76 or 0x77
        # This is a simplified example; real implementation would use a library like adafruit-bme280
        # For the sake of this example, we simulate data
