import time
import signal
import sys
import random
import smbus2
from gpiozero import Buzzer

# Constants
I2C_BUS = 1
AMG8833_ADDR = 0x39
BUZZER_PIN = 17
HUMAN_THRESHOLD = 30.0
POLL_INTERVAL = 0.1

# Global resources for cleanup
buzzer = None
i2c_bus = None
running = True

def signal_handler(signum, frame):
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False

def init_sensor():
    global i2c_bus
    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
        # Verify sensor presence by reading the device ID register (0x00)
        dev_id = i2c_bus.read_byte_data(AMG8833_ADDR, 0x00)
        if dev_id != 0x41:
            print(f"Warning: Unexpected AMG8833 device ID 0x{dev_id:02X}, expected 0x41")
        return True
    except Exception as e:
        print(f"Error initializing I2C bus or AMG8833: {e}")
        return False

def read_thermal_data():
    global i2c_bus
    if i2c_bus is None:
        return None
    try:
        # Read 64 bytes starting at register 0x80 (pixel data)
        data = i2c_bus.read_i2c_block_data(AMG8833_ADDR, 0x80, 64)
        if len(data) != 64:
            print("Error: Incomplete thermal data read")
            return None
        # Convert 16-bit little-endian values to Celsius
        thermal_data = []
        for i in range(0, 64, 2):
            raw = data[i] | (data[i+1] << 8)
            # Convert to signed 16-bit and scale (0.25°C per LSB)
            temp = (raw >> 4) * 0.25
            if raw & 0x0800:
                temp -= 64.0
            thermal_data.append(temp)
        return thermal_data
    except Exception as e:
        print(f"Error reading thermal data: {e}")
        return None

def detect_human(thermal_data):
    if thermal_data is None:
        return False
    for temp in thermal_data:
        if temp > HUMAN_THRESHOLD:
            return True
    return False

def trigger_alert(buzzer_obj):
    if buzzer_obj is None:
        return
    try:
        buzzer_obj.on()
        time.sleep(1)
        buzzer_obj.off()
    except Exception as e:
        print(f"Error triggering alert: {e}")

def cleanup():
    global buzzer, i2c_bus
    print("Cleaning up resources...")
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
    print("Cleanup complete.")

def main():
    global buzzer, running
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Error initializing buzzer on GPIO{BUZZER_PIN}: {e}")
        sys.exit(1)

    # Initialize sensor
    if not init_sensor():
        print("Sensor initialization failed. Simulating thermal data.")
        i2c_bus = None

    print("Thermal camera monitoring started. Press Ctrl+C to exit.")

    try:
        while running:
            thermal_data = read_thermal_data()
            if thermal_data is None:
                # Simulate data on I2C error
                thermal_data = [random.uniform(20.0, 45.0) for _ in range(64)]

            if detect_human(thermal_data):
                print("Human detected! Triggering alert.")
                trigger_alert(buzzer)
            else:
                print("No human detected.")

            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

