import signal
import sys
import cv2
import numpy as np
from pyzbar.pyzbar import decode as qr_decode

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initializes the Raspberry Pi camera using the CSI driver library."""
    try:
        import libcamera
        from picamera2 import Picamera2
        picam2 = Picamera2()
        config = picam2.create_still_configuration(
            main={"size": (64, 64), "format": "RGB888"}
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(camera):
    """Captures a single image from the camera."""
    try:
        return camera.capture_array()
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def decode_qr_code(image):
    """Decodes a QR code from the given image."""
    try:
        gray = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
        decoded_objects = qr_decode(gray)
        return bool(decoded_objects), decoded_objects
    except Exception as e:
        print(f"Error decoding QR code: {e}")
        return False, None

def release_camera(camera):
    """Releases the camera resources."""
    if camera is not None:
        try:
            camera.stop()
        except Exception:
            pass

def main():
    """Main function to capture an image and decode a QR code."""
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = initialize_camera()
    if not _running:
        return

    if camera is None:
        print("Camera initialization failed. Exiting.")
        return

    try:
        image = capture_image(camera)
        if not _running:
            return

        if image is None:
            print("Image capture failed. Exiting.")
            return

        qr_detected, decoded_objects = decode_qr_code(image)

        if qr_detected:
            print("Hello, World!")
        else:
            print("No QR code detected.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        release_camera(camera)

if __name__ == "__main__":
    main()

