import signal
import sys
import time
import board
import busio
import digitalio

try:
    import adafruit_bme280
except ImportError:
    print("Missing dependency: adafruit_bme280", file=sys.stderr)
    sys.exit(1)

try:
    from adafruit_epd.il0373 import IL0373
except ImportError:
    print("Missing dependency: adafruit_epd", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
SPI_SCK_PIN = board.SCK
SPI_MOSI_PIN = board.MOSI
SPI_MISO_PIN = board.MISO

BME280_CS_PIN = board.D7   # GPIO7 (CE1) – BME280 chip select
BME280_SCK_PIN = board.SCK # GPIO11 (BCM)
BME280_MOSI_PIN = board.MOSI
BME280_MISO_PIN = board.MISO

EPD_CS_PIN = board.D5      # GPIO5 (BCM)
EPD_DC_PIN = board.D6      # GPIO6 (BCM)
EPD_RESET_PIN = board.D9   # GPIO9 (BCM)
EPD_BUSY_PIN = board.D10   # GPIO10 (BCM)

EPD_WIDTH = 128
EPD_HEIGHT = 296
REFRESH_INTERVAL = 60

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
spi_bus = None
bme280_sensor = None
epd_display = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global spi_bus, bme280_sensor, epd_display
    if epd_display is not None:
        try:
            epd_display.sleep()
        except Exception:
            pass
    for dev in (bme280_sensor,):
        if dev is not None:
            try:
                dev.deinit()
            except Exception:
                pass
    for dev in (epd_display,):
        if dev is not None:
            try:
                dev.deinit()
            except Exception:
                pass
    for dev in (bme280_sensor, epd_display):
        if dev is not None:
            try:
                dev.__del__()
            except Exception:
                pass
    for dev in (bme280_sensor, epd_display):
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass


def _init_spi():
    global spi_bus
    try:
        spi_bus = busio.SPI(SPI_SCK_PIN, MOSI=SPI_MOSI_PIN, MISO=SPI_MISO_PIN)
        while not spi_bus.try_lock():
            time.sleep(0.01)
        spi_bus.configure(baudrate=1000000, phase=0, polarity=0)
        spi_bus.unlock()
        return spi_bus
    except Exception as exc:
        print(f"SPI init failed: {exc}", file=sys.stderr)
        return None


def _init_bme280():
    global bme280_sensor
    try:
        cs = digitalio.DigitalInOut(BME280_CS_PIN)
        cs.direction = digitalio.Direction.OUTPUT
        cs.value = True
        bme280_sensor = adafruit_bme280.Adafruit_BME280_SPI(spi_bus, cs)
        return bme280_sensor
    except (RuntimeError, ValueError, OSError) as exc:
        print(f"BME280 init failed: {exc}", file=sys.stderr)
        bme280_sensor = None
        return None
    except Exception as exc:
        print(f"BME280 init unexpected error: {exc}", file=sys.stderr)
        bme280_sensor = None
        return None


def _init_epd():
    global epd_display
    try:
        cs = digitalio.DigitalInOut(EPD_CS_PIN)
        dc = digitalio.DigitalInOut(EPD_DC_PIN)
        reset = digitalio.DigitalInOut(EPD_RESET_PIN)
        busy = digitalio.DigitalInOut(EPD_BUSY_PIN)
        epd_display = IL0373(
            3.3,
            EPD_WIDTH,
            EPD_HEIGHT,
            cs,
            dc,
            reset,
            busy,
            spi_bus,
        )
        return epd_display
    except Exception as exc:
        print(f"e-paper init failed: {exc}", file=sys.stderr)
        epd_display = None
        return None


def _read_bme280():
    if bme280_sensor is None:
        return None, None, None
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        pressure = bme280_sensor.pressure
        if temperature is None or humidity is None or pressure is None:
            return None, None, None
        return temperature, humidity, pressure
    except (RuntimeError, ValueError, OSError) as exc:
        print(f"BME280 read error: {exc}", file=sys.stderr)
        return None, None, None
    except Exception as exc:
        print(f"BME280 read unexpected error: {exc}", file=sys.stderr)
        return None, None, None


def _update_display(temperature, humidity, pressure):
    if epd_display is None:
        return
    try:
        epd_display.fill(0)
        epd_display.text(f"Temp: {temperature:.1f} C", 0, 0, 1)
        epd_display.text(f"Hum: {humidity:.1f} %", 0, 20, 1)
        epd_display.text(f"Pres: {pressure:.1f} hPa", 0, 40, 1)
        epd_display.display()
    except Exception as exc:
        print(f"Display update error: {exc}", file=sys.stderr)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    spi_bus = _init_spi()
    if spi_bus is None:
        _cleanup()
        sys.exit(1)

    bme280_sensor = _init_bme280()
    if bme280_sensor is None:
        _cleanup()
        sys.exit(1)

    epd_display = _init_epd()
    if epd_display is None:
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            temperature, humidity, pressure = _read_bme280()
            if temperature is not None and humidity is not None and pressure is not None:
                _update_display(temperature, humidity, pressure)
            else:
                print("Sensor data unavailable; skipping display update.")
            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < REFRESH_INTERVAL:
                time.sleep(1)
                slept += 1
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

