import argparse
import json
import logging
import os
import queue
import signal
import sys
import threading
import time
from datetime import datetime

import cv2
import numpy as np
from picamera2 import Picamera2
from tflite_runtime.interpreter import Interpreter

GESTURES = ["Open Hand", "Closed Fist", "Pointing Up", "Pointing Down", "Peace Sign"]
CONFIDENCE_THRESHOLD = 0.7
SIMULATION_DELAY = 2.0
CLOUD_DATA_FILE = "cloud_data.json"
LOG_FILE = "smart_home.log"

running = True
last_gesture_time = 0.0
last_accepted_gesture = None
light = False
thermostat = 22
tv = False
gesture_queue = queue.Queue(maxsize=10)
state_lock = threading.Lock()

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
console_handler = logging.StreamHandler()
console_handler.setLevel(logging.INFO)
console_handler.setFormatter(logging.Formatter("%(asctime)s - %(levelname)s - %(message)s"))
logging.getLogger().addHandler(console_handler)


def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def load_model(model_path):
    if not os.path.isfile(model_path):
        logging.error(f"Model file not found: {model_path}")
        return None
    try:
        interpreter = Interpreter(model_path=model_path)
        interpreter.allocate_tensors()
        logging.info("TensorFlow Lite model loaded successfully.")
        return interpreter
    except Exception as e:
        logging.error(f"Error loading TensorFlow Lite model: {e}")
        return None


def preprocess_frame(frame):
    try:
        resized = cv2.resize(frame, (224, 224))
        rgb = cv2.cvtColor(resized, cv2.COLOR_BGR2RGB)
        input_data = np.expand_dims(rgb, axis=0)
        return input_data
    except Exception as e:
        logging.error(f"Error preprocessing frame: {e}")
        return None


def run_inference(interpreter, input_data):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        interpreter.set_tensor(input_details[0]["index"], input_data)
        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]["index"])
        return output_data[0]
    except Exception as e:
        logging.error(f"Error running inference: {e}")
        return None


def recognize_gesture(output_data):
    try:
        scores = output_data
        predicted_idx = int(np.argmax(scores))
        if predicted_idx < len(GESTURES) and scores[predicted_idx] > CONFIDENCE_THRESHOLD:
            return GESTURES[predicted_idx], float(scores[predicted_idx])
        return None, None
    except Exception as e:
        logging.error(f"Error recognizing gesture: {e}")
        return None, None


def control_smart_home(gesture):
    global light, thermostat, tv
    with state_lock:
        if gesture == "Open Hand":
            light = not light
        elif gesture == "Closed Fist":
            light = False
        elif gesture == "Pointing Up":
            thermostat = min(30, thermostat + 1)
        elif gesture == "Pointing Down":
            thermostat = max(15, thermostat - 1)
        elif gesture == "Peace Sign":
            tv = not tv
        logging.info(f"Smart Home State: Light={light}, Thermostat={thermostat}, TV={tv}")


def capture_frames(picam2, frame_queue):
    global running
    try:
        picam2.start()
        logging.info("Camera started successfully.")
    except Exception as e:
        logging.error(f"Error starting camera: {e}")
        running = False
        return
    while running:
        try:
            frame = picam2.capture_array()
            if frame is None:
                logging.warning("Captured empty frame.")
                continue
            if frame_queue.full():
                try:
                    frame_queue.get_nowait()
                except queue.Empty:
                    pass
            frame_queue.put(frame)
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            time.sleep(0.1)
    try:
        picam2.stop()
    except Exception as e:
        logging.error(f"Error stopping camera: {e}")


def process_frames(interpreter, frame_queue, gesture_queue):
    global running, last_gesture_time, last_accepted_gesture
    while running:
        try:
            frame = frame_queue.get(timeout=1.0)
        except queue.Empty:
            continue
        if frame is None:
            continue
        try:
            input_data = preprocess_frame(frame)
            if input_data is None:
                continue
            output_data = run_inference(interpreter, input_data)
            if output_data is None:
                continue
            gesture, confidence = recognize_gesture(output_data)
            if gesture:
                current_time = time.time()
                if current_time - last_gesture_time > SIMULATION_DELAY:
                    last_gesture_time = current_time
                    last_accepted_gesture = gesture
                    gesture_queue.put((gesture, confidence))
                else:
                    logging.debug("Gesture detected but ignored due to rate limiting.")
        except Exception as e:
            logging.error(f"Error processing frame: {e}")


def log_to_cloud(gesture_queue):
    global running, last_accepted_gesture
    while running:
        try:
            gesture, confidence = gesture_queue.get(timeout=1.0)
        except queue.Empty:
            continue
        if gesture is None:
            continue
        with state_lock:
            current_state = {
                "light": light,
                "thermostat": thermostat,
                "tv": tv,
            }
        timestamp = datetime.now().isoformat()
        user_id = "user_123"
        data = {
            "timestamp": timestamp,
            "user_id": user_id,
            "gesture": gesture,
            "state": current_state,
        }
        try:
            with open(CLOUD_DATA_FILE, "a") as f:
                f.write(json.dumps(data) + "\n")
            logging.info(f"Logged to cloud: {data}")
        except Exception as e:
            logging.error(f"Error writing to cloud data file: {e}")


def main():
    global running, last_gesture_time, last_accepted_gesture
    parser = argparse.ArgumentParser(description="Gesture-Controlled Smart Home System")
    parser.add_argument(
        "--model_path",
        default="gesture_model_quantized.tflite",
        help="Path to the TensorFlow Lite model file",
    )
    parser.add_argument(
        "--camera_resolution",
        default="64",
        help="Camera resolution (e.g., 64 for 640x480)",
    )
    args = parser.parse_args()

    interpreter = load_model(args.model_path)
    if interpreter is None:
        logging.error("Failed to load model. Exiting.")
        sys.exit(0)

    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        picam2.configure(config)
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        running = False
        sys.exit(0)

    capture_thread = threading.Thread(target=capture_frames, args=(picam2, gesture_queue))
    inference_thread = threading.Thread(target=process_frames, args=(interpreter, gesture_queue, gesture_queue))
    cloud_thread = threading.Thread(target=log_to_cloud, args=(gesture_queue,))

    capture_thread.daemon = True
    inference_thread.daemon = True
    cloud_thread.daemon = True

    capture_thread.start()
    inference_thread.start()
    cloud_thread.start()

    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    try:
        while running:
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt received.")
    finally:
        running = False
        capture_thread.join(timeout=2.0)
        inference_thread.join(timeout=2.0)
        cloud_thread.join(timeout=2.0)
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

