import cv2
import numpy as np
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotionDetector:
    def __init__(self, camera_index=0, blur_size=3, mse_threshold=100.0):
        self.camera_index = camera_index
        self.blur_size = blur_size
        self.mse_threshold = mse_threshold
        self.cap = None
        self.running = False

    def initialize_camera(self):
        self.cap = cv2.VideoCapture(self.camera_index)
        if not self.cap.isOpened():
            logging.error(f"Could not open camera at index {self.camera_index}")
            return False
        return True

    def process_frame(self, frame):
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        blurred = cv2.GaussianBlur(gray, (self.blur_size, self.blur_size), 0)
        compensated = self._light_compensation(blurred)
        return compensated, gray

    def _light_compensation(self, img):
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
        return clahe.apply(img)

    def detect_motion(self, current, previous):
        if previous is None:
            return False
        diff = current.astype(np.float32) - previous.astype(np.float32)
        mse = np.mean(diff ** 2)
        return mse > self.mse_threshold

    def run(self):
        if not self.initialize_camera():
            return

        self.running = True
        previous_gray = None

        try:
            while self.running:
                ret, frame = self.cap.read()
                if not ret:
                    logging.error("Failed to grab frame")
                    break

                compensated, gray = self.process_frame(frame)

                if self.detect_motion(gray, previous_gray):
                    logging.info("Motion Detected using MSE!")

                cv2.imshow('Original', frame)
                cv2.imshow('Compensated', compensated)
                cv2.imshow('Grayscale', gray)
                cv2.imshow('Edges', cv2.Canny(gray, 100, 200))

                key = cv2.waitKey(1) & 0xFF
                if key == 27:
                    break

                previous_gray = gray

        except Exception as e:
            logging.error(f"An error occurred: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.cap is not None and self.cap.isOpened():
            self.cap.release()
        cv2.destroyAllWindows()

    def stop(self):
        self.running = False

def main():
    detector = MotionDetector(camera_index=0, blur_size=3, mse_threshold=100.0)

    def signal_handler(sig, frame):
        logging.info("Interrupt received, stopping...")
        detector.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    detector.run()

if __name__ == "__main__":
    main()

