import atexit
import signal
import threading
import time
import logging
import os
import sys
import traceback
from typing import Optional, Tuple, Callable, Any

from flask import Flask, render_template, Response, request, redirect, url_for

from camera import Camera
from mail_config import send_email
from mail_config import send_email_with_image as send_email_with_image_func
from mail_config import send_email_with_image_and_text as send_email_with_image_and_text_func
from mail_config import send_email_with_text as send_email_with_text_func

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

app = Flask(__name__)
shutdown_event = threading.Event()
current_classifier = "motion_detector"
preview_enabled = False
email_notifications_enabled = False
email_recipient = ""
email_interval = 60
last_email_send_time = 0.0
camera: Optional[Camera] = None
detection_thread: Optional[threading.Thread] = None
detection_lock = threading.Lock()

try:
    camera = Camera()
    camera.set_flip(True)
    camera.set_resolution(320, 240)
    camera.set_quality(64)
    camera.set_rotation(180)
    logger.info("Camera initialized successfully.")
except Exception as e:
    logger.error(f"Failed to initialize camera: {e}")
    sys.exit(1)

def get_object_with_basic_motion_detection() -> Tuple[bytes, bool]:
    try:
        image, detected = camera.detect_motion()
        return image, detected
    except Exception as e:
        logger.error(f"Error during motion detection: {e}")
        return b"", False

def get_object(classifier: str) -> bytes:
    try:
        if classifier == "motion_detector":
            image, _ = get_object_with_basic_motion_detection()
            return image
        else:
            image, _ = camera.get_object(classifier)
            return image
    except Exception as e:
        logger.error(f"Error during object detection with classifier '{classifier}': {e}")
        return b""

def check_for_objects() -> None:
    global last_email_send_time, email_notifications_enabled, email_recipient, email_interval, current_classifier

    while not shutdown_event.is_set():
        try:
            if email_notifications_enabled and (time.time() - last_email_send_time) >= email_interval:
                with detection_lock:
                    image_data = get_object(current_classifier)

                if image_data:
                    try:
                        if current_classifier == "text":
                            send_email_with_text_func(email_recipient, "Object Detected", "Text detected!")
                        elif current_classifier == "image":
                            send_email_with_image_func(email_recipient, "Object Detected", "Image detected!", image_data)
                        elif current_classifier == "image_and_text":
                            send_email_with_image_and_text_func(email_recipient, "Object Detected", "Both image and text detected!", image_data)
                        else:
                            send_email(email_recipient, "Object Detected", "Object detected!")
                        last_email_send_time = time.time()
                        logger.info("Email notification sent successfully.")
                    except Exception as e:
                        logger.error(f"Error sending email: {e}")
                else:
                    logger.warning("No image data received for email notification.")
        except Exception as e:
            logger.error(f"Error in object detection thread: {e}")

        shutdown_event.wait(1.0)

@app.route('/', methods=['GET', 'POST'])
def index() -> str:
    global current_classifier, preview_enabled, email_notifications_enabled, email_recipient, email_interval

    if request.method == 'POST':
        try:
            current_classifier = request.form.get('classifier', 'motion_detector')
            preview_enabled = 'preview' in request.form
            email_notifications_enabled = 'email_notifications' in request.form
            email_recipient = request.form.get('email_recipient', '').strip()
            try:
                email_interval = int(request.form.get('email_interval', 60))
            except ValueError:
                email_interval = 60

            logger.info(f"Classifier: {current_classifier}, Preview: {preview_enabled}, Email: {email_notifications_enabled}, Recipient: {email_recipient}, Interval: {email_interval}")
        except Exception as e:
            logger.error(f"Error processing form data: {e}")

    return render_template('index.html',
                           classifiers=["text", "image", "image_and_text", "motion_detector"],
                           current_classifier=current_classifier,
                           preview_enabled=preview_enabled,
                           email_notifications_enabled=email_notifications_enabled,
                           email_recipient=email_recipient,
                           email_interval=email_interval)

def generate_stream(camera: Camera, classifier: str) -> bytes:
    while not shutdown_event.is_set():
        try:
            image_data = get_object(classifier)
            if image_data:
                yield (b'--frame\r\n'
                       b'Content-Type: image/jpeg\r\n\r\n' + image_data + b'\r\n\r\n')
            else:
                time.sleep(0.1)
        except Exception as e:
            logger.error(f"Error generating stream: {e}")
            time.sleep(0.1)

@app.route('/video_feed')
def video_feed() -> Response:
    return Response(generate_stream(camera, current_classifier),
                    mimetype='multipart/x-mixed-replace; boundary=frame')

def cleanup() -> None:
    global camera, detection_thread
    logger.info("Cleaning up resources...")
    shutdown_event.set()
    if detection_thread and detection_thread.is_alive():
        detection_thread.join(timeout=5.0)
    if camera:
        try:
            camera.stop()
        except Exception as e:
            logger.error(f"Error stopping camera: {e}")
    logger.info("Cleanup complete.")

if __name__ == '__main__':
    atexit.register(cleanup)

    def signal_handler(signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        detection_thread = threading.Thread(target=check_for_objects, daemon=True)
        detection_thread.start()
        app.run(host='0.0.0.0', debug=False, threaded=True)
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
        logger.debug(traceback.format_exc())
    finally:
        cleanup()

