import signal
import sys
import time
from collections import deque

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except Exception:
    _GPIO_AVAILABLE = False

DEFAULT_CONFIG = {
    "sensor1": {"trigger": 17, "echo": 18, "offset": 0.0, "max_distance": 200.0},
    "sensor2": {"trigger": 22, "echo": 23, "offset": 0.0, "max_distance": 200.0},
    "sensor3": {"trigger": 24, "echo": 25, "offset": 0.0, "max_distance": 200.0},
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Configuration file '{config_file}' not found. Using defaults.")
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from '{config_file}': {e}. Using defaults.")
    return DEFAULT_CONFIG.copy()


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def initialize_gpio(sensors):
    if not _GPIO_AVAILABLE:
        logging.warning("RPi.GPIO not available. Running in simulation mode.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        for sensor in sensors.values():
            GPIO.setup(sensor["trigger"], GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(sensor["echo"], GPIO.IN)
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        raise


def read_distance(trigger_pin, echo_pin, timeout_ms=50):
    try:
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, GPIO.LOW)

        pulse_start = time.time()
        timeout = time.time() + (timeout_ms / 1000.0)
        while GPIO.input(echo_pin) == 0:
            if time.time() > timeout:
                return None
            pulse_start = time.time()

        pulse_end = time.time()
        timeout = time.time() + (timeout_ms / 1000.0)
        while GPIO.input(echo_pin) == 1:
            if time.time() > timeout:
                return None
            pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150
        return round(distance, 2)
    except Exception as e:
        logging.error(f"Error reading distance from trigger {trigger_pin}, echo {echo_pin}: {e}")
        return None


def calculate_median(data):
    if not data:
        return None
    sorted_data = sorted(data)
    n = len(sorted_data)
    if n % 2 == 1:
        return sorted_data[n // 2]
    else:
        return (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2.0


