import signal
import sys
import time
import random
import logging
import os
import speech_recognition as sr
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT_PIN = 4
LIGHT_PIN = 17
WAKE_WORD = "Greenhouse"
LISTEN_TIMEOUT = 5
TEMP_MIN = 15
TEMP_MAX = 35

running = True

def signal_handler(sig, frame):
    global running
    logging.info("Termination signal received. Cleaning up...")
    running = False

def simulate_gpio_init():
    logging.warning("Simulating GPIO initialization (no real GPIO hardware detected).")
    return {'out': {}}

def simulate_gpio_set(pin, state):
    logging.info(f"Simulated GPIO set pin {pin} to {'HIGH' if state else 'LOW'}")

def simulate_gpio_cleanup():
    logging.info("Simulating GPIO cleanup.")

def read_temperature():
    try:
        import adafruit_dht
        import board
        dht_device = adafruit_dht.DHT11(board.D4)
        temperature = dht_device.temperature
        if temperature is None:
            logging.warning("DHT11 returned None temperature.")
            return None
        return temperature
    except ImportError:
        logging.warning("adafruit-circuitpython-dht not installed. Simulating temperature.")
        return random.uniform(TEMP_MIN, TEMP_MAX)
    except Exception as e:
        logging.error(f"Error reading temperature: {e}. Simulating.")
        return random.uniform(TEMP_MIN, TEMP_MAX)

def control_lights(state):
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT)
        GPIO.output(LIGHT_PIN, GPIO.HIGH if state else GPIO.LOW)
        logging.info(f"Lights turned {'on' if state else 'off'}")
    except ImportError:
        logging.warning("RPi.GPIO not installed. Simulating light control.")
        simulate_gpio_set(LIGHT_PIN, state)
    except Exception as e:
        logging.error(f"Error controlling lights: {e}. Simulating.")
        simulate_gpio_set(LIGHT_PIN, state)

def take_picture(picam2):
    try:
        timestamp = int(time.time() * 1000)
        filename = f"greenhouse_{timestamp}.jpg"
        picam2.capture_file(filename)
        logging.info(f"Picture saved as {filename}")
        return filename
    except Exception as e:
        logging.error(f"Error taking picture: {e}")
        return None

def process_command(command):
    if "turn on the lights" in command:
        control_lights(True)
    elif "turn off the lights" in command:
        control_lights(False)
    elif "what is the temperature" in command:
        temperature = read_temperature()
        if temperature is not None:
            logging.info(f"Temperature is {temperature:.1f} degrees Celsius")
        else:
            logging.warning("Could not read temperature.")
    elif "take a picture" in command:
        picam2 = Picamera2()
        try:
            picam2.start()
            take_picture(picam2)
            picam2.stop()
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
        finally:
            try:
                picam2.close()
            except Exception:
                pass
    else:
        logging.info(f"Unknown command: {command}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT)
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        logging.info("GPIO initialized successfully.")
    except ImportError:
        logging.warning("RPi.GPIO not installed. Simulating GPIO.")
        GPIO = simulate_gpio_init()
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}. Simulating GPIO.")
        GPIO = simulate_gpio_init()

    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_still_configuration())
        picam2.start()
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.warning(f"Camera not available: {e}. Pictures will not be taken.")
        picam2 = None

    r = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            logging.info("Say 'Greenhouse' to start...")
            r.adjust_for_ambient_noise(source, duration=1)
            while running:
                try:
                    audio = r.listen(source, timeout=LISTEN_TIMEOUT)
                    text = r.recognize_google(audio)
                    logging.info(f"You said: {text}")
                    if WAKE_WORD in text.lower():
                        logging.info("Wake word detected!")
                        process_command(text)
                    else:
                        logging.info("Command not recognized.")
                except sr.WaitTimeoutError:
                    pass
                except sr.UnknownValueError:
                    logging.warning("Could not understand audio")
                except sr.RequestError as e:
                    logging.error(f"Could not request results from Google Speech Recognition service; {e}")
    except Exception as e:
        logging.error(f"Microphone error: {e}")
    finally:
        logging.info("Cleaning up...")
        if picam2:
            try:
                picam2.stop()
                picam2.close()
            except Exception:
                pass
        try:
            GPIO.cleanup()
        except Exception:
            simulate_gpio_cleanup()
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

