import sys
import time
import signal
import cv2
import config
import hardware
from picamera2 import Picamera2

running = True

def _signal_handler(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)

    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(
            main={"format": 'XRGB8888', "size": (64, 64)}
        ))
        picam2.start()
    except Exception as e:
        print(f"Failed to initialize camera: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        recognizer = cv2.face.EigenFaceRecognizer_create()
        recognizer.read(config.TRAINING_FILE)
    except Exception as e:
        print(f"Failed to load training data: {e}", file=sys.stderr)
        picam2.stop()
        sys.exit(1)

    try:
        box = hardware.Box()
        box.lock()
    except Exception as e:
        print(f"Failed to initialize box hardware: {e}", file=sys.stderr)
        picam2.stop()
        sys.exit(1)

    cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    face_cascade = cv2.CascadeClassifier(cascade_path)
    if face_cascade.empty():
        print("Failed to load Haar cascade classifier.", file=sys.stderr)
        box.lock()
        picam2.stop()
        sys.exit(1)

    try:
        while running:
            try:
                if box.is_button_up():
                    try:
                        image = picam2.capture_array()
                    except Exception as e:
                        print(f"Capture error: {e}", file=sys.stderr)
                        time.sleep(0.1)
                        continue

                    if image is None:
                        time.sleep(0.1)
                        continue

                    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
                    faces = face_cascade.detectMultiScale(gray, 1.3, 5)

                    if len(faces) > 0:
                        x, y, w, h = faces[0]
                        cropped = gray[y:y + h, x:x + w]
                        resized = cv2.resize(cropped, (10, 10))

                        try:
                            l, conf = recognizer.predict(resized)
                        except Exception as e:
                            print(f"Recognition error: {e}", file=sys.stderr)
                            time.sleep(0.1)
                            continue

                        if l == config.POSITIVE_LABEL and 1500 < conf < config.POSITIVE_THRESHOLD:
                            if not box.is_locked():
                                box.lock()
                            print("Recognized face! Box is now locked.")
                        else:
                            if not box.is_locked():
                                box.lock()
                            print("Face not recognized. Box is now locked.")

            except Exception as e:
                print(f"Error during loop: {e}", file=sys.stderr)

            time.sleep(0.1)

    finally:
        try:
            box.lock()
        except Exception:
            pass
        try:
            picam2.stop()
        except Exception:
            pass

if __name__ == "__main__":
    main()

