import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def setup_gpio():
    GPIO.setmode(GPIO.BCM)
