import io
import os
import time
import signal
import logging
import threading
from datetime import datetime

try:
    from picamera2 import Picamera2
except ImportError:
    logging.error("picamera2 library is required. Install with: pip install picamera2")
    raise

try:
    from PIL import Image, ImageChops, ImageOps
except ImportError:
    logging.error("Pillow library is required. Install with: pip install Pillow")
    raise

try:
    import numpy as np
except ImportError:
    logging.error("numpy library is required. Install with: pip install numpy")
    raise

try:
    import configparser
except ImportError:
    logging.error("configparser library is required. Install with: pip install configparser")
    raise

CONFIG_FILE = "config.txt"
DEFAULT_CONFIG = {
    "camera": {
        "resolution_width": "640",
        "resolution_height": "480",
        "framerate": "30",
        "roi_x1": "0",
        "roi_x2": "640",
        "roi_y1": "0",
        "roi_y2": "480",
    },
    "motion": {
        "threshold": "10",
        "sensitivity": "1",
        "confirmation_delay": "5",
    },
    "temperature": {
        "threshold": "50",
        "simulated_temperature": "False",
    },
    "storage": {
        "snapshot_dir": "/home/pi/snapshots",
    },
}

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.picam2 = None
        self.running = False
        self.lock = threading.Lock()

    def initialize(self):
        try:
            self.picam2 = Picamera2()
            width = int(self.config["camera"]["resolution_width"])
            height = int(self.config["camera"]["resolution_height"])
            framerate = int(self.config["camera"]["framerate"])
            roi_x1 = int(self.config["camera"]["roi_x1"])
            roi_x2 = int(self.config["camera"]["roi_x2"])
            roi_y1 = int(self.config["camera"]["roi_y1"])
            roi_y2 = int(self.config["camera"]["roi_y2"])

            main_config = self.picam2.create_preview_configuration(
                main={"size": (width, height), "format": "RGB888"},
                controls={"FrameRate": framerate},
            )
            self.picam2.configure(main_config)

            self.picam2.start()
            time.sleep(2)

            logging.info(
                f"Camera initialized: {width}x{height}, framerate={framerate}, ROI={roi_x1},{roi_y2},{roi_x2},{roi_y1}"
            )
            return True
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            return False

    def capture_frame(self):
        with self.lock:
            if not self.running or self.picam2 is None:
                return None
            try:
                return self.picam2.capture_array()
            except Exception as e:
                logging.error(f"Error capturing frame: {e}")
                return None

    def stop(self):
        with self.lock:
            self.running = False
            if self.picam2:
                try:
                    self.picam2.stop()
                except Exception as e:
                    logging.error(f"Error stopping camera: {e}")
                self.picam2 = None


class MotionDetector:
    def __init__(self, config):
        self.config = config
        self.motion_threshold = int(self.config["motion"]["threshold"])
        self.sensitivity = int(self.config["motion"]["sensitivity"])
        self.confirmation_delay = int(self.config["motion"]["confirmation_delay"])
        self.roi_x1 = int(self.config["camera"]["roi_x1"])
        self.roi_x2 = int(self.config["camera"]["roi_x2"])
        self.roi_y1 = int(self.config["camera"]["roi_y1"])
        self.roi_y2 = int(self.config["camera"]["roi_x2"])

    def detect_motion(self, frame1, frame2):
        if frame1 is None or frame2 is None:
            return False

        try:
            roi1 = frame1[
                self.roi_y1 : self.roi_y2,
                self.roi_x1 : self.roi_x2,
            ]
            roi2 = frame2[
                self.roi_y1 : self.roi_y2,
                self.roi_x1 : self.roi_x2,
            ]

            diff = np.abs(roi1.astype(np.int16) - roi2.astype(np.int16))
            avg_diff = np.mean(diff)

            if avg_diff > self.motion_threshold * self.sensitivity:
                time.sleep(self.confirmation_delay)
                return self.confirm_motion(frame1, frame2)
            return False
        except Exception as e:
            logging.error(f"Error detecting motion: {e}")
            return False

    def confirm_motion(self, frame1, frame2):
        try:
            roi1 = frame1[
                self.roi_y1 : self.roi_y2,
                self.roi_x1 : self.roi_x2,
            ]
            roi2 = frame2[
                self.roi_y1 : self.roi_y2,
                self.roi_x1 : self.roi_x2,
            ]

            diff = np.abs(roi1.astype(np.int16) - roi2.astype(np.int16))
            avg_diff = np.mean(diff)

            return avg_diff > self.motion_threshold * self.sensitivity
        except Exception as e:
            logging.error(f"Error confirming motion: {e}")
            return False


class TemperatureMonitor:
    def __init__(self, config):
        self.config = config
        self.temperature_threshold = int(self.config["temperature"]["threshold"])
        self.simulated_temperature = self.config["temperature"]["simulated_temperature"] == "True"

    def get_temperature(self):
        if self.simulated_temperature:
            return 25.0
        try:
            import subprocess
            result = subprocess.run(
                ["vcgencmd", "measure_temp"],
                capture_output=True,
                text=True,
                check=True,
            )
            temp_str = result.stdout.strip()
            return float(temp_str.split("=")[1].split("'")[0])
        except Exception as e:
            logging.error(f"Error getting temperature: {e}")
            return None

    def check_temperature(self):
        temperature = self.get_temperature()
        if temperature is not None and temperature > self.temperature_threshold:
            logging.warning(f"Temperature alert! Temperature: {temperature:.2f}°C")
            return True
        return False


class SnapshotSaver:
    def __init__(self, config):
        self.config = config
        self.snapshot_dir = self.config["storage"]["snapshot_dir"]
        os.makedirs(self.snapshot_dir, exist_ok=True)

    def save_snapshot(self, frame):
        try:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = os.path.join(self.snapshot_dir, f"motion_{timestamp}.jpg")
            img = Image.fromarray(frame)
            img.save(filename)
            logging.info(f"Snapshot saved: {filename}")
        except Exception as e:
            logging.error(f"Error saving snapshot: {e}")


def load_config(config_file):
    config = configparser.ConfigParser()
    config.read_dict(DEFAULT_CONFIG)
    if os.path.exists(config_file):
        config.read(config_file)
    return config


def main():
    config = load_config(CONFIG_FILE)

    camera_handler = CameraHandler(config)
    if not camera_handler.initialize():
        logging.error("Failed to initialize camera. Exiting.")
        return

    motion_detector = MotionDetector(config)
    temperature_monitor = TemperatureMonitor(config)
    snapshot_saver = SnapshotSaver(config)

    previous_frame = None

    def signal_handler(sig, frame):
        logging.info("Exiting program...")
        camera_handler.stop()
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            current_frame = camera_handler.capture_frame()
            if current_frame is None:
                time.sleep(0.1)
                continue

            if previous_frame is not None:
                if motion_detector.detect_motion(previous_frame, current_frame):
                    logging.info("Motion detected!")
                    snapshot_saver.save_snapshot(current_frame)

            if temperature_monitor.check_temperature():
                logging.warning("Temperature alert triggered!")

            previous_frame = current_frame
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        camera_handler.stop()


if __name__ == "__main__":
    main()

