import sys
import time
import signal
import logging
import cv2
import numpy as np
import pygame
import RPi.GPIO as GPIO
from typing import Tuple, Optional

import config
import face
import lfw

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

_running = True

def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False

def initialize_audio() -> None:
    try:
        pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
    except pygame.error as e:
        logging.error(f"Error initializing audio: {e}")
        raise

def load_recognition_model(training_file: str) -> Tuple[lfw.LFW, lfw.Label, lfw.Label]:
    if not os.path.isfile(training_file):
        logging.error(f"Training file not found: {training_file}")
        raise FileNotFoundError(training_file)
    try:
        logging.info(f"Loading training data from {training_file}...")
        model = lfw.LFW()
        model.train()
        positive_label = lfw.Label(config.POSITIVE_LABEL)
        negative_label = lfw.Label("unknown")
        logging.info("Training data loaded.")
        return model, positive_label, negative_label
    except Exception as e:
        logging.error(f"Error loading training data: {e}")
        raise

def play_sound(channel: int, sound_file: str) -> None:
    try:
        sound = pygame.mixer.Sound(sound_file)
        channel.play(sound)
    except (pygame.error, FileNotFoundError) as e:
        logging.error(f"Error playing sound: {e}")

def capture_image(camera) -> Optional[np.ndarray]:
    try:
        ret, frame = camera.read()
        if not ret or frame is None:
            logging.error("Failed to capture image from camera.")
            return None
        return frame
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        return None

def preprocess_image(image: np.ndarray) -> Optional[np.ndarray]:
    try:
        gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        face_coords = face.detect_single(gray_image)
        if face_coords is None:
            logging.warning("No face detected.")
            return None
        x, y, w, h = face_coords
        cropped_face = face.crop(gray_image, x, y, w, h)
        resized_face = face.resize(cropped_face)
        return resized_face
    except Exception as e:
        logging.error(f"Error preprocessing image: {e}")
        return None

def recognize_face(model, positive_label, image: np.ndarray) -> Tuple[bool, float]:
    try:
        label, confidence = model.predict(image, positive_label, config.POSITIVE_THRESHOLD)
        return label == config.POSITIVE_LABEL, float(confidence)
    except Exception as e:
        logging.error(f"Error recognizing face: {e}")
        return False, 0.0

def control_door(is_authorized: bool, lock_pin: int, button_pin: int) -> None:
    try:
        if is_authorized:
            GPIO.output(lock_pin, GPIO.HIGH)
            logging.info("Door unlocked.")
            play_sound(config.sounds[0], config.WELCOME_SOUND)
        else:
            GPIO.output(lock_pin, GPIO.LOW)
            logging.info("Door remains locked.")
            play_sound(config.sounds[2], config.LATER_SOUND)
            play_sound(config.sounds[1], config.WAIT_SOUND)
    except Exception as e:
        logging.error(f"Error controlling door: {e}")

def main() -> None:
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = None
    try:
        camera = config.get_camera()
        if camera is None:
            raise RuntimeError("Failed to initialize camera.")

        initialize_audio()
        model, positive_label, negative_label = load_recognition_model(config.TRAINING_FILE)

        GPIO.setwarnings(False)
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(config.LOCK_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(config.BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        logging.info("Running Door Access Control...")
        print('Press button to trigger face recognition. Press Ctrl+C to exit.')

        while _running:
            if GPIO.input(config.BUTTON_PIN) == GPIO.LOW:
                image = capture_image(camera)
                if image is not None:
                    processed_image = preprocess_image(image)
                    if processed_image is not None:
                        is_authorized, confidence = recognize_face(model, positive_label, processed_image)
                        logging.info(f"Face recognized with {confidence * 100:.2f}% confidence.")
                        control_door(is_authorized, config.LOCK_PIN, config.BUTTON_PIN)
                time.sleep(0.1)

            try:
                if sys.stdin.read(1) == 'l':
                    GPIO.output(config.LOCK_PIN, GPIO.LOW)
                    logging.info("Door locked manually.")
            except (IOError, OSError):
                pass

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if camera is not None:
            camera.release()
        GPIO.cleanup()
        pygame.mixer.quit()
        logging.info("Exiting Door Access Control...")

if __name__ == "__main__":
    main()

