import sys
import signal
import serial

BLUETOOTH_PORT = "/dev/rfcomm4"
BAUD_RATE = 38400


class BluetoothSerial:
    """Context-managed Bluetooth serial link for /dev/rfcomm4."""

    def __init__(self, port: str, baudrate: int):
        self.port = port
        self.baudrate = baudrate
        self._serial: serial.Serial | None = None

    def __enter__(self) -> "BluetoothSerial":
        try:
            self._serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                xonxoff=False,
                rtscts=False,
                dsrdtr=False,
                timeout=1.0,
            )
        except serial.SerialException as exc:
            print(f"Error opening Bluetooth port {self.port}: {exc}", file=sys.stderr)
            raise
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        if self._serial is not None and self._serial.is_open:
            try:
                self._serial.close()
            except serial.SerialException as exc:
                print(f"Error closing Bluetooth port: {exc}", file=sys.stderr)

    def send_data(self, data: str) -> int | None:
        if self._serial is None or not self._serial.is_open:
            print("Bluetooth port is not open.", file=sys.stderr)
            return None
        try:
            payload = f"X{data}\n".encode("utf-8")
            bytes_written = self._serial.write(payload)
            if bytes_written is not None and bytes_written > 0:
                print(f"Sent {bytes_written} bytes: {data!r}", file=sys.stderr)
            else:
                print("Failed to write data to Bluetooth port.", file=sys.stderr)
            return bytes_written
        except serial.SerialException as exc:
            print(f"Error writing to Bluetooth port: {exc}", file=sys.stderr)
            return None


def main() -> int:
    shutting_down = False

    def _handle_signal(signum, frame):
        nonlocal shutting_down
        shutting_down = True
        print("\nShutdown signal received.", file=sys.stderr)

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        with BluetoothSerial(BLUETOOTH_PORT, BAUD_RATE) as bluetooth:
            while not shutting_down:
                try:
                    user_input = input("Enter data to send (or 'q' to quit): ")
                except EOFError:
                    print("\nEOF on stdin; exiting.", file=sys.stderr)
                    break

                if shutting_down:
                    break

                if user_input.strip().lower() == "q":
                    print("Quit command received. Exiting.", file=sys.stderr)
                    break

                bluetooth.send_data(user_input)

    except serial.SerialException as exc:
        print(f"Fatal Bluetooth error: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    sys.exit(main())

