import io
import logging
import numpy as np

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers MJPEG frames from a camera driver and forwards them to an output sink."""

    def __init__(self, c, output_sink):
        self.c = c
        self.output_sink = output_sink
        self.buffer = io.BytesIO()
        self._frame_complete = False
        self._frame_type = 0

    def write(self, d):
        """Append bytes to the buffer and flush a complete frame to the sink."""
        try:
            self.buffer.write(d)
        except Exception as exc:
            logger.error("Error writing to buffer: %s", exc)
            return

        try:
            if self._frame_complete:
                self._frame_complete = False
                self._frame_type = 0

                if self._frame_type != 1:
                    try:
                        self.output_sink(self.buffer.getvalue())
                    except Exception as sink_exc:
                        logger.error("Error writing to output sink: %s", sink_exc)
                    finally:
                        self.buffer.seek(0)
                        self.buffer.truncate()
            else:
                self._frame_complete = _is_frame_complete(d)
                self._frame_type = _get_frame_type(d)
        except Exception as exc:
            logger.error("Error processing frame: %s", exc)

    def close(self):
        """Flush any remaining buffered data to the sink before closing."""
        try:
            if self.buffer.tell() > 0:
                self.output_sink(self.buffer.getvalue())
        except Exception as exc:
            logger.error("Error flushing buffer on close: %s", exc)
        finally:
            self.buffer.close()


class MotionDetectionBuffer:
    """Detects motion by comparing decoded JPEG frames from an MJPEG stream."""

    def __init__(self, f, c):
        self.f = f
        self.c = c
        self.buffer = io.BytesIO()
        self.previous_frame = None

    def write(self, d):
        """Parse incoming bytes, decode completed JPEGs, and invoke the motion callback."""
        try:
            self.buffer.write(d)
        except Exception as exc:
            logger.error("Error writing to buffer: %s", exc)
            return

        try:
            if _is_frame_complete(d):
                self._process_frame()
        except Exception as exc:
            logger.error("Error processing frame: %s", exc)

    def _process_frame(self):
        """Decode the buffered JPEG and trigger the motion callback if a previous frame exists."""
        try:
            self.buffer.seek(0)
            data = self.buffer.read()
            self.buffer.seek(0)
            self.buffer.truncate()

            if not data:
                return

            arr = np.frombuffer(data, dtype=np.uint8)
            current_frame = self.c.imdecode(arr, self.c.CV_IMREAD_COLOR)

            if current_frame is None:
                logger.warning("Failed to decode frame; skipping.")
                return

            if self.previous_frame is not None:
                try:
                    self.f(self.previous_frame, current_frame)
                except Exception as exc:
                    logger.error("Error in motion detection callback: %s", exc)

            self.previous_frame = current_frame
        except Exception as exc:
            logger.error("Error in _process_frame: %s", exc)

    def close(self):
        """Flush any remaining buffered data and decode it as a final frame."""
        try:
            if self.buffer.tell() > 0:
                self._process_frame()
        except Exception as exc:
            logger.error("Error flushing buffer on close: %s", exc)
        finally:
            self.buffer.close()


def _is_frame_complete(d):
    """Return True when the MJPEG stream reaches a frame boundary (0xFF 0xD9)."""
    return d.endswith(b'\xff\xd9')


def _get_frame_type(d):
    """Return the H.264 frame type (0 for P-frame, 1 for I-frame) from the first few bytes."""
    if len(d) < 5:
        return 0
    return int(d[4])

