import sys
import time
import signal
import threading
import numpy as np
import cv2
import pygame.mixer as mixer
from typing import Tuple, Optional

import config
import face
import audio
from picamera2 import Picamera2
from libcamera import Transform

try:
    from gpiozero import Button, OutputDevice
except ImportError:
    print("Error: gpiozero is required. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_lock: Optional[OutputDevice] = None
_button: Optional[Button] = None
_picam2: Optional[Picamera2] = None
_sound_lock = threading.Lock()
_sounds = {}


def _cleanup() -> None:
    """Release every hardware / audio resource we hold."""
    global _lock, _button, _picam2
    if _lock is not None:
        try:
            _lock.off()
            _lock.close()
        except Exception:
            pass
        _lock = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
        _button = None
    if _picam2 is not None:
        try:
            _picam2.close()
        except Exception:
            pass
        _picam2 = None
    try:
        mixer.quit()
    except Exception:
        pass


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for a graceful shutdown."""
    global _running
    _running = False


def _load_sounds() -> None:
    """Pre-load the three WAV files used for audio feedback."""
    global _sounds
    for name, path in (("welcome", "welcome.wav"),
                       ("wait", "wait.wav"),
                       ("later", "later.wav")):
        try:
            _sounds[name] = mixer.Sound(path)
        except Exception as exc:
            print(f"Error loading sound '{path}': {exc}", file=sys.stderr)
