import signal
import sys
import time
import logging

import smbus2
from PIL import Image, ImageDraw, ImageFont

try:
    import adafruit_bme280
    import adafruit_tsl2561
except ImportError as exc:
    print(f"Missing dependency: {exc}. Install with: pip install adafruit-circuitpython-bme280 adafruit-circuitpython-tsl2561", file=sys.stderr)
    sys.exit(1)

try:
    import board
    import busio
    from adafruit_ssd1306 import SSD1306_I2C
except ImportError as exc:
    print(f"Missing display dependency: {exc}. Install with: pip install adafruit-circuitpython-ssd1306", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("bme280_oled")

I2C_BUS = 1
OLED_WIDTH = 128
OLED_HEIGHT = 64
UPDATE_INTERVAL = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def init_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        log.error("Failed to initialize I2C bus: %s", exc)
        return None


def init_oled(i2c):
    try:
        return SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, i2c)
    except Exception as exc:
        log.error("Failed to initialize SSD1306 OLED: %s", exc)
        return None


def init_bme280(i2c):
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(i2c)
    except Exception as exc:
        log.error("Failed to initialize BME280: %s", exc)
        return None


def init_tsl2561(i2c):
    try:
        return adafruit_tsl2561.TSL2561(i2c)
    except Exception as exc:
        log.error("Failed to initialize TSL2561: %s", exc)
        return None


def read_bme280(bme280):
    try:
        return bme280.temperature, bme280.humidity, bme280.pressure
    except Exception as exc:
        log.warning("BME280 read error: %s", exc)
        return None, None, None


def read_tsl2561(tsl2561):
    try:
        return tsl2561.lux
    except Exception as exc:
        log.warning("TSL2561 read error: %s", exc)
        return None


def display_data(oled, temp, hum, pres, light):
    try:
        oled.fill(0)
        oled.show()
        img = Image.new("1", (OLED_WIDTH, OLED_HEIGHT))
        draw = ImageDraw.Draw(img)
        font = ImageFont.load_default()
        lines = [
            f"Temp: {temp:.1f} C" if temp is not None else "Temp: N/A",
            f"Hum: {hum:.1f} % " if hum is not None else "Hum: N/A",
            f"Pres: {pres:.1f} hPa" if pres is not None else "Pres: N/A",
            f"Light: {light:.1f} lux" if light is not None else "Light: N/A",
        ]
        y = 0
        for line in lines:
            draw.text((0, y), line, font=font, fill=255)
            y += 16
        oled.image(img)
        oled.show()
    except Exception as exc:
        log.warning("Display update error: %s", exc)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c = init_i2c()
    if i2c is None:
        sys.exit(1)

    oled = init_oled(i2c)
    if oled is None:
        i2c.deinit()
        sys.exit(1)

    bme280 = init_bme280(i2c)
    if bme280 is None:
        oled.fill(0)
        oled.show()
        i2c.deinit()
        sys.exit(1)

    tsl2561 = init_tsl2561(i2c)
    if tsl2561 is None:
        oled.fill(0)
        oled.show()
        i2c.deinit()
        sys.exit(1)

    log.info("Sensors initialized. Updating every %.1f s. Press Ctrl+C to exit.", UPDATE_INTERVAL)

    try:
        while _running:
            temp, hum, pres = read_bme280(bme280)
            light = read_tsl2561(tsl2561)
            display_data(oled, temp, hum, pres, light)
            time.sleep(UPDATE_INTERVAL)
    finally:
        log.info("Cleaning up resources...")
        try:
            oled.fill(0)
            oled.show()
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass
        log.info("Done.")


if __name__ == "__main__":
    main()

