import os
import time
import signal
import logging
from typing import List, Optional, Tuple

from PIL import Image

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class AnimatedGif:
    """Manages loading, preloading, and playing of animated GIFs on a display."""

    def __init__(self, display, folder: str, width: Optional[int] = None, height: Optional[int] = None):
        self.display = display
        self.folder = folder
        self.width = width if width is not None else display.width
        self.height = height if height is not None else display.height
        self.gif_files: List[str] = []
        self._is_running = False
        self._current_gif_index = 0
        self._loop_count = 0
        self._frame_duration: List[int] = []
        self._frames: List[Image.Image] = []

    def load_files(self) -> None:
        """Loads GIF file paths from the specified folder, validating each file."""
        if not os.path.isdir(self.folder):
            raise FileNotFoundError(f"Folder not found: {self.folder}")

        gif_extensions = ('.gif', '.GIF')
        found = 0
        for entry in os.listdir(self.folder):
            if entry.lower().endswith(gif_extensions):
                file_path = os.path.join(self.folder, entry)
                try:
                    with Image.open(file_path) as img:
                        if getattr(img, 'is_animated', False):
                            self.gif_files.append(file_path)
                            found += 1
                        else:
                            logger.warning(f"Skipping non-animated file: {file_path}")
                except Exception as e:
                    logger.error(f"Error loading GIF {file_path}: {e}")
        if not self.gif_files:
            raise FileNotFoundError(f"No valid GIF files found in folder: {self.folder}")
        logger.info(f"Found {found} valid GIF(s) in {self.folder}")

    def preload(self) -> None:
        """Preloads frames and durations from the current GIF file."""
        if not self.gif_files:
            raise FileNotFoundError("No GIF files loaded. Call load_files() first.")

        current_file = self.gif_files[self._current_gif_index]
        try:
            with Image.open(current_file) as img:
                self._loop_count = getattr(img, 'loop', 0)
                self._frame_duration = [int(duration) for duration in getattr(img, 'frame_duration', [0])]
                self._frames = []
                for frame in range(img.n_frames):
                    img.seek(frame)
                    frame_img = img.convert('RGB')
                    frame_img = frame_img.resize((self.width, self.height), Image.NEAREST)
                    self._frames.append(frame_img)
        except Exception as e:
            logger.error(f"Error preloading GIF {current_file}: {e}")
            raise

    def play(self, loop: int = 0) -> bool:
        """Plays the preloaded GIF, respecting the loop count."""
        if not self._frames:
            logger.error("No frames preloaded. Call preload() first.")
            return False

        self._loop_count = loop if loop > 0 else 0
        start_time = time.monotonic()
        frame_index = 0

        while self._is_running:
            if frame_index >= len(self._frame_duration):
                frame_index = 0
                if self._loop_count > 0 and self._loop_count == 1:
                    break
                if self._loop_count > 0:
                    logger.info(f"Loop {self._loop_count} complete.")
                    return True
                logger.info("Animation loop complete. Restarting...")
                continue

            try:
                self.display.display(self._frames[frame_index])
            except Exception as e:
                logger.error(f"Error displaying frame: {e}")
                return False

            sleep_time = self._frame_duration[frame_index] / 1000.0
            elapsed = time.monotonic() - start_time
            remaining = sleep_time - elapsed
            if remaining > 0:
                time.sleep(remaining)
            else:
                logger.warning(f"Frame {frame_index} took longer than its duration ({self._frame_duration[frame_index]} ms).")
            frame_index += 1

        return True

    def run(self) -> None:
