except ImportError:
    smbus2 = None

try:
    import lib.oled.SSD1306 as SSD1306
except ImportError:
    SSD1306 = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

I2C_BUS = 1
OLED_ADDR = 0x3C
OLED_WIDTH = 128
OLED_HEIGHT = 64
FRAME_DURATION_BASE_MS = 20
LOOP_COUNT_INFINITE = 0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info("Signal received, shutting down...")


def _init_display():
    if SSD1306 is None:
        logger.error("SSD1306 module not available.")
        return None
    if smbus2 is None:
        logger.error("smbus2 module not available.")
        return None
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        logger.error("Failed to open I2C bus %d: %s", I2C_BUS, exc)
        return None
    try:
        oled = SSD1306.SSD1306_I2C(
            OLED_WIDTH, OLED_HEIGHT, bus, addr=OLED_ADDR
        )
        oled.begin()
        oled.clear()
        oled.display()
    except Exception as exc:
        logger.error("Failed to initialize SSD1306 at 0x%02X: %s", OLED_ADDR, exc)
        try:
            bus.close()
        except Exception:
            pass
        return None
    return oled, bus


def _load_gif_frames(path):
    try:
        with Image.open(path) as img:
            frames = []
            for frame in range(img.n_frames):
                img.seek(frame)
                duration = img.info.get("duration", FRAME_DURATION_BASE_MS)
                frames.append((ImageOps.pad(
                    img.convert("RGB"),
                    (OLED_WIDTH, OLED_HEIGHT),
                    method=Image.NEAREST,
                    color=(0, 0, 0),
                    centering=(0.5, 0.5),
                ), duration))
            return frames
    except FileNotFoundError:
        logger.error("GIF file not found: %s", path)
        return None
    except (OSError, ValueError, Image.UnidentifiedImageError) as exc:
        logger.error("Error loading GIF %s: %s", path, exc)
        return None


def _render_frame(oled, image):
    try:
        oled.clear()
        oled.image(image)
        oled.display()
    except Exception as exc:
        logger.error("Error rendering frame: %s", exc)


def play_gif(oled, gif_path, loop_count=LOOP_COUNT_INFINITE):
    if oled is None:
        logger.error("Display not initialized.")
        return
    if not os.path.isfile(gif_path):
        logger.error("GIF file not found: %s", gif_path)
        return
    frames = _load_gif_frames(gif_path)
    if frames is None:
        return
    frame_count = len(frames)
    if frame_count == 0:
        logger.error("No frames loaded from GIF.")
        return
    logger.info("Playing GIF: %s (%d frames)", gif_path, frame_count)
    current_frame = 0
    loop = 0
    while _running:
        if current_frame >= frame_count:
            current_frame = 0
            loop += 1
            if loop >= loop_count and loop_count != LOOP_COUNT_INFINITE:
                logger.info("Completed loop %d/%d. Exiting.", loop, loop_count)
                break
        image, duration = frames[current_frame]
        _render_frame(oled, image)
        current_frame = (current_frame + 1) % frame_count
        time.sleep(duration / 1000.0)


def main(gif_folder):
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    oled = _init_display()
    if oled is None:
        sys.exit(1)
    oled, bus = oled
    try:
        if not os.path.isdir(gif_folder):
            logger.error("GIF folder not found: %s", gif_folder)
            return
        gif_files = [
            f for f in os.listdir(gif_folder)
            if f.lower().endswith(".gif")
        ]
        if not gif_files:
            logger.warning("No GIF files found in %s", gif_folder)
            return
        for gif_file in gif_files:
            if not _running:
                break
            gif_path = os.path.join(gif_folder, gif_file)
            play_gif(oled, gif_path, loop_count=LOOP_COUNT_INFINITE)
    finally:
        try:
            oled.clear()
            oled.display()
        except Exception:
            pass
        try:
            bus.close()
        except Exception:
            pass
        logger.info("Resources released. Exiting.")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python script.py <gif_folder>")
        sys.exit(1)
    main(sys.argv[1])

