def _poll_sensors(bus, addr):
    port = _read_port(bus, addr)
    for sensor_num in range(8):
        if not (port & (1 << sensor_num)):
            print(f"Obstacle detected by sensor {sensor_num}")


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

