    return round(random.uniform(MIN_TEMP, MAX_TEMP), 2)


def create_message(reading, message_count):
    return json.dumps({"temperature": reading, "count": message_count})


def connect_and_publish(client, topic, message_count):
    connected = False
    for attempt in range(1, MAX_RECONNECT_ATTEMPTS + 1):
        try:
            result = client.connect(BROKER_HOST, BROKER_PORT, KEEPALIVE)
            if result == mqtt.MQTT_ERR_SUCCESS:
                connected = True
                break
            else:
                print(f"Connection attempt {attempt}/{MAX_RECONNECT_ATTEMPTS} failed with error code: {result}")
        except Exception as e:
            print(f"Connection attempt {attempt}/{MAX_RECONNECT_ATTEMPTS} failed: {e}")
        if attempt < MAX_RECONNECT_ATTEMPTS:
            time.sleep(RECONNECT_DELAY)
    if not connected:
        print("Failed to connect to MQTT broker after multiple attempts.")
        return 0

    stop_event.clear()
    client.loop_start()
    try:
        published = 0
        for i in range(message_count):
            if stop_event.is_set():
                print("Publishing interrupted by stop event.")
                break
            temperature = generate_temperature_reading()
            message = create_message(temperature, i + 1)
            try:
                result = client.publish(topic, message, qos=0)
                if result.rc == mqtt.MQTT_ERR_SUCCESS:
                    published += 1
                    print(f"Published message {i + 1}/{message_count}: {message}")
                else:
                    print(f"Failed to publish message {i + 1}/{message_count} with error code: {result.rc}")
            except Exception as e:
                print(f"Exception during publish of message {i + 1}/{message_count}: {e}")
            stop_event.wait(1.0)
        return published
    finally:
        client.loop_stop()
        try:
            client.disconnect()
            print("Disconnected from MQTT broker.")
        except Exception as e:
            print(f"Error during disconnect: {e}")


def signal_handler(signum, frame):
    print(f"\nSignal {signum} received, stopping...")
    stop_event.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    client.on_connect = on_connect
    client.on_publish = on_publish

    try:
        published_messages = connect_and_publish(client, TOPIC, MESSAGE_COUNT)
        if published_messages == MESSAGE_COUNT:
            print("All messages published successfully.")
            sys.exit(0)
        else:
            print(f"Only {published_messages} of {MESSAGE_COUNT} messages were published.")
            sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

