import time
import logging
import signal
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x5F
DHT20_STATUS_REG = 0x71
DHT20_MEASURE_REG = 0x71
DHT20_STATUS_BUSY_BIT = 0x80
DHT20_CRC_POLYNOMIAL = 0x31
DHT20_CRC_INIT = 0xFF

class DHT20:
    def __init__(self, i2c_bus_number=1):
        self.i2c_bus = None
        self._running = True
        try:
            self.i2c_bus = smbus2.SMBus(i2c_bus_number)
        except Exception as e:
            logging.error(f"Failed to open I2C bus {i2c_bus_number}: {e}")
            raise
        time.sleep(0.5)
        if not self._check_sensor():
            logging.error("DHT20 sensor not detected or status check failed.")
            self.close()
            raise RuntimeError("DHT20 sensor not detected or status check failed.")
        logging.info("DHT20 sensor initialized successfully.")

    def _check_sensor(self):
        try:
            status = self.i2c_bus.read_byte_data(DHT20_I2C_ADDRESS, DHT20_STATUS_REG)
            return (status & 0x80) == 0
        except Exception as e:
            logging.error(f"Error checking sensor status: {e}")
            return False

    def _read_raw_data(self):
        try:
            data = self.i2c_bus.read_i2c_block_data(DHT20_I2C_ADDRESS, DHT20_MEASURE_REG, 7)
            if len(data) != 7:
                logging.error(f"Unexpected data length: {len(data)}")
                return None
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
            crc = data[6]
            calculated_crc = self._calculate_crc8(data[:6])
            if calculated_crc != crc:
                logging.warning("CRC error detected.")
                return None, True
            return humidity_raw, temperature_raw, False
        except Exception as e:
            logging.error(f"Error reading sensor data: {e}")
            return None, True

    def _calculate_crc8(self, data):
        crc = DHT20_CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20_CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def read_data(self):
        if not self.i2c_bus:
            logging.error("I2C bus not initialized.")
            return None, None, True
        retries = 0
        while retries < 5:
            try:
                if self._check_sensor():
                    humidity_raw, temperature_raw, crc_error = self._read_raw_data()
                    if humidity_raw is not None and temperature_raw is not None and not crc_error:
                        temperature = temperature_raw / 1048576.0 * 200.0 - 50.0
                        humidity = humidity_raw / 1048576.0 * 100.0
                        return temperature, humidity, False
                    else:
                        logging.warning("Sensor data invalid, retrying...")
                        retries += 1
                        time.sleep(2)
                else:
                    logging.warning("Sensor busy, retrying...")
                    retries += 1
                    time.sleep(2)
            except Exception as e:
                logging.error(f"Error reading sensor data: {e}")
                retries += 1
                time.sleep(2)
        logging.error("Failed to read sensor data after multiple retries.")
        return None, None, True

    def close(self):
        if self.i2c_bus:
            try:
                self.i2c_bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.i2c_bus = None

    def stop(self):
        self._running = False

def main():
    sensor = None
    def signal_handler(sig, frame):
        logging.info("Program interrupted by user.")
        if sensor:
            sensor.stop()
        exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    try:
        sensor = DHT20(i2c_bus_number=1)
        temperature, humidity, crc_error = sensor.read_data()
        if temperature is not None and humidity is not None and not crc_error:
            logging.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
        else:
            logging.error("Failed to read sensor data.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if sensor:
            sensor.close()

if __name__ == "__main__":
    main()

