import signal
import sys
import time
import logging
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x5F
I2C_BUS_NUMBER = 1
MEASUREMENT_TIMEOUT = 0.1
STATUS_READY_BIT = 0x80
STATUS_ERROR_BIT = 0x10
STATUS_BUSY_BIT = 0x01

DHT20_CRC_POLYNOMIAL = 0x31
DHT20_CRC_INIT = 0xFF


class DHT20:
    def __init__(self, i2c_bus_number=I2C_BUS_NUMBER, address=DHT20_I2C_ADDRESS):
        self.address = address
        self.bus = None
        try:
            self.bus = SMBus(i2c_bus_number)
            logging.info(f"Opened I2C bus {i2c_bus_number}")
        except Exception as e:
            logging.error(f"Failed to open I2C bus {i2c_bus_number}: {e}")
            self.bus = None

        if self.bus is not None:
            try:
                self._verify_sensor()
            except Exception as e:
                logging.error(f"Sensor verification failed: {e}")
                self.bus = None

    def _verify_sensor(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, 0x71, 2)
            if data[0] != 0x15 or data[1] != 0xA7:
                raise ValueError(f"Unexpected calibration values: 0x{data[0]:02X} 0x{data[1]:02X}")
            logging.info("DHT20 sensor verified successfully.")
        except Exception as e:
            raise ValueError(f"Sensor verification failed: {e}")

    def _read_register(self, register):
        try:
            write_msg = i2c_msg.write(self.address, [register])
            read_msg = i2c_msg.read(self.address, 1)
            self.bus.i2c_rdwr(write_msg, read_msg)
            return list(read_msg)
        except Exception as e:
            logging.error(f"Error reading register 0x{register:02X}: {e}")
            return None

    def _write_register(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except Exception as e:
            logging.error(f"Error writing register 0x{register:02X}: {e}")

    def measure(self):
        if self.bus is None:
            logging.error("I2C bus not initialized.")
            return None, None, True

        try:
            self._write_register(0x71, 0xBE)
            time.sleep(0.018)

            start_time = time.time()
            while True:
                status = self._read_register(0x71)
                if status is None:
                    return None, None, True
                if (status[0] & STATUS_READY_BIT) and not (status[0] & STATUS_BUSY_BIT):
                    break
                if time.time() - start_time > MEASUREMENT_TIMEOUT:
                    logging.error("Measurement timeout.")
                    return None, None, True
                time.sleep(0.01)

            data = self._read_register(0x71)
            if data is None or len(data) < 7:
                logging.error("Failed to read measurement data.")
                return None, None, True

            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

            calculated_crc = self._calculate_crc8(data[:6])
            received_crc = data[6]

            if calculated_crc != received_crc:
                logging.warning("CRC error detected.")
                return None, None, True

            temperature = temperature_raw * 200.0 / 0x100000
            humidity = humidity_raw * 100.0 / 0x100000

            return temperature, humidity, False

        except Exception as e:
            logging.error(f"Error during measurement: {e}")
            return None, None, True

    def _calculate_crc8(self, data):
        crc = DHT20_CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20_CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None


def main():
    sensor = DHT20()
    if sensor.bus is None:
        logging.error("Failed to initialize DHT20 sensor. Exiting.")
        sys.exit(1)

    def signal_handler(sig, frame):
        logging.info("Signal received, exiting gracefully.")
        sensor.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    temperature, humidity, crc_error = sensor.measure()

    if crc_error:
        logging.error("Measurement failed or CRC error.")
    else:
        logging.info(f"Temperature: {temperature:.2f} C")
        logging.info(f"Humidity: {humidity:.2f} %")

    sensor.close()


if __name__ == "__main__":
    main()

