import time
import signal
import sys

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def get_cpu_temperature():
    """Return the CPU temperature in degrees Celsius, or None on error."""
    try:
        from gpiozero import CPUTemperature
        return CPUTemperature().temperature
    except FileNotFoundError:
        print("Error: thermal zone file not found. Is this running on a Raspberry Pi?")
        return None
    except Exception as exc:
        print(f"Error reading CPU temperature: {exc}")
        return None

def main():
    signal.signal(signal.SIGINT, _handle_sigint)
    while _running:
        temp = get_cpu_temperature()
        if temp is not None:
            print(f"CPU Temperature: {temp:.2f} °C")
        time.sleep(5)

    print("Program terminated")
    sys.exit(0)

if __name__ == "__main__":
    main()

