import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus on GPIO3 (SCL) and GPIO2 (SDA)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    exit(1)

# Initialize the TCA9548A I2C multiplexer
try:
    i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
except Exception as e:
    print(f"Error initializing I2C multiplexer: {e}")
    exit(1)

# Initialize the BME280 sensor on multiplexer channel 0
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_multiplexer[0])
except Exception as e:
    print(f"Error initializing BME280 sensor: {e}")
    exit(1)

# Initialize the TSL2591 sensor on multiplexer channel 1
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer[1])
except Exception as e:
    print(f"Error initializing TSL2591 sensor: {e}")
    exit(1)

# Main loop for continuous sensor readings
try:
    while True:
        # Read temperature, humidity, and pressure from the BME280 sensor
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
            pressure = bme280_sensor.pressure
        except Exception as e:
            print(f"Error reading BME280 sensor: {e}")
            temperature = None
            humidity = None
            pressure = None

        # Read light intensity from the TSL2591 sensor
        try:
            light_intensity = tsl2591_sensor.lux
        except Exception as e:
            print(f"Error reading TSL2591 sensor: {e}")
            light_intensity = None

        # Print the sensor readings with two decimal places
        if temperature is not None:
            print(f"Temperature: {temperature:.2f} C")
        if humidity is not None:
            print(f"Humidity: {humidity:.2f} %")
        if pressure is not None:
            print(f"Pressure: {pressure:.2f} hPa")
        if light_intensity is not None:
            print(f"Light Intensity: {light_intensity:.2f} lux")

        # Pause for 2 seconds before the next set of readings
        time.sleep(2)

# Handle keyboard interrupt (Ctrl+C) for graceful exit
except KeyboardInterrupt:
    print("\nExiting program.")

