import serial
import serial.tools.list_ports
import time
import csv
import sys
import signal

PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
LOG_FILE = 'temperature_log.csv'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_uart(port, baud):
    try:
        return serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
            write_timeout=1.0,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {port}: {exc}", file=sys.stderr)
        return None

def read_temperature(uart):
    try:
        raw = uart.readline()
    except serial.SerialException as exc:
        print(f"Warning: serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        return float(raw.decode('ascii', errors='replace').strip())
    except ValueError:
        print(f"Warning: non-numeric data received: {raw!r}", file=sys.stderr)
        return None

def append_log(celsius, fahrenheit):
    try:
        with open(LOG_FILE, 'a', newline='') as fh:
            writer = csv.writer(fh)
            if fh.tell() == 0:
                writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])
            writer.writerow([time.strftime('%Y-%m-%d %H:%M:%S'), f'{celsius:.2f}', f'{fahrenheit:.2f}'])
    except OSError as exc:
        print(f"Warning: failed to write log: {exc}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    uart = open_uart(PORT, BAUD_RATE)
    if uart is None:
        sys.exit(1)

    try:
        while _running:
            temp_c = read_temperature(uart)
            if temp_c is not None:
                temp_f = temp_c * 9.0 / 5.0 + 32.0
                append_log(temp_c, temp_f)
            time.sleep(0.5)
    finally:
        if uart.is_open:
            uart.close()
            print("UART port closed.")

if __name__ == '__main__':
    main()

