import json
import logging
import random
import signal
import sys
import time
import urllib.error
import urllib.request

import adafruit_dht
import board

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "webhook_url": "http://example.com/webhook",
    "dht22_pin": 4,
    "temperature_min": -40,
    "temperature_max": 80,
    "humidity_min": 0,
    "humidity_max": 100,
    "moving_average_window": 5,
    "retry_delays": [1, 3, 9],
    "max_consecutive_failures": 3,
    "failure_pause_seconds": 300,
}

running = True


def load_config(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning("Config file not found; using defaults.")
    except json.JSONDecodeError as exc:
        logging.error("Invalid JSON in config file: %s", exc)
    return dict(DEFAULT_CONFIG)


def validate_reading(temperature, humidity, cfg):
    if not (cfg["temperature_min"] <= temperature <= cfg["temperature_max"]):
        logging.error("Temperature out of range: %.1f", temperature)
        return False
    if not (cfg["humidity_min"] <= humidity <= cfg["humidity_max"]):
        logging.error("Humidity out of range: %.1f", humidity)
        return False
    return True


def simulate_reading(cfg):
    temperature = round(random.uniform(20, 30), 1)
    humidity = round(random.uniform(60, 80), 1)
    logging.info("Simulated reading: T=%.1f C, H=%.1f %%", temperature, humidity)
    return temperature, humidity


def send_webhook(url, payload):
    try:
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(url, data=data, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            logging.info("Webhook sent successfully (HTTP %d).", resp.status)
            return True
    except urllib.error.HTTPError as exc:
        logging.error("HTTP error sending webhook: %s", exc)
    except urllib.error.URLError as exc:
        logging.error("URL error sending webhook: %s", exc)
    except Exception as exc:
        logging.error("Unexpected error sending webhook: %s", exc)
    return False


def main():
    global running
    cfg = load_config(CONFIG_FILE)

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(message)s",
    )

    signal.signal(signal.SIGINT, lambda *_: setattr(globals(), "running", False))
    signal.signal(signal.SIGTERM, lambda *_: setattr(globals(), "running", False))

    dht = None
    consecutive_failures = 0
    samples = []

    try:
        try:
            dht = adafruit_dht.DHT22(getattr(board, f"D{cfg['dht22_pin']}"))
            logging.info("DHT22 initialized on BCM pin %d.", cfg["dht22_pin"])
        except Exception as exc:
            logging.error("Failed to initialize DHT22: %s", exc)

        while running:
