import signal
import sys
import time
import logging
import threading

import paho.mqtt.client as mqtt
from gpiozero import Device
from gpiozero.pins.lgpio import LGPIOFactory
from adafruit_dht import DHT22
from board import D4

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = "\u00B0C"
HOMIE_VERSION = "4.0"
MAX_RETRIES = 3
RETRY_DELAY = 2.0
DHT_INIT_WARMUP = 2.0

_shutdown = threading.Event()


def _signal_handler(signum, frame):
    logger.info("Signal %s received, shutting down...", signum)
    _shutdown.set()


class DHT22Sensor:
    def __init__(self, pin, retries=MAX_RETRIES, retry_delay=RETRY_DELAY):
        self.pin = pin
        self.retries = retries
        self.retry_delay = retry_delay
        self._lock = threading.Lock()
        self._sensor = None
        self._init_sensor()

    def _init_sensor(self):
        try:
            self._sensor = DHT22(self.pin, use_pulseio=False)
            logger.info("DHT22 initialized on pin %s", self.pin)
        except Exception as exc:
            logger.error("Failed to initialize DHT22: %s", exc)
            self._sensor = None

    def read(self):
        if self._sensor is None:
            logger.error("DHT22 not initialized")
            return None, None
        for attempt in range(1, self.retries + 1):
            try:
                temperature = self._sensor.temperature
                humidity = self._sensor.humidity
                if temperature is not None and humidity is not None:
                    return temperature, humidity
                logger.warning("DHT22 returned None (attempt %d/%d)", attempt, self.retries)
            except RuntimeError as exc:
                logger.warning("DHT22 read error (attempt %d/%d): %s", attempt, self.retries, exc)
            except Exception as exc:
                logger.error("Unexpected DHT22 error (attempt %d/%d): %s", attempt, self.retries, exc)
            if attempt < self.retries:
                time.sleep(self.retry_delay)
        logger.error("DHT22 read failed after %d attempts", self.retries)
        return None, None

    def close(self):
        if self._sensor is not None:
            try:
                self._sensor.exit()
            except Exception:
                pass
            self._sensor = None


class HomieMQTT:
    def __init__(self, config):
        self.config = config
        self._client = None
        self._connected = False
        self._lock = threading.Lock()

    def _on_connect(self, client, userdata, flags, reason_code, properties):
        if reason_code == 0:
            self._connected = True
            logger.info("Connected to MQTT broker %s:%d", self.config.mqttbroker, self.config.mqttport)
            self._send_homie_discovery()
        else:
            self._connected = False
            logger.error("MQTT connect failed, reason_code=%s", reason_code)

    def _on_disconnect(self, client, userdata, flags, reason_code, properties):
        self._connected = False
        logger.warning("Disconnected from MQTT broker (reason_code=%s)", reason_code)

    def _send_homie_discovery(self):
        with self._lock:
            if self._client is None:
                return
        try:
            self._client.publish(
                f"homie/{self.config.homieclientid}/$homie", HOMIE_VERSION, retain=True
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/$name", self.config.homieclientname, retain=True
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/$nodes", self.config.homienodes, retain=True
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/$name",
                "DHT22 Sensor",
                retain=True,
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/$properties",
                "temperature,humidity",
                retain=True,
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/temperature/$name",
                "Temperature",
                retain=True,
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/temperature/$unit",
                DEGREE_CELSIUS,
                retain=True,
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/temperature/$datatype",
                "float",
                retain=True,
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/humidity/$name",
                "Humidity",
                retain=True,
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/humidity/$unit",
                "%",
                retain=True,
            )
            self._client.publish(
                f"homie/{self.config.homieclientid}/{self.config.homienodes}/humidity/$datatype",
                "float",
                retain=True,
            )
        except Exception as exc:
            logger.error("Failed to send Homie discovery messages: %s", exc)

    def connect(self):
        with self._lock:
            if self._client is not None:
                return
            try:
                self._client = mqtt.Client(
                    mqtt.CallbackAPIVersion.VERSION2,
                    client_id=self.config.mqttclientid,
                    clean_session=True,
                )
                if self.config.mqttusername and self.config.mqttpassword:
                    self._client.username_pw_set(self.config.mqttusername, self.config.mqttpassword)
                self._client.on_connect = self._on_connect
                self._client.on_disconnect = self._on_disconnect
                self._client.will_set(
                    f"homie/{self.config.homieclientid}/$state", "lost", retain=True
                )
                self._client.connect(self.config.mqttbroker, self.config.mqttport, keepalive=60)
                self._client.loop_start()
                time.sleep(2)
                if not self._connected:
                    self._client.loop_stop()
                    self._client = None
                    logger.error("MQTT connection timed out")
                    return False
                self._send_homie_discovery()
            except Exception as exc:
                logger.error("MQTT connection error: %s", exc)
                self._client = None
                return False
        return True

    def publish(self, topic, payload, retain=True):
        with self._lock:
            if self._client is None or not self._connected:
                logger.warning("MQTT not connected, skipping publish to %s", topic)
                return
            try:
                self._client.publish(topic, payload, retain=retain)
            except Exception as exc:
                logger.error("MQTT publish error to %s: %s", topic, exc)

    def disconnect(self):
        with self._lock:
            if self._client is None:
                return
            try:
                self._client.loop_stop()
                self._client.disconnect()
            except Exception as exc:
                logger.error("MQTT disconnect error: %s", exc)
            finally:
                self._client = None
                self._connected = False


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        import config
    except Exception as exc:
        logger.error("Failed to import config module: %s", exc)
        sys.exit(1)

    try:
        from config import (
            mqttbroker, mqttport, mqttusername, mqttpassword, mqttclientid,
            mqttretainmessage, mqttqos, homieclientid, homieclientname, homienodes,
            dhtegpiopin, publishertimeout, publishtime, dhtegpiopin,
        )
    except AttributeError as exc:
        logger.error("Missing config parameter: %s", exc)
        sys.exit(1)

    Device.pin_factory = LGPIOFactory()

    sensor = DHT22Sensor(D4)
    mqtt_client = HomieMQTT(config)

    if not mqtt_client.connect():
        logger.error("Failed to connect to MQTT broker, exiting")
        sensor.close()
        sys.exit(1)

    logger.info("DHT22 warm-up period (%.1f s) ...", DHT_INIT_WARMUP)
    time.sleep(DHT_INIT_WARMUP)

    try:
        while not _shutdown.is_set():
            temperature, humidity = sensor.read()
            if temperature is not None and humidity is not None:
                topic_temp = f"homie/{homieclientid}/{homienodes}/temperature"
                topic_hum = f"homie/{homieclientid}/{homienodes}/humidity"
                mqtt_client.publish(topic_temp, f"{temperature:.1f}", retain=mqttretainmessage)
                mqtt_client.publish(topic_hum, f"{humidity:.1f}", retain=mqttretainmessage)
                logger.info("T=%.1f%s  H=%.1f%%", temperature, DEGREE_CELSIUS, humidity)
            else:
                logger.warning("Skipping publish due to read failure")
            if _shutdown.is_set():
                break
            for _ in range(publishertimeout):
                if _shutdown.is_set():
                    break
                time.sleep(1)
    except Exception as exc:
        logger.error("Unexpected error in main loop: %s", exc)
    finally:
        logger.info("Cleaning up...")
        mqtt_client.disconnect()
        sensor.close()
        logger.info("Done.")


if __name__ == "__main__":
    main()

