import signal
import sys
import time
import json
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    import adafruit_dht
    import board
    DHT_AVAILABLE = True
except ImportError:
    DHT_AVAILABLE = False

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LED_PIN = 17
DHT_PIN = 4
PWM_FREQUENCY = 100          # Hz
SUNRISE_SECONDS = 600
SUNSET_SECONDS = 600
HOLD_SECONDS = 10
MAX_BRIGHTNESS = 90.0         # percent (hard cap)
SENSOR_INTERVAL = 5           # seconds between DHT22 reads

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("led_cycle")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_pwm = None
_dht = None
_running = True


def _shutdown(signum=None, frame=None):
    """Emergency shutdown: turn LED off, stop PWM, release GPIO."""
    global _running
    _running = False
    log.info("Shutdown signal received – cleaning up.")
    if _pwm is not None:
        try:
            _pwm.ChangeDutyCycle(0)
            _pwm.stop()
        except Exception:
            pass
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass
    if DHT_AVAILABLE and _dht is not None:
        try:
            _dht.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def _read_dht22():
    """Attempt a DHT22 read with a short retry window.

    Returns (temperature, humidity) or (None, None) on failure.
    """
    if not DHT_AVAILABLE:
        return None, None
    if _dht is None:
        return None, None
    for attempt in range(3):
        try:
            t = _dht.temperature
            h = _dht.humidity
            if t is not None and h is not None:
                return t, h
        except RuntimeError as exc:
            # DHT22 checksum / timing glitches are common – retry.
            log.warning("DHT22 read attempt %d failed: %s", attempt + 1, exc)
        except Exception as exc:
            log.error("DHT22 unexpected error: %s", exc)
            break
        time.sleep(0.5)
    return None, None


def _log_entry(brightness, temperature, humidity):
    """Print a timestamped JSON-like log line."""
    entry = {
        "timestamp": datetime.now().isoformat(timespec="seconds"),
        "brightness": round(brightness, 1),
    }
    if temperature is not None:
        entry["temperature"] = round(temperature, 1)
    if humidity is not None:
        entry["humidity"] = round(humidity, 1)
    print(json.dumps(entry), flush=True)


def _set_brightness(brightness):
    """Set LED brightness (0–90 %) via PWM duty cycle.

    Clamps to the hard cap so the LED never exceeds 90 %.
    """
    clamped = min(max(brightness, 0.0), MAX_BRIGHTNESS)
    if _pwm is not None:
        _pwm.ChangeDutyCycle(clamped)
    return clamped


def _ramp(pwm, start, end, duration, hold=0):
    """Ramp brightness from *start* to *end* over *duration* seconds."""
    if start == end:
        return
    steps = max(1, int(duration / 0.1))
    delta = (end - start) / steps
    for i in range(1, steps + 1):
        if not _running:
            return
        brightness = start + delta * i
        _set_brightness(brightness)
        _log_entry(brightness, None, None)
        time.sleep(0.1)
    if hold > 0:
        _set_brightness(end)
        _log_entry(end, None, None)
        for _ in range(hold):
            if not _running:
                return
            time.sleep(1)


def main():
    global _pwm, _dht

    # --- GPIO setup ----------------------------------------------------------
    if GPIO is not None:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT)
    else:
        log.warning("RPi.GPIO not available – running in simulation mode.")

    # --- PWM setup -----------------------------------------------------------
    if GPIO is not None:
        _pwm = GPIO.PWM(LED_PIN, PWM_FREQUENCY)
        _pwm.start(0)
    else:
        _pwm = None

    # --- DHT22 setup ---------------------------------------------------------
    if DHT_AVAILABLE:
        try:
            _dht = adafruit_dht.DHT22(board.D4)
        except Exception as exc:
            log.error("Failed to initialise DHT22 on BCM pin 4: %s", exc)
            _dht = None

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    log.info("Starting sunrise/sunset LED cycle (PWM %d Hz, max %d%%).",
             PWM_FREQUENCY, MAX_BRIGHTNESS)

    try:
        while _running:
            # --- Sunrise: 0 -> 90 % over 600 s --------------------------------
            _log_entry(0, None, None)
            _set_brightness(0)
            _ramp(_pwm, 0, MAX_BRIGHTNESS, SUNRISE_SECONDS, HOLD_SECONDS)

            if not _running:
                break

            # --- Hold at max brightness 10 s -----------------------------------
            _log_entry(MAX_BRIGHTNESS, None, None)
            _set_brightness(MAX_BRIGHTNESS)
            for _ in range(HOLD_SECONDS):
                if not _running:
                    break
                time.sleep(1)

            if not _running:
                break

            # --- Sunset: 90 -> 0 % over 600 s ---------------------------------
            _log_entry(MAX_BRIGHTNESS, None, None)
            _ramp(_pwm, MAX_BRIGHTNESS, 0, SUNSET_SECONDS, HOLD_SECONDS)

            if not _running:
                break

            # --- Hold at 0 brightness 10 s ------------------------------------
            _log_entry(0, None, None)
            _set_brightness(0)
            for _ in range(HOLD_SECONDS):
                if not _running:
                    break
                time.sleep(1)

            if not _running:
                break

            # --- Optional sensor reads during hold -----------------------------
            if _dht is not None:
                temperature, humidity = _read_dht22()
                _log_entry(0, temperature, humidity)

    except Exception as exc:
        log.exception("Unexpected error in main loop: %s", exc)
    finally:
        _shutdown()


if __name__ == "__main__":
    main()

