                    logger.warning(f"Measurement attempt {attempt + 1} failed: {e}")
                    time.sleep(self.RETRY_DELAY)
                    continue

                raw_temp = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
                raw_hum = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

                temperature = (raw_temp / 2**20) * 200.0 - 50.0
                humidity = (raw_hum / 2**20) * 100.0

                self.last_temperature = temperature
                self.last_humidity = humidity
                self.last_measurement_time = time.monotonic()
                return temperature, humidity, False

            logger.warning(f"Measurement attempt {attempt + 1} failed to wait for ready.")
            time.sleep(self.RETRY_DELAY)

        logger.error("Max retries reached. Returning None.")
        return None, None, True

    def begin(self):
        if self.bus is None:
            raise DHT20Error("I2C bus not initialized.")
        time.sleep(self.POWER_ON_DELAY)
        try:
            self._write_register(0x71, [0x00, 0x00])
        except DHT20Error as e:
            raise DHT20Error(f"Failed to begin measurement: {e}") from e
        return True

    def stop(self):
        self._running = False


def main():
    sensor = DHT20()
    try:
        if not sensor.begin():
            print("Failed to initialize DHT20 sensor.")
            return
        while True:
            temp, hum, _ = sensor.get_temperature_and_humidity()
            if temp is not None and hum is not None:
                print(f"Temperature: {temp:.2f} C, Humidity: {hum:.2f} %")
            else:
                print("Failed to read sensor data.")
            time.sleep(2.0)
    except KeyboardInterrupt:
        print("Exiting program.")
    except DHT20Error as e:
        logger.error(f"Fatal error: {e}")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

