import signal
import sys
import time
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

FAN_PIN = 17
WAIT_TIME = 1
FAN_MIN = 25
FAN_MAX = 100
FAN_OFF = 0
TEMPERATURE_THRESHOLD = 1
PWM_FREQUENCY = 25
THERMAL_ZONE = '/sys/class/thermal/thermal_zone0/temp'

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def get_cpu_temperature():
    try:
        with open(THERMAL_ZONE, 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError) as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None

def calculate_fan_speed(temperature):
    if temperature is None:
        return FAN_OFF
    if temperature > 50:
        return FAN_MAX
    elif temperature > 40:
        return int(FAN_MIN + (temperature - 40) * 25)
    else:
        return FAN_OFF

def main():
    global _running
    signal.signal(signal.SIGTERM, _handle_signal)
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        logging.error(f"Failed to initialize GPIO {FAN_PIN}: {e}")
        sys.exit(1)
    try:
        while _running:
            temperature = get_cpu_temperature()
            if temperature is not None:
                logging.info(f"CPU Temperature: {temperature:.2f} °C")
                speed = calculate_fan_speed(temperature)
                if speed != fan.value * 100:
                    fan.value = speed / 100.0
                    logging.info(f"Fan speed set to: {speed}%")
            time.sleep(WAIT_TIME)
    except KeyboardInterrupt:
        logging.info("Fan control interrupted by keyboard.")
    finally:
        try:
            fan.value = 0
            fan.close()
        except Exception:
            pass
        logging.info("Fan stopped and GPIO cleaned up.")

if __name__ == "__main__":
    main()

