import subprocess
import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("fanctl")

FAN_PIN = 14
PWM_FREQ = 100.0
INTERVAL = 5.0
DEFAULT_DUTY = 100.0

TEMPERATURE_THRESHOLDS = [
    (80.0, 100.0),
    (71.0, 85.0),
    (70.0, 70.0),
    (65.0, 65.0),
    (60.0, 60.0),
    (50.0, 50.0),
]

fan = None
running = True


def get_cpu_temperature():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        temp_str = result.stdout.strip()
        return float(temp_str.split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError) as exc:
        log.error("Failed to read CPU temperature: %s", exc)
        return None


def calculate_fan_speed(temperature):
    for threshold, speed in TEMPERATURE_THRESHOLDS:
        if temperature >= threshold:
            return speed
    return 0.0


def signal_handler(signum, frame):
    global running
    log.info("Received signal %s, shutting down...", signum)
    running = False


def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as exc:
        log.error("Failed to initialize PWM on GPIO%d: %s", FAN_PIN, exc)
        sys.exit(1)

    log.info("Fan control started on GPIO%d @ %.0f Hz", FAN_PIN, PWM_FREQ)

    try:
        while running:
            temperature = get_cpu_temperature()
            if temperature is not None:
                speed = calculate_fan_speed(temperature)
                try:
                    fan.value = speed / 100.0
                    log.info("CPU temp: %.1f°C -> fan duty: %.0f%%", temperature, speed)
                except Exception as exc:
                    log.error("Failed to set PWM duty: %s", exc)
            else:
                log.warning("Temperature read failed; retaining last duty cycle.")

            for _ in range(int(INTERVAL)):
                if not running:
                    break
                time.sleep(1)
    finally:
        if fan is not None:
            try:
                fan.value = 0.0
                fan.close()
            except Exception:
                pass
        log.info("Fan control stopped.")


if __name__ == "__main__":
    main()

