import signal
import sys
import time
import logging
import threading

import paho.mqtt.client as mqtt
from gpiozero import InputDevice
from adafruit_dht import DHT22

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

running = threading.Event()
running.set()

def handle_signal(signum, frame):
    logger.info('Received signal %s, shutting down...', signum)
    running.clear()

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def publish_message(client, topic, payload):
    info = client.publish(topic, payload, qos=1)
    info.wait_for_publish(timeout=5)
    if info.rc != mqtt.MQTT_ERR_SUCCESS:
        logger.error('Failed to publish to %s (rc=%s)', topic, info.rc)

def read_dht22(sensor):
    while running.is_set():
        try:
            temp = sensor.temperature
            hum = sensor.humidity
            if temp is not None and hum is not None:
                return round(temp, 1), round(hum, 1)
            logger.warning('DHT22 returned None values')
        except RuntimeError as e:
            logger.warning('DHT22 read error: %s', e)
        except Exception as e:
            logger.error('Unexpected DHT22 error: %s', e)
        time.sleep(2)
    return None, None

def main():
    try:
        import config
    except ImportError:
        logger.error('config.py not found')
        sys.exit(1)

    try:
        sensor = DHT22(InputDevice(config.dhtgpiopin))
    except Exception as e:
        logger.error('Failed to initialize DHT22 on pin %s: %s', config.dhtgpiopin, e)
        sys.exit(1)

    client = mqtt.Client(
        mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid,
        protocol=mqtt.MQTTv311
    )
    client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = lambda c, u, flags, rc: logger.info('MQTT rc=%s', rc)
    client.on_disconnect = lambda c, u, rc: logger.info('MQTT disconnected (rc=%s)', rc)

    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        client.loop_start()
    except Exception as e:
        logger.error('MQTT connection failed: %s', e)
        sensor.close()
        sys.exit(1)

    temp_topic = f'homie/{config.homieclientid}/{config.homienodes}/temperature'
    hum_topic = f'homie/{config.homieclientid}/{config.homienodes}/humidity'

    while running.is_set():
        temp, hum = read_dht22(sensor)
        if temp is not None and hum is not None:
            publish_message(client, temp_topic, f't {temp:.1f}')
            publish_message(client, hum_topic, f'h {hum:.1f}')
        else:
            logger.warning('Skipping publish due to read failure')
        time.sleep(config.publishtime)

    logger.info('Cleaning up...')
    try:
        client.loop_stop()
        client.disconnect()
    except Exception:
        pass
    try:
        sensor.close()
    except Exception:
        pass
    logger.info('Done.')

if __name__ == '__main__':
    main()

