    sys.exit(1)

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4            # BCM GPIO4 (physical pin 7)
LED_PIN = 17                 # BCM GPIO17 (physical pin 11)
TEMP_THRESHOLD_HIGH = 30.0   # °C
TEMP_THRESHOLD_LOW = 25.0    # °C
LOG_FILE = "hydroponics_data.log"
SAMPLE_INTERVAL = 5          # seconds

# --- Globals for cleanup -----------------------------------------------------
_running = True
_led_state = False

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    global _led_state
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        _led_state = False
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def _log(msg):
    ts = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    line = f"{ts} - {msg}"
    print(line)
    try:
        with open(LOG_FILE, "a") as f:
            f.write(line + "\n")
    except OSError as e:
        print(f"Failed to write log: {e}")

def _read_dht22(sensor):
    try:
        temp = sensor.temperature
        hum = sensor.humidity
        if temp is None or hum is None:
            raise RuntimeError("Sensor returned None")
        return temp, hum
    except Exception as e:
        raise RuntimeError(f"DHT22 read failed: {e}")

def _read_ds18b20():
    base = "/sys/bus/w1/devices/"
    try:
        devices = os.listdir(base)
    except OSError as e:
        raise RuntimeError(f"w1-gpio scan failed: {e}")
    if not devices:
        raise RuntimeError("No 1-Wire devices found")
    dev_path = os.path.join(base, devices[0], "w1_slave")
    try:
        with open(dev_path, "r") as f:
            lines = f.readlines()
    except OSError as e:
        raise RuntimeError(f"Cannot read {dev_path}: {e}")
    if len(lines) < 2 or "YES" not in lines[0]:
        raise RuntimeError("DS18B20 not ready (CRC check failed)")
    equals = lines[1].find("t=")
    if equals == -1:
        raise RuntimeError("Temperature field not found")
    raw = lines[1][equals + 2:].strip()
    temp = float(raw) / 1000.0
    return temp

def main():
    global _led_state

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    _led_state = False

    try:
        dht = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        _log(f"Failed to init DHT22: {e}")
        _cleanup()
        sys.exit(1)

    _log("Hydroponics monitor started")

    try:
        while _running:
            try:
                temp_dht, hum = _read_dht22(dht)
                temp_ds18b20 = _read_ds18b20()
                _log(f"DHT22: {temp_dht:.1f}C, {hum:.1f}%  |  DS18B20: {temp_ds18b20:.1f}C")

                if temp_dht > TEMP_THRESHOLD_HIGH and not _led_state:
                    GPIO.output(LED_PIN, GPIO.HIGH)
                    _led_state = True
                    _log("LED ON: temp above 30C")
                elif temp_dht < TEMP_THRESHOLD_LOW and _led_state:
                    GPIO.output(LED_PIN, GPIO.LOW)
                    _led_state = False
                    _log("LED OFF: temp below 25C")

            except RuntimeError as e:
                _log(f"Sensor error: {e}")
            except Exception as e:
                _log(f"Unexpected error: {e}")

            for _ in range(SAMPLE_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    finally:
        _cleanup()
        _log("Hydroponics monitor stopped")

if __name__ == "__main__":
    main()

