import smbus
import time
import signal
import sys

I2C_BUS = 1
AHT20_ADDR = 0x5F

running = True

def signal_handler(sig, frame):
    global running
    running = False

def crc8(data: bytes) -> int:
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ 0x31) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def read_aht20(bus: smbus.SMBus) -> tuple[float, float] | None:
    try:
        bus.write_byte(AHT20_ADDR, 0x71)
        time.sleep(0.02)
        bus.write_byte(AHT20_ADDR, 0x71)
        time.sleep(0.01)
        bus.write_byte(AHT20_ADDR, 0xBE)
        time.sleep(0.08)
        data = bus.read_i2c_block_data(AHT20_ADDR, 0x00, 7)
        if len(data) != 7:
            print("CRC error: incomplete data")
            return None
        if crc8(bytes(data[:6])) != data[6]:
            print("CRC error: mismatch")
            return None
        raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        humidity = (raw / 2**20) * 100.0
        temp_raw = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]
        temperature = (temp_raw / 2**20) * 200.0 - 50.0
        return temperature, humidity
    except IOError as e:
        print(f"I/O error reading AHT20: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading AHT20: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        bus = smbus.SMBus(I2C_BUS)
    except IOError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)
    try:
        while running:
            result = read_aht20(bus)
            if result is not None:
                temperature, humidity = result
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}  Temperature: {temperature:.2f}°C / {temperature * 9/5 + 32:.2f}°F  Humidity: {humidity:.2f}%")
            else:
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}  Read failed")
            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

