import serial
import time
import signal
import sys
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
ALERT_GPIO_PIN = 17
TEMPERATURE_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
ALERT_DURATION = 5
LOG_FILE_PATH = '/home/pi/sensor_log.txt'

running = True
uart = None

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global uart
    if uart is not None and uart.is_open:
        try:
            uart.close()
            logging.info("UART port closed.")
        except serial.SerialException as e:
            logging.error(f"Error closing UART: {e}")
    try:
        GPIO.output(ALERT_GPIO_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()
    logging.info("GPIO cleanup completed.")


def read_sensor_data(uart_port):
    try:
        raw = uart_port.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        logging.error(f"Error reading from serial port: {e}")
        return None
    except Exception as e:
        logging.error(f"Unexpected error reading from serial port: {e}")
        return None


def parse_sensor_data(data):
    if not data:
        return None, None
    try:
        parts = data.split(',')
        if len(parts) != 2:
            raise ValueError(f"Expected 2 fields, got {len(parts)}")
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError as e:
        logging.error(f"Error parsing sensor data: {e}")
        return None, None


def check_thresholds(temperature, humidity):
    return temperature > TEMPERATURE_THRESHOLD or humidity > HUMIDITY_THRESHOLD


def log_data(temperature, humidity):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%\n"
    try:
        with open(LOG_FILE_PATH, 'a') as log_file:
            log_file.write(log_entry)
        logging.info(f"Data logged: {log_entry.strip()}")
    except IOError as e:
        logging.error(f"Error writing to log file: {e}")


def activate_alert():
    try:
        GPIO.output(ALERT_GPIO_PIN, GPIO.HIGH)
        logging.warning("Alert triggered! GPIO17 set HIGH.")
        time.sleep(ALERT_DURATION)
    except Exception as e:
        logging.error(f"Error setting GPIO HIGH: {e}")
    finally:
        try:
            GPIO.output(ALERT_GPIO_PIN, GPIO.LOW)
            logging.info("Alert deactivated. GPIO17 set LOW.")
        except Exception as e:
            logging.error(f"Error setting GPIO LOW: {e}")


def main():
    global uart
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(ALERT_GPIO_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        sys.exit(1)

    try:
        uart = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=1
        )
        logging.info(f"Connected to serial port: {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        logging.error(f"Error opening serial port: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            sensor_data = read_sensor_data(uart)
            if sensor_data:
                temperature, humidity = parse_sensor_data(sensor_data)
                if temperature is not None and humidity is not None:
                    log_data(temperature, humidity)
                    if check_thresholds(temperature, humidity):
                        activate_alert()
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

