import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO is not installed. Install with: pip install RPi.GPIO")
    sys.exit(1)

# Configuration
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0  # seconds

# Global flag for graceful shutdown
_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def setup_gpio(pins):
    """Sets up GPIO pins as inputs with pull-up resistors."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in pins:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as e:
            print(f"Error setting up GPIO pin {pin}: {e}")
            raise


def read_sensor(pin):
    """Reads the state of a GPIO pin and returns True if HIGH, False if LOW."""
    try:
        return GPIO.input(pin) == GPIO.HIGH
    except Exception as e:
        print(f"Error reading GPIO pin {pin}: {e}")
        return False


def cleanup_gpio():
    """Cleans up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")


def main():
    """Main function to monitor sensor inputs and print responses."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        setup_gpio(SENSOR_PINS)
        print(f"Monitoring GPIO pins: {SENSOR_PINS}")
        print(f"Polling interval: {POLL_INTERVAL} seconds")
        print("Press Ctrl+C to exit.\n")

        while _running:
            for i, pin in enumerate(SENSOR_PINS):
                if read_sensor(pin):
                    print(f"Response for sensor {i + 1}")
            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

