    except OSError as exc:
        print(f"Error creating CSV file '{CSV_FILE}': {exc}", file=sys.stderr)


def log_event():
    timestamp = datetime.now().isoformat(timespec="seconds")
    try:
        with open(CSV_FILE, "a", newline="") as f:
