import signal
import threading
import time
from gpiozero import OutputDevice, Device
from gpiozero.pins.native import NativeFactory

# Use the native pin factory to avoid requiring pigpio daemon
Device.pin_factory = NativeFactory()


class OutputPin:
    """Represents a GPIO output pin with a name and value tracking."""

    def __init__(self, name: str, pin_number: int, initial_value: int = 0):
        if not isinstance(name, str) or not name:
            raise ValueError("name must be a non-empty string")
        if not isinstance(pin_number, int) or not (0 <= pin_number <= 27):
            raise ValueError("pin_number must be an integer between 0 and 27")
        if initial_value not in (0, 1):
            raise ValueError("initial_value must be 0 or 1")

        self.name = name
        self.pin_number = pin_number
        self.value = initial_value
        self._lock = threading.Lock()

        try:
            self.device = OutputDevice(pin_number, initial_value=initial_value)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize GPIO {pin_number} for {name}: {e}")

    def set_value(self, value: int) -> None:
        """Sets the pin value (0 or 1) atomically."""
        if value not in (0, 1):
            raise ValueError("value must be 0 or 1")
        with self._lock:
            self.value = value
            self.device.value = value

    def get_value(self) -> int:
        """Returns the current pin value."""
        with self._lock:
            return self.value

    def shutdown(self) -> None:
        """Reverts the pin to input mode and releases the device."""
        if self.device is not None:
            try:
                self.device.close()
            except Exception:
                pass
            self.device = None


class TriggerPin(OutputPin):
    """Represents a trigger pin that generates a short high pulse."""

    def __init__(self, name: str, pin_number: int, pulse_high: bool = True):
        super().__init__(name, pin_number, initial_value=0)
        self.pulse_high = pulse_high
        self._pulse_lock = threading.Lock()

    def trigger(self) -> None:
        """Generates a 100-microsecond high pulse on the pin."""
        with self._pulse_lock:
            if self.pulse_high:
                self.set_value(1)
            else:
                self.set_value(0)
            time.sleep(0.0001)
            self.set_value(0)


def main() -> None:
    output_pin = OutputPin("ExampleOutput", 21, initial_value=0)
    trigger_pin = TriggerPin("ExampleTrigger", 20, pulse_high=True)

    def cleanup(signum=None, frame=None):
        print("\nShutting down...")
        output_pin.shutdown()
        trigger_pin.shutdown()
        if signum is not None:
            raise SystemExit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        print(f"OutputPin '{output_pin.name}' on GPIO {output_pin.pin_number} initialized to {output_pin.get_value()}")
        print(f"TriggerPin '{trigger_pin.name}' on GPIO {trigger_pin.pin_number} initialized to {trigger_pin.get_value()}")
        trigger_pin.trigger()
        print("Trigger pulse generated.")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

