            fan.value = 0.0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global fan

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize PWM on GPIO{FAN_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected failure initializing GPIO{FAN_PIN}: {e}")
        sys.exit(1)

    print(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    print("Enter a speed percentage (0-100) or 'q' to quit.")

