import signal
import sys
import time

try:
    from rainbowhat import display, led, lstrip, touch
except ImportError:
    print("Error: rainbowhat library not installed. Install with: pip install rainbowhat", file=sys.stderr)
    sys.exit(1)

# Touchpad GPIO pins (BCM) and their bit weights
TOUCH_PINS = {5: 4, 6: 2, 12: 1}
# APA102 data and clock pins (BCM)
DATA_PIN = 10
CLOCK_PIN = 11
# Buzzer and status LED pins (BCM)
BUZZER_PIN = 13
GREEN_LED_PIN = 7
BLUE_LED_PIN = 8

bit_states = 0
running = True


def cleanup():
    """Turn off all peripherals cleanly."""
    try:
        display.clear()
        display.show()
    except Exception as e:
        print(f"Error clearing display: {e}", file=sys.stderr)
    try:
        led.all_off()
    except Exception as e:
        print(f"Error turning off LEDs: {e}", file=sys.stderr)
    try:
        lstrip.set_pixel(0, 0, 0, 0)
        lstrip.show()
    except Exception as e:
        print(f"Error turning off LED strip: {e}", file=sys.stderr)


def handle_signal(signum, frame):
    global running
    running = False


def update_discrete_leds():
    """Set discrete LEDs based on bit_states (0-7)."""
    try:
        led.set_pixel(0, 0, 0, 0)
        led.set_pixel(1, 0, 0, 0)
        led.set_pixel(2, 0, 0, 0)
        if bit_states & 1:
            led.set_pixel(0, 0, 0, 1)
        if bit_states & 2:
            led.set_pixel(1, 0, 0, 1)
        if bit_states & 4:
            led.set_pixel(2, 0, 0, 1)
        led.show()
    except Exception as e:
        print(f"Error updating discrete LEDs: {e}", file=sys.stderr)


def update_apa102():
    """Drive APA102 strip: dim white at index 0 when value 0, all white when value 7, else single pixel colored by A/B/C."""
    try:
        lstrip.clear()
        value = bit_states
        if value == 0:
            lstrip.set_pixel(0, 31, 31, 31)
        elif value == 7:
            for i in range(7):
                lstrip.set_pixel(i, 31, 31, 31)
        else:
            r = 31 if value & 4 else 0
            g = 31 if value & 2 else 0
            b = 31 if value & 1 else 0
            lstrip.set_pixel(value, r, g, b)
        lstrip.show()
    except Exception as e:
        print(f"Error updating APA102 strip: {e}", file=sys.stderr)


def update_display():
    """Write decimal value 0-7 to the 14-segment display."""
    try:
        display.clear()
        display.print_str(str(bit_states))
        display.show()
    except Exception as e:
        print(f"Error updating display: {e}", file=sys.stderr)


def update_buzzer():
    """Sound a 0.5-second tone and turn on green/blue status LEDs."""
    try:
        led.on(GREEN_LED_PIN)
        led.on(BLUE_LED_PIN)
        time.sleep(0.5)
        led.off(GREEN_LED_PIN)
        led.off(BLUE_LED_PIN)
    except Exception as e:
        print(f"Error updating buzzer/status LEDs: {e}", file=sys.stderr)


def toggle_bit(pin, weight):
    """Toggle the bit corresponding to the given touchpad pin and update all outputs."""
    global bit_states
    bit_states ^= weight
    update_discrete_leds()
    update_apa102()
    update_display()
    update_buzzer()


def main():
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Register touch event handlers
    for pin, weight in TOUCH_PINS.items():
        try:
            touch.on(pin, lambda p=pin, w=weight: toggle_bit(p, w))
        except Exception as e:
            print(f"Error registering touch event on GPIO{pin}: {e}", file=sys.stderr)

    print("Rainbow HAT 3-bit counter ready. Press Ctrl+C to exit.")
    try:
        while running:
            signal.pause()
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Cleanup complete.")


if __name__ == "__main__":
    main()

