import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)


class LEDController:
    """
    Controls an LED connected to a Raspberry Pi GPIO pin using gpiozero.

    Provides on(), off(), and blink() methods.  The LED is guaranteed to be
    turned off on any exit path, including SIGINT, SIGTERM, and exceptions.
    """

    def __init__(self, pin: int):
        """
        Initialize the LEDController.

        Args:
            pin: BCM GPIO pin number (e.g. 25 for physical pin 22).

        Raises:
            ValueError: If the pin number is invalid.
            GPIOZeroError: If the underlying gpiozero device cannot be created.
        """
        if not isinstance(pin, int) or isinstance(pin, bool):
