import signal
import sys
import time
import random
from neopixel import NeoPixel

# Configuration
LED_COUNT = 1
LED_PIN = 18
LED_FREQ_HZ = 800000
LED_DMA = 10
LED_BRIGHTNESS = 255
LED_INVERT = False
LED_CHANNEL = 0

strip = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global strip
    if strip is not None:
        try:
            strip.fill((0, 0, 0))
            strip.show()
        except Exception:
            pass
        try:
            strip.cleanup()
        except Exception:
            pass
        strip = None


def get_heart_rate():
    return random.randint(40, 130)


def get_step_count():
    return random.randint(0, 1000)


def main():
    global strip

    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    try:
        strip = NeoPixel(
            LED_COUNT,
            LED_PIN,
            LED_FREQ_HZ,
            LED_DMA,
            LED_INVERT,
            LED_BRIGHTNESS,
            LED_CHANNEL,
        )
    except Exception as e:
        print(f"Error initializing LED strip: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            heart_rate = get_heart_rate()
            step_count = get_step_count()

            if 60 <= heart_rate <= 100 and step_count > 100:
                color = (0, 255, 0)
            elif 50 <= heart_rate <= 59 or 101 <= heart_rate <= 120 or step_count <= 100:
                color = (255, 255, 0)
            else:
                color = (255, 0, 0)

            try:
                strip.fill(color)
                strip.show()
            except Exception as e:
                print(f"Error updating LED: {e}", file=sys.stderr)
                break

            if color != (255, 0, 0):
                time.sleep(0.5)
                continue

            try:
                strip.fill((255, 0, 0))
                strip.show()
                time.sleep(0.5)
                strip.fill((0, 0, 0))
                strip.show()
                time.sleep(0.5)
            except Exception as e:
                print(f"Error toggling LED: {e}", file=sys.stderr)
                break

    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

