#!/usr/bin/env python3
"""
ADXL345 accelerometer reader for Raspberry Pi.

Reads the ADXL345 on I2C bus 1, logs samples to data.txt, and triggers
WARNING-level alerts when the acceleration magnitude exceeds --threshold g.
Handles SIGINT/SIGTERM for graceful shutdown.
"""

import argparse
import csv
import logging
import signal
import sys
import time
from datetime import datetime, timezone

import smbus2

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
ADXL345_ADDRESS = 0x53
ADXL345_DEVID = 0xE5
ADXL345_POWER_CTL = 0x2D
ADXL345_DATAX0 = 0x32
ADXL345_BW_RATE = 0x2C
ADXL345_DEVID_MASK = 0xFF

# Graceful-shutdown flag
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _setup_logging():
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
        datefmt="%Y-%m-%dT%H:%M:%S%z",
    )


def _parse_args():
    p = argparse.ArgumentParser(
        description="ADXL345 accelerometer reader with magnitude threshold alert."
    )
    p.add_argument(
        "--sample_rate", type=float, default=10, help="Sampling rate in Hz (default: 10)"
    )
    p.add_argument(
        "--threshold", type=float, default=1.5, help="Magnitude threshold in g (default: 1.5)"
    )
    p.add_argument(
        "--log_file", type=str, default="data.txt", help="Output CSV log file (default: data.txt)"
    )
    return p.parse_args()


def _open_i2c_bus(bus_number: int = 1):
    try:
        return smbus2.SMBus(bus_number)
    except FileNotFoundError:
        logging.error("I2C bus %d not found. Enable I2C with 'sudo raspi-config'.", bus_number)
        return None
    except PermissionError:
        logging.error("Permission denied opening I2C bus %d. Run as root or add user to 'i2c' group.", bus_number)
        return None
    except OSError as exc:
        logging.error("Failed to open I2C bus %d: %s", bus_number, exc)
        return None


def _read_acceleration(bus, address):
    """Read (x, y, z) acceleration in g. Returns (None, None, None) on error."""
    try:
        data = bus.read_i2c_block_data(address, ADXL345_DATAX0, 6)
    except OSError as exc:
        logging.error("I2C read error at register 0x%02X: %s", ADXL345_DATAX0, exc)
        return None, None, None

    if len(data) != 6:
        logging.error("Unexpected data length: %d bytes", len(data))
        return None, None, None

    x = (data[1] << 8) | data[0]
    y = (data[3] << 8) | data[2]
    z = (data[5] << 8) | data[4]

    # Convert to signed 16-bit
    if x >= 0x8000:
        x -= 0x10000
    if y >= 0x8000:
        y -= 0x10000
    if z >= 0x8000:
        z -= 0x10000

    return x, y, z


def _acceleration_to_g(x, y, z):
    return (x / 256.0, y / 256.0, z / 256.0)


def _magnitude(x_g, y_g, z_g):
    return (x_g * x_g + y_g * y_g + z_g * z_g) ** 0.5


def _verify_sensor(bus, address):
    """Return True if the ADXL345 is present and has the correct device ID."""
    try:
        devid = bus.read_byte_data(address, ADXL345_DEVID)
    except OSError as exc:
        logging.error("Cannot read DEVID register: %s", exc)
        return False

    if devid != ADXL345_DEVID:
        logging.error(
            "Device ID mismatch: got 0x%02X, expected 0x%02X (not an ADXL345).",
            devid, ADXL345_DEVID,
        )
        return False

    return True


def _init_sensor(bus, address):
    """Power on the ADXL345 and set data rate to 100 Hz (10 Hz sample rate)."""
    try:
        bus.write_byte_data(address, ADXL345_POWER_CTL, 0x08)  # Measure mode
    except OSError as exc:
        logging.error("Failed to set power control: %s", exc)
        raise

    try:
        bus.write_byte_data(address, ADXL345_BW_RATE, 0x0A)  # 100 Hz data rate
    except OSError as exc:
        logging.error("Failed to set data rate: %s", exc)
        raise


def _main():
    global _running

    _setup_logging()
    args = _parse_args()

    if args.sample_rate <= 0:
        logging.error("Sample rate must be positive, got %s", args.sample_rate)
        sys.exit(1)

    if args.threshold < 0:
        logging.error("Threshold must be non-negative, got %s", args.threshold)
        sys.exit(1)

    bus = _open_i2c_bus(1)
    if bus is None:
        sys.exit(0)

    try:
        if not _verify_sensor(bus, ADXL345_ADDRESS):
            logging.error("ADXL345 not detected. Exiting.")
            sys.exit(0)

        _init_sensor(bus, ADXL345_ADDRESS)
        logging.info("ADXL345 initialized (100 Hz data rate, measure mode).")

        signal.signal(signal.SIGINT, _signal_handler)
        signal.signal(signal.SIGTERM, _signal_handler)

        sample_interval = 1.0 / args.sample_rate
        last_info = 0.0

        with open(args.log_file, "a", newline="") as fh:
            writer = csv.writer(fh)
            writer.writerow(["timestamp", "x_g", "y_g", "z_g", "magnitude"])

            while _running:
                loop_start = time.monotonic()

                x, y, z = _read_acceleration(bus, ADXL345_ADDRESS)
                if x is None:
                    time.sleep(sample_interval)
                    continue

                x_g, y_g, z_g = _acceleration_to_g(x, y, z)
                magnitude = _magnitude(x_g, y_g, z_g)

                timestamp = datetime.now(timezone.utc).isoformat()
                writer.writerow([timestamp, f"{x_g:.4f}", f"{y_g:.4f}", f"{z_g:.4f}", f"{magnitude:.4f}"])
                fh.flush()

                if magnitude > args.threshold:
                    logging.warning(
                        "Acceleration magnitude %.4f g exceeds threshold %.2f g", magnitude, args.threshold
                    )

                now = time.monotonic()
                if now - last_info >= 1.0:
                    logging.info("Sampling at %d Hz, threshold=%.2f g", args.sample_rate, args.threshold)
                    last_info = now

                elapsed = time.monotonic() - loop_start
                sleep_time = sample_interval - elapsed
                if sleep_time > 0:
                    time.sleep(sleep_time)

    except OSError as exc:
        logging.error("I2C communication error: %s", exc)
        sys.exit(1)
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
        sys.exit(1)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        logging.info("Program terminated.")


if __name__ == "__main__":
    _main()

