import smbus
import time

# MPU6050 accelerometer registers (AD0 low, default I2C address 0x68)
ACCEL_XOUT_H = 0x3B
ACCEL_YOUT_H = 0x3D
ACCEL_SCALE = 16384.0  # 2g range -> 16-bit signed full scale


def read_signed_word(bus, register):
    """Read a 16-bit signed value from two consecutive I2C registers."""
    high = bus.read_byte_data(0x68, register)
    low = bus.read_byte_data(0x68, register + 1)
    raw = (high << 8) | low
    if raw >= 0x8000:
        raw -= 0x10000
    return raw


def main():
    bus = None
    try:
        bus = smbus.SMBus(1)
        print("MPU6050 accelerometer demo for kids")
        print("Reading X and Y axes every 0.5 seconds...")

        for sample_index in range(5):
            x_raw = read_signed_word(bus, ACCEL_XOUT_H)
            y_raw = read_signed_word(bus, ACCEL_YOUT_H)
            x_g = x_raw / ACCEL_SCALE
            y_g = y_raw / ACCEL_SCALE

            if x_g < -0.1:
                print("tilting left")
            elif x_g > 0.1:
                print("tilting right")
            else:
                if y_g < -0.1:
                    print("tilting forward")
                elif y_g > 0.1:
                    print("tilting back")
                else:
                    print("level")

            time.sleep(0.5)

    except OSError as e:
        print(f"I2C error: {e}")
        print("Check that the MPU6050 is connected and the I2C bus is enabled.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            bus.close()
            print("I2C bus closed.")


if __name__ == "__main__":
    main()

