import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Configuration
ALERT_PIN = 18
QUALITY_THRESHOLD = 50
NUM_READINGS = 5
DELAY_SECONDS = 2


def read_water_quality():
    """Simulates reading water quality data (0-100%)."""
    return random.randint(0, 100)


def check_water_quality(quality, threshold):
    """Checks if water quality is below threshold and returns alert status."""
    return quality < threshold


def main():
    """Main function to simulate water quality monitoring."""
    try:
        # Initialize LED on BCM pin 18
        alert_led = LED(ALERT_PIN)

        for i in range(NUM_READINGS):
            water_quality = read_water_quality()
            alert = check_water_quality(water_quality, QUALITY_THRESHOLD)

            print(f"Reading {i + 1}/{NUM_READINGS} - Water Quality: {water_quality}%")
            print(f"Alert: {'YES' if alert else 'NO'}")

            # Drive the LED based on the alert status
            if alert:
                alert_led.on()
            else:
                alert_led.off()

            if i < NUM_READINGS - 1:
                time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    finally:
        # gpiozero automatically cleans up resources on garbage collection,
        # but we explicitly close the LED to ensure the pin is released.
        try:
            alert_led.close()
        except NameError:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

