import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_moisture_level():
    return random.randint(0, 100)

def control_water_pump(moisture_level):
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        print(f"Water Pump ON: Moisture level {moisture_level} is below threshold {MOISTURE_THRESHOLD}.")
    else:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        print(f"Water Pump OFF: Moisture level {moisture_level} is above threshold {MOISTURE_THRESHOLD}.")

def cleanup():
    try:
        GPIO.output(PUMP_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()
    print("GPIO cleanup completed.")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        sys.exit(1)

    try:
        for i in range(ITERATIONS):
            if not _running:
                break
            moisture = read_moisture_level()
            control_water_pump(moisture)
            if i < ITERATIONS - 1 and _running:
                time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

