    global _running
    _running = False

def read_moisture_level(current_level):
    return max(0, current_level - MOISTURE_DECREMENT)

def control_led(moisture_level):
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(LED_PIN, GPIO.HIGH)
        return "ON"
    else:
        GPIO.output(LED_PIN, GPIO.LOW)
        return "OFF"

def cleanup():
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

