import time
import logging
import signal
import sys

try:
    from gpiozero import Servo
    from gpiozero.pins.pigpio import PiGPIOFactory
    _GPIOZERO_AVAILABLE = True
except ImportError:
    _GPIOZERO_AVAILABLE = False

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

SERVO_PIN = 18
PWM_FREQUENCY = 50
STEP_DELAY = 0.5


class ServoController:
    """Control a micro servo via gpiozero Servo with robust cleanup."""

    def __init__(self, pin, frequency=50):
        if not _GPIOZERO_AVAILABLE:
            raise RuntimeError("gpiozero is not installed; install with: pip install gpiozero pigpio")
        self.pin = pin
        self.frequency = frequency
        self.servo = None
        self._initialized = False
        try:
            factory = PiGPIOFactory()
            self.servo = Servo(
                pin,
                pin_factory=factory,
                min_pulse_width=0.5 / 1000,
                max_pulse_width=2.5 / 1000,
            )
            self.servo.value = 0
            self._initialized = True
            logging.info("Servo controller initialized on GPIO %d at %d Hz", pin, frequency)
        except Exception as exc:
            logging.error("Failed to initialize servo on GPIO %d: %s", pin, exc)
            self._cleanup()
            raise

    def _angle_to_value(self, angle):
        """Map a 0-180 degree angle to a gpiozero Servo value (-1..1)."""
        if not 0 <= angle <= 180:
            raise ValueError(f"Angle must be between 0 and 180, got {angle}")
        return (angle / 180.0) * 2.0 - 1.0

    def move_to(self, angle):
        """Move the servo to the specified angle (0-180 degrees)."""
        if not self._initialized:
            raise RuntimeError("Servo controller not initialized")
        value = self._angle_to_value(angle)
        try:
            self.servo.value = value
            logging.info("Moving servo to angle: %d degrees (value: %.2f)", angle, value)
        except Exception as exc:
            logging.error("Failed to move servo to %d degrees: %s", angle, exc)
            raise

    def stop(self):
        """Stop the servo and release resources."""
        if self._initialized and self.servo is not None:
            try:
                self.servo.value = 0
                self.servo.close()
                logging.info("Servo stopped and resources released")
            except Exception as exc:
                logging.error("Error stopping servo: %s", exc)
            finally:
                self._initialized = False

    def _cleanup(self):
        """Best-effort cleanup of the servo instance."""
        if self._initialized and self.servo is not None:
            try:
                self.servo.value = 0
                self.servo.close()
            except Exception:
                pass
            finally:
                self._initialized = False


def run_sweep(controller, angles):
    """Sweep the servo through a list of angles, then return to 0."""
    if not controller._initialized:
        raise RuntimeError("Servo controller not initialized")
    for angle in angles:
        controller.move_to(angle)
        time.sleep(STEP_DELAY)
    controller.move_to(0)
    time.sleep(STEP_DELAY)


def main():
    controller = None
    try:
        controller = ServoController(SERVO_PIN, PWM_FREQUENCY)
        angles = [0, 45, 90, 135, 180]
        run_sweep(controller, angles)
        logging.info("Sweep completed successfully")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as exc:
        logging.error("An error occurred: %s", exc)
    finally:
        if controller is not None:
            controller.stop()


if __name__ == "__main__":
    main()

