import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQ = 50

MIN_PULSE_US = 1000
MAX_PULSE_US = 2000
MIN_ANGLE = 0
MAX_ANGLE = 180
HOLD_TIME_S = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def angle_to_duty(angle):
    if not (MIN_ANGLE <= angle <= MAX_ANGLE):
        raise ValueError(f"Angle {angle} out of range [{MIN_ANGLE}, {MAX_ANGLE}]")
    pulse_us = MIN_PULSE_US + (angle / MAX_ANGLE) * (MAX_PULSE_US - MIN_PULSE_US)
    return pulse_us / 1000.0 / (1.0 / PWM_FREQ)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SERVO_PIN, GPIO.OUT)
    pwm = GPIO.PWM(SERVO_PIN, PWM_FREQ)
    pwm.start(0)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        pwm.stop()
        GPIO.cleanup()
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            try:
                angle_str = raw.decode('ascii', errors='replace').strip()
                if not angle_str:
                    continue
                angle = int(angle_str)
            except ValueError:
                print(f"Invalid data received (not an integer): {raw!r}", file=sys.stderr)
                continue

            try:
                duty = angle_to_duty(angle)
            except ValueError:
                print(f"Invalid angle {angle}", file=sys.stderr)
                continue

            try:
                pwm.ChangeDutyCycle(duty)
                time.sleep(HOLD_TIME_S)
                pwm.ChangeDutyCycle(0)
            except Exception as e:
                print(f"Servo control error: {e}", file=sys.stderr)
                break
    finally:
        try:
            pwm.stop()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass
        GPIO.cleanup()

if __name__ == '__main__':
    main()

