import signal
import sys
import time
import logging
from typing import Optional, Tuple

from pymodbus.client import ModbusSerialClient
from pymodbus.exceptions import ModbusException
from pymodbus.payload import BinaryPayloadDecoder
from pymodbus.constants import Endian

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("ModbusServo")

# Constants for servo motor control
SERVO_MODBUS_ADDRESS = 1
SERVO_REGISTER_POSITION = 0
SERVO_REGISTER_SPEED = 1
SERVO_REGISTER_TORQUE = 2
SERVO_REGISTER_STATUS = 3
SERVO_REGISTER_VERSION = 4

# Error codes
ERROR_OK = 0
ERROR_MODBUS = 1
ERROR_SERIAL = 2
ERROR_INVALID_INPUT = 3
ERROR_TIMEOUT = 4
ERROR_NOT_INITIALIZED = 5
ERROR_READBACK_MISMATCH = 6


class ServoMotor:
    """Modbus RTU driver for a servo motor over a serial bus."""

    def __init__(
        self,
        port: str = "/dev/serial0",
        baudrate: int = 115200,
        timeout: float = 1.0,
        unit_id: int = SERVO_MODBUS_ADDRESS,
    ) -> None:
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.unit_id = unit_id
        self.client: Optional[ModbusSerialClient] = None
        self._initialized = False

    def connect(self) -> int:
        """Open the serial port and verify the Modbus unit responds."""
        if self._initialized:
            logger.warning("Servo already initialized; reconnecting.")
            self.disconnect()

        try:
            self.client = ModbusSerialClient(
                port=self.port,
                baudrate=self.baudrate,
                parity="N",
                stopbits=1,
                bytesize=8,
                timeout=self.timeout,
            )
        except Exception as exc:
            logger.error("Failed to create ModbusSerialClient for %s: %s", self.port, exc)
            return ERROR_SERIAL

        try:
            if not self.client.connect():
                logger.error("Failed to open serial port %s", self.port)
                self.client = None
                return ERROR_SERIAL
        except Exception as exc:
            logger.error("Serial port %s open failed: %s", self.port, exc)
            self.client = None
            return ERROR_SERIAL

        try:
            # Probe the unit by reading the version register.
            resp = self.client.read_holding_registers(
                address=SERVO_REGISTER_VERSION,
                count=1,
                slave=self.unit_id,
            )
            if resp.isError():
                logger.error("Modbus probe failed (unit %d): %s", self.unit_id, resp)
                self.client.close()
                self.client = None
                return ERROR_MODBUS
        except Exception as exc:
            logger.error("Modbus probe failed (unit %d): %s", self.unit_id, exc)
            self.client.close()
            self.client = None
            return ERROR_MODBUS

        self._initialized = True
        logger.info("Connected to servo unit %d on %s @ %d baud", self.unit_id, self.port, self.baudrate)
        return ERROR_OK

    def disconnect(self) -> None:
        """Close the serial connection if open."""
        if self.client is not None:
            try:
                self.client.close()
            except Exception as exc:
                logger.warning("Error closing serial port: %s", exc)
            finally:
                self.client = None
                self._initialized = False
        logger.info("Disconnected from servo.")

    def _read_register(self, address: int, count: int = 1) -> Optional[int]:
        """Read a holding register and return its value, or None on error."""
        if not self._initialized or self.client is None:
            logger.error("Servo not initialized; cannot read register %d", address)
            return None
        try:
            resp = self.client.read_holding_registers(
                address=address,
                count=count,
                slave=self.unit_id,
            )
            if resp.isError():
                logger.error("Modbus read error at register %d: %s", address, resp)
                return None
            if resp.isError():
                return None
            decoder = BinaryPayloadDecoder.fromRegisters(resp.registers, byteorder=Endian.BIG)
            return decoder.decode_16bit_int()
        except Exception as exc:
            logger.error("Modbus read exception at register %d: %s", address, exc)
            return None

    def _write_register(self, address: int, value: int) -> bool:
        """Write a 16-bit value to a holding register; return True on success."""
        if not self._initialized or self.client is None:
            logger.error("Servo not initialized; cannot write register %d", address)
            return False
        try:
            self.client.write_register(
                address=address,
                value=value,
                slave=self.unit_id,
            )
            return True
        except Exception as exc:
            logger.error("Modbus write exception at register %d: %s", address, exc)
            return False

    def get_position(self) -> Optional[int]:
        """Read the current position register."""
        return self._read_register(SERVO_REGISTER_POSITION)

    def get_speed(self) -> Optional[int]:
        """Read the current speed register."""
        return self._read_register(SERVO_REGISTER_SPEED)

    def get_torque(self) -> Optional[int]:
        """Read the current torque register."""
        return self._read_register(SERVO_REGISTER_TORQUE)

    def get_status(self) -> Optional[int]:
        """Read the status register."""
        return self._read_register(SERVO_REGISTER_STATUS)

    def set_position(self, position: int) -> bool:
        """Command the servo to move to the specified position."""
        if not isinstance(position, int) or not (-32768 <= position <= 32767):
            logger.error("Position %r out of 16-bit range", position)
            return False
        return self._write_register(SERVO_REGISTER_POSITION, position)

    def set_speed(self, speed: int) -> bool:
        """Command the servo to move at the specified speed."""
        if not isinstance(speed, int) or not (-32768 <= speed <= 32767):
            logger.error("Speed %r out of 16-bit range", speed)
            return False
        return self._write_register(SERVO_REGISTER_SPEED, speed)

    def set_torque(self, torque: int) -> bool:
        """Enable or disable torque."""
        if not isinstance(torque, int) or not (0 <= torque <= 32767):
            logger.error("Torque %r out of 16-bit range", torque)
            return False
        return self._write_register(SERVO_REGISTER_TORQUE, torque)

    def get_version(self) -> Optional[int]:
        """Read the firmware version register."""
        return self._read_register(SERVO_REGISTER_VERSION)

    def is_moving(self) -> bool:
        """Return True if the motor is currently moving."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x01) != 0

    def is_torque_enabled(self) -> bool:
        """Return True if torque is currently enabled."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x02) != 0

    def is_position_limit(self) -> bool:
        """Return True if a position limit has been reached."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x04) != 0

    def is_temperature_limit(self) -> bool:
        """Return True if the temperature limit has been reached."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x08) != 0

    def is_input_limit(self) -> bool:
        """Return True if an input limit has been reached."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x10) != 0

    def is_overheating(self) -> bool:
        """Return True if the motor is overheating."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x20) != 0

    def is_low_voltage(self) -> bool:
        """Return True if the voltage is too low."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x40) != 0

    def is_high_voltage(self) -> bool:
        """Return True if the voltage is too high."""
        status = self.get_status()
        if status is None:
            return False
        return (status & 0x80) != 0


def _signal_handler(signum, frame, servo: Optional[ServoMotor]) -> None:
    """Handle SIGINT/SIGTERM by disconnecting cleanly."""
    logger.info("Signal %d received; shutting down.", signum)
    if servo is not None:
        servo.disconnect()
    sys.exit(0)


def main() -> int:
    servo = ServoMotor(port="/dev/serial0", baudrate=115200, timeout=1.0)
    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, servo))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, servo))

    result = ERROR_OK
    try:
        result = servo.connect()
        if result != ERROR_OK:
            logger.error("Connection failed with error code %d", result)
            return 0

        # Command the motor to move to position 0.
        if not servo.set_position(0):
            logger.error("Failed to set position 0")
            return 0

        # Wait for the motor to reach the target.
        deadline = time.monotonic() + 5.0
        while servo.is_moving() and time.monotonic() < deadline:
            time.sleep(0.05)

        if servo.is_moving():
            logger.warning("Motor did not reach position 0 within 5 s")
        else:
            pos = servo.get_position()
            if pos is None:
                logger.error("Failed to read back position")
            else:
                logger.info("Motor reached position %d", pos)

        # Read and log status registers.
        status = servo.get_status()
        if status is not None:
            logger.info("Status: 0x%04X", status)
        else:
            logger.error("Failed to read status register")

        torque = servo.get_torque()
        if torque is not None:
            logger.info("Torque: %d", torque)
        else:
            logger.error("Failed to read torque register")

        speed = servo.get_speed()
        if speed is not None:
            logger.info("Speed: %d", speed)
        else:
            logger.error("Failed to read speed register")

        version = servo.get_version()
        if version is not None:
            logger.info("Firmware version: %d", version)
        else:
            logger.error("Failed to read version register")

    except Exception as exc:
        logger.error("Unexpected error: %s", exc)
        return 0
    finally:
        servo.disconnect()

    return 0


if __name__ == "__main__":
    sys.exit(main())

