import time
import signal
import sys
import logging
from typing import Optional

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

PCA9685_ADDR = 0x40
I2C_BUS = 1
PCA9685_REG_MODE1 = 0x00
PCA9685_REG_PRESCALE = 0xFE
PCA9685_REG_LED0_ON_L = 0x06
PCA9685_LED_STEP = 4

BASE_CHANNEL = 0
DROP_CHANNEL = 1
SEEK_CHANNEL = 2
GRAB_CHANNEL = 4

METAL_DROP_ANGLE = 135
PLASTIC_DROP_ANGLE = 180
PAPER_DROP_ANGLE = 90

DEFAULT_BASE_ANGLE = 90
DEFAULT_GRAB_ANGLE = 120
DEFAULT_SEEK_ANGLE = 90

PCA9685_MODE1_SLEEP = 0x10
PCA9685_MODE1_RESTART = 0x80


class PCA9685ServoController:
    def __init__(self, bus_num: int = I2C_BUS, addr: int = PCA9685_ADDR):
        self.addr = addr
        self.bus_num = bus_num
        self.bus: Optional[SMBus] = None
        self._initialized = False
        self._original_sigint = None
        self._original_sigterm = None
        self._channels = [0] * 16

    def begin(self) -> bool:
        try:
            self.bus = SMBus(self.bus_num)
        except FileNotFoundError:
            logger.error(f"I2C bus {self.bus_num} not found. Enable I2C with 'sudo raspi-config'.")
            return False
        except PermissionError:
            logger.error(f"Permission denied on I2C bus {self.bus_num}. Run as root or add user to 'i2c' group.")
            return False
        except OSError as e:
            logger.error(f"Failed to open I2C bus {self.bus_num}: {e}")
            return False

        try:
            old_mode = self.bus.read_byte_data(self.addr, PCA9685_REG_MODE1)
            self.bus.write_byte_data(self.addr, PCA9685_REG_MODE1, (old_mode & ~PCA9685_MODE1_SLEEP) | PCA9685_MODE1_RESTART)
            time.sleep(0.005)
            prescale = 2500 - (1000 / 4096) - 1
            self.bus.write_byte_data(self.addr, PCA9685_REG_PRESCALE, int(round(prescale)))
            self.bus.write_byte_data(self.addr, PCA9685_REG_MODE1, old_mode)
            time.sleep(0.005)
            self._initialized = True
            logger.info(f"PCA9685 initialized on bus {self.bus_num} at address 0x{self.addr:02X}.")
            return True
        except OSError as e:
            logger.error(f"Failed to initialize PCA9685 at 0x{self.addr:02X}: {e}")
            self.close()
            return False

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
