import signal
import sys
import time

import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice

PUMP_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_S = 10

_running = True
_pump = None


def _handle_signal(signum, frame):
    global _running
    _running = False


def _safe_pump_off():
    if _pump is not None:
        try:
            _pump.off()
        except Exception:
            pass


def main():
    global _pump

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        print(f"Failed to initialize pump GPIO{PUMP_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Failed to initialize I2C bus: {exc}", file=sys.stderr)
        _safe_pump_off()
        sys.exit(1)

    try:
        soil_sensor = adafruit_seesaw.seesaw.Seesaw(i2c, addr=0x36)
    except Exception as exc:
        print(f"Seesaw sensor not found at I2C 0x36: {exc}", file=sys.stderr)
        _safe_pump_off()
        sys.exit(1)

    print("Soil moisture monitor started. Press Ctrl+C to stop.")

    while _running:
        try:
            moisture_level = soil_sensor.moisture_read()
            print(f"Soil Moisture Level: {moisture_level}")

            if moisture_level < DRY_SOIL_THRESHOLD:
                _pump.on()
                print("Water Pump Status: ON")
            else:
                _pump.off()
                print("Water Pump Status: OFF")

        except Exception as exc:
            print(f"Error reading sensor or controlling pump: {exc}", file=sys.stderr)
            _safe_pump_off()

        for _ in range(READ_INTERVAL_S):
            if not _running:
                break
            time.sleep(1)

    _safe_pump_off()
    if _pump is not None:
        _pump.close()
    print("Program terminated. Pump is off.")


if __name__ == "__main__":
    main()

