import http.server
import json
import signal
import sys
import traceback

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

RELAY_PIN = 23
HOST_NAME = "0.0.0.0"
HOST_PORT = 5000

relay = None
httpd = None


def cleanup(signum=None, frame=None):
    """Release GPIO resources and stop the HTTP server on exit."""
    global relay, httpd
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def handle_relay_request(payload, relay_dev):
    """Parse and validate the JSON payload, then drive the relay.

    Returns a (status_code, body) tuple.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "Invalid request: payload must be a JSON object"}
    if "state" not in payload:
        return 400, {"error": "Invalid request: 'state' key is required"}
    state = payload["state"]
    if state not in ("on", "off"):
        return 400, {"error": "Invalid request: 'state' must be 'on' or 'off'"}
    try:
        relay_dev.value = 1 if state == "on" else 0
    except (GPIOZeroError, GPIODeviceError) as exc:
        return 500, {"error": f"GPIO error: {exc}"}
    return 200, {"status": "Relay state changed"}


class RelayRequestHandler(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path != "/relay":
            self.send_error(404, "Not Found")
            return
        try:
            content_length = int(self.headers.get("Content-Length", 0))
            if content_length <= 0:
                self.send_error(400, "Invalid request: empty payload")
                return
            post_data = self.rfile.read(content_length)
            payload = json.loads(post_data.decode("utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            self.send_error(400, f"Invalid request: {exc}")
            return
        except Exception as exc:
            self.send_error(500, f"Internal server error: {exc}")
            return
        status_code, body = handle_relay_request(payload, relay)
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(body).encode("utf-8"))

    def log_message(self, format, *args):
        print(f"{self.address_string()} - {format % args}", file=sys.stderr)


def main():
    global relay, httpd
    try:
        relay = OutputDevice(RELAY_PIN)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Failed to initialize GPIO{RELAY_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        httpd = http.server.HTTPServer((HOST_NAME, HOST_PORT), RelayRequestHandler)
        print(f"Listening on {HOST_NAME}:{HOST_PORT} (GPIO{RELAY_PIN})")
        httpd.serve_forever()
    except Exception as exc:
        print(f"Server error: {exc}", file=sys.stderr)
        traceback.print_exc(file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

