import time
import signal
import sys
from typing import Optional

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit-circuitpython-servokit is not installed.")
    print("Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_BUS = 1
I2C_ADDRESS = 0x40          # PCA9685 default address (A0–A5 tied to GND)
SERVO_CHANNEL = 0           # Channel 0 on the PCA9685
STEP_SIZE = 5               # Degrees per step
STEP_DELAY = 0.04           # Seconds between steps
MIN_ANGLE = 0
MAX_ANGLE = 180


# ---------------------------------------------------------------------------
# Graceful shutdown flag
# ---------------------------------------------------------------------------
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


# ---------------------------------------------------------------------------
# ServoKit wrapper
# ---------------------------------------------------------------------------
class ServoKitWrapper:
    """Thin wrapper around adafruit_servokit.ServoKit with robust error
    handling and guaranteed cleanup."""

    def __init__(self, channels: int = 16, address: int = I2C_ADDRESS,
                 i2c_bus: int = I2C_BUS) -> None:
        self._kit: Optional[ServoKit] = None
        try:
            self._kit = ServoKit(channels=channels, address=address,
                                 i2c=i2c_bus)
        except (OSError, ValueError) as exc:
            raise RuntimeError(
                f"Failed to initialize ServoKit on I2C bus {i2c_bus} "
                f"at address 0x{address:02X}: {exc}"
            ) from exc

    def __enter__(self) -> "ServoKitWrapper":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.cleanup()

    def cleanup(self) -> None:
        """Release the underlying I2C bus and de-energize all channels."""
        if self._kit is None:
            return
        try:
            for ch in range(self._kit.channels):
                try:
                    self._kit.servo[ch].angle = None
                except Exception:
                    pass
        except Exception:
            pass
        self._kit = None

    def move_servo(self, channel: int, target_angle: int) -> None:
        """Move *channel* toward *target_angle* in STEP_SIZE-degree steps."""
        if self._kit is None:
            raise RuntimeError("ServoKit not initialized.")
        if not (0 <= channel < 16):
            raise ValueError(f"Channel must be 0-15, got {channel}.")
        if not (MIN_ANGLE <= target_angle <= MAX_ANGLE):
            raise ValueError(
                f"Target angle {target_angle} out of range {MIN_ANGLE}-{MAX_ANGLE}."
            )

        current = self._kit.servo[channel].angle
        if current is None:
            current = MIN_ANGLE

        if target_angle == current:
            return

        step = STEP_SIZE if target_angle > current else -STEP_SIZE
        angle = current
        while _running and (step > 0 and angle < target_angle
                            or step < 0 and angle > target_angle):
            angle += step
            # Clamp to target so the final step lands exactly there
            if step > 0 and angle >= target_angle:
                angle = target_angle
            elif step < 0 and angle <= target_angle:
                angle = target_angle

            try:
                self._kit.servo[channel].angle = angle
            except (OSError, ValueError) as exc:
                raise RuntimeError(
                    f"Failed to move channel {channel} to {angle}°: {exc}"
                ) from exc

            if _running:
                time.sleep(STEP_DELAY)

    def grab_object(self, channel: int = SERVO_CHANNEL) -> None:
        """Move channel to 90° (grab position)."""
        self.move_servo(channel, 90)

    def release_object(self, channel: int = SERVO_CHANNEL) -> None:
        """Move channel to 150° (release position)."""
        self.move_servo(channel, 150)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    try:
        with ServoKitWrapper() as kit:
            print("ServoKit initialized. Running grab -> release sequence.")
            kit.grab_object()
            time.sleep(1)
            kit.release_object()
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except RuntimeError as exc:
        print(f"Runtime error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")


if __name__ == "__main__":
    main()

