import signal
import sys
import time
import logging
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

SOLENOID_PIN = 24
PULSE_COUNT = 3
PULSE_DURATION = 0.4
DELAY_BETWEEN_PULSES = 1.0


class SolenoidController:
    def __init__(self, pin: int):
        self.pin = pin
        self.device: OutputDevice | None = None
        try:
            self.device = OutputDevice(pin)
            self.device.off()
            logging.info("Solenoid relay initialized on GPIO%d (BCM).", pin)
        except (GPIOZeroError, GPIODeviceError) as exc:
            logging.error("Failed to initialize solenoid on GPIO%d: %s", pin, exc)
            raise

    def activate(self, duration: float) -> None:
        if self.device is None:
            raise RuntimeError("Solenoid device is not initialized.")
        try:
            self.device.on()
            logging.info("Solenoid activated for %.2f seconds.", duration)
            time.sleep(duration)
        except (GPIOZeroError, GPIODeviceError) as exc:
            logging.error("Error during solenoid activation: %s", exc)
            raise
        finally:
            self.device.off()
            logging.info("Solenoid deactivated.")

    def pulse(self, count: int, duration: float, delay: float) -> None:
        for i in range(1, count + 1):
            logging.info("Pulse %d/%d", i, count)
            self.activate(duration)
            if i < count:
                time.sleep(delay)

    def cleanup(self) -> None:
        if self.device is not None:
            try:
                self.device.off()
                self.device.close()
                logging.info("Solenoid relay cleaned up.")
            except Exception as exc:
                logging.error("Error during cleanup: %s", exc)


def main() -> int:
    controller: SolenoidController | None = None
    try:
        controller = SolenoidController(SOLENOID_PIN)
        controller.pulse(PULSE_COUNT, PULSE_DURATION, DELAY_BETWEEN_PULSES)
        return 0
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
        return 130
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
        return 1
    finally:
        if controller is not None:
            controller.cleanup()


def _signal_handler(signum, frame):
    logging.info("Received signal %d, shutting down.", signum)
    sys.exit(130)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    sys.exit(main())

