import json
import logging
import os
import sys
import time

try:
    import smbus
except ImportError:
    smbus = None

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

# ---------------------------------------------------------------------------
# Logging configuration
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
CONFIG_FILE = 'irrigation_config.json'
I2C_BUS = 1
DS3231_ADDR = 0x68
DS3231_SECONDS_REG = 0x00
DS3231_MINUTES_REG = 0x01
DS3231_HOURS_REG = 0x02
DS3231_DAY_REG = 0x03
DS3231_DATE_REG = 0x04
DS3231_MONTH_REG = 0x05
DS3231_YEAR_REG = 0x06

DEFAULT_GPIO_PIN = 17
DEFAULT_REPEAT_COUNT = 3

# ---------------------------------------------------------------------------
# DS3231 helpers
# ---------------------------------------------------------------------------
def bcd_to_dec(bcd):
    """Convert a two-digit BCD byte to decimal."""
    return ((bcd >> 4) & 0x0F) * 10 + (bcd & 0x0F)


def get_current_time():
    """Read the DS3231 and return (year, month, day, hours, minutes, seconds).

    Falls back to the system clock if the RTC is unavailable.
    """
    if smbus is None:
        logger.warning('smbus module not available; using system clock.')
        return time.localtime()

    try:
        bus = smbus.SMBus(I2C_BUS)
    except Exception as exc:
        logger.warning(f'Cannot open I2C bus {I2C_BUS}: {exc}; using system clock.')
        return time.localtime()

    try:
        data = bus.read_i2c_block_data(DS3231_ADDR, DS3231_SECONDS_REG, 7)
    except Exception as exc:
        logger.warning(f'Cannot read DS3231 at 0x{DS3231_ADDR:02X}: {exc}; using system clock.')
        return time.localtime()

    seconds = bcd_to_dec(data[0] & 0x7F)
    minutes = bcd_to_dec(data[1] & 0x7F)
    hours = bcd_to_dec(data[2] & 0x3F)
    day = bcd_to_dec(data[3] & 0x07)
    date = bcd_to_dec(data[4] & 0x3F)
    month = bcd_to_dec(data[5] & 0x1F)
    year = bcd_to_dec(data[6]) + 2000

    return (year, month, date, hours, minutes, seconds)


# ---------------------------------------------------------------------------
# GPIO / OOK helpers
# ---------------------------------------------------------------------------
def setup_gpio(pin):
    """Configure *pin* as an output and drive it LOW."""
    if GPIO is None:
        logger.warning('RPi.GPIO not available; GPIO setup skipped.')
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        logger.info(f'GPIO {pin} configured as output (BCM).')
    except Exception as exc:
        logger.warning(f'GPIO setup failed on pin {pin}: {exc}')


def transmit_ook(code, pin, repeat_count=1):
    """Transmit *code* (a list of 0/1 ints) using OOK with 1 ms per bit.

    The entire code is repeated *repeat_count* times with a 10 ms gap
    between repeats.
    """
    if GPIO is None:
        logger.warning('RPi.GPIO not available; skipping OOK transmission.')
        return

    try:
        for repeat in range(repeat_count):
            for bit in code:
                GPIO.output(pin, GPIO.HIGH if bit else GPIO.LOW)
                time.sleep(0.001)
            if repeat < repeat_count - 1:
                time.sleep(0.01)
    except Exception as exc:
        logger.error(f'Error during OOK transmission: {exc}')


def cleanup_gpio():
    """Release GPIO resources."""
    if GPIO is None:
        return
    try:
        GPIO.cleanup()
        logger.info('GPIO cleanup completed.')
    except Exception as exc:
        logger.warning(f'GPIO cleanup failed: {exc}')


# ---------------------------------------------------------------------------
# Configuration loading
# ---------------------------------------------------------------------------
def load_config(config_file):
    """Load and validate the JSON configuration file."""
    if not os.path.isfile(config_file):
        raise FileNotFoundError(f'Configuration file not found: {config_file}')

    try:
        with open(config_file, 'r', encoding='utf-8') as fh:
            config = json.load(fh)
    except json.JSONDecodeError as exc:
        raise ValueError(f'Invalid JSON in configuration file: {exc}') from exc
    except OSError as exc:
        raise OSError(f'Error reading configuration file: {exc}') from exc

    required = {'zone1_on', 'zone1_off', 'zone2_on', 'zone2_off'}
    if not required.issubset(config):
        raise ValueError(
            f'Missing required keys in config: {required - set(config)}'
        )

    return config


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    if len(sys.argv) != 3:
        logger.error('Usage: python script.py <zone> <on|off>')
        sys.exit(0)

    zone = sys.argv[1]
    action = sys.argv[2]

    try:
        config = load_config(CONFIG_FILE)
    except (FileNotFoundError, ValueError, OSError) as exc:
        logger.error(f'Configuration error: {exc}')
        sys.exit(0)

    gpio_pin = config.get('gpio_pin', DEFAULT_GPIO_PIN)
    repeat_count = config.get('transmission_repeat', DEFAULT_REPEAT_COUNT)

    try:
        code = config[f'{zone.lower()}_{action}']
    except KeyError:
        logger.error(
            f'Invalid zone/action: {zone}/{action}. '
            f'Valid zones: zone1, zone2. Actions: on, off.'
        )
        sys.exit(0)

    if not isinstance(code, list) or len(code) != 12:
        logger.error(f'RF code must be a 12-bit list; got {code!r}')
        sys.exit(0)

    setup_gpio(gpio_pin)
    try:
        current_time = get_current_time()
        logger.info(
            f'Current time (RTC or system): {current_time[3]:02d}:{current_time[4]:02d}:{current_time[5]:02d}'
        )
        logger.info(f'Turning {zone} {action} using RF code: {code}')
        transmit_ook(code, gpio_pin, repeat_count)
        logger.info(f'{zone} {action} command transmitted successfully.')
    except Exception as exc:
        logger.error(f'Error during command execution: {exc}')
    finally:
        cleanup_gpio()


if __name__ == '__main__':
    main()

