import serial
import time
import signal
import sys
import re

OK_RESPONSE = b"OK"
ERROR_RESPONSE = b"ERROR"
FAIL_RESPONSE = b"FAIL"
ALREADY_CONNECTED_RESPONSE = b"ALREADY CONNECTED"
SEND_OK_RESPONSE = b"SEND OK"
SEND_FAILED_RESPONSE = b"SEND FAIL"
RECEIVE_OK_RESPONSE = b"RECEIVE OK"
RECEIVE_FAILED_RESPONSE = b"RECEIVE FAIL"
CLOSED_RESPONSE = b"CLOSED"
WIFI_CONNECTED_RESPONSE = b"WIFI CONNECTED"
WIFI_GOT_IP_RESPONSE = b"WIFI GOT IP"
WIFI_DISCONNECTED_RESPONSE = b"WIFI DISCONNECT"
IPD_PREFIX = (b"+IPD,").encode('utf-8')


class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.uart = None
        self._open_uart()

    def _open_uart(self):
        try:
            self.uart = serial.Serial(
                port=self.port,
                baudrate=self.baud_rate,
                timeout=self.timeout,
                write_timeout=self.timeout,
            )
        except serial.SerialException as exc:
            print(f"Error opening UART port {self.port}: {exc}", file=sys.stderr)
            self.uart = None

    def _send_command(self, command, timeout=None, wait_for=OK_RESPONSE):
        if self.uart is None:
            print("UART not initialized; cannot send command.", file=sys.stderr)
            return None
        try:
            self.uart.reset_input_buffer()
            self.uart.write(command)
            self.uart.flush()
        except serial.SerialException as exc:
            print(f"Error writing to UART: {exc}", file=sys.stderr)
            return None
        if timeout is None:
            timeout = self.timeout
        deadline = time.monotonic() + timeout
        response = b""
        while time.monotonic() < deadline:
            try:
                chunk = self.uart.read(1024)
            except serial.SerialException as exc:
                print(f"Error reading from UART: {exc}", file=sys.stderr)
                return None
            if chunk:
                response += chunk
                if wait_for in response:
                    return response
            else:
                break
        return None

    def test_connection(self):
        response = self._send_command(b"AT\r\n", wait_for=OK_RESPONSE)
        return response is not None

    def restart(self):
        response = self._send_command(b"AT+RST\r\n", wait_for=OK_RESPONSE)
        if response is None:
            return False
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"\r\n'.encode('utf-8')
        response = self._send_command(command, timeout=10.0, wait_for=WIFI_GOT_IP_RESPONSE)
        return response is not None

    def disconnect_wifi(self):
        response = self._send_command(b"AT+CWQAP\r\n", wait_for=OK_RESPONSE)
        return response is not None

    def get_ip(self):
        response = self._send_command(b"AT+CIFSR\r\n", wait_for=OK_RESPONSE)
        if response is None:
            return None
        try:
            match = re.search(rb'"sta/ip":"(\d+\.\d+\.\d+\.\d+)"', response)
            if match:
                return match.group(1).decode('utf-8')
        except Exception:
            pass
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        request = (
            f"{method} {url} HTTP/1.1\r\n"
            f"Host: {host}\r\n"
            f"Connection: close\r\n"
        )
        if headers:
            request += headers + "\r\n"
        request += f"\r\n"
        if data:
            request += data
        request_bytes = request.encode('utf-8')
        self._send_command(b"AT+CIPSTART=\"TCP\",\"" + host.encode('utf-8') + b"\"," + str(port).encode('utf-8') + b"\r\n", wait_for=ALREADY_CONNECTED_RESPONSE)
        if self._send_command(b"AT+CIPSEND\r\n", wait_for=SEND_OK_RESPONSE) is None:
            self._send_command(b"AT+CIPCLOSE\r\n", wait_for=OK_RESPONSE)
            return None
        response = self._send_command(request_bytes, wait_for=SEND_OK_RESPONSE)
        if response is None:
            self._send_command(b"AT+CIPCLOSE\r\n", wait_for=OK_RESPONSE)
            return None
        return response

    def receive_http_response(self, timeout=5.0):
        deadline = time.monotonic() + timeout
        response = b""
        while time.monotonic() < deadline:
            try:
                chunk = self.uart.read(1024)
            except serial.SerialException as exc:
                print(f"Error reading from UART: {exc}", file=sys.stderr)
                return None
            if chunk:
                response += chunk
                if IPD_PREFIX in response:
                    parts = response.split(IPD_PREFIX, 1)
                    if len(parts) > 1:
                        ipd_data = parts[1]
                        if b":" in ipd_data:
                            payload = ipd_data.split(b":", 1)[1]
                            if b"\r\n" in payload:
                                return payload.split(b"\r\n", 1)[0]
            else:
                break
        return None

    def close(self):
        if self.uart is not None:
            try:
                self.uart.close()
            except Exception:
                pass
            self.uart = None

    def __del__(self):
        self.close()


def _signal_handler(signum, frame):
    print("\nSignal received, closing UART...", file=sys.stderr)
    if 'esp' in globals() and isinstance(esp, ESP8266):
        esp.close()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    esp = None
    try:
        esp = ESP8266(port='/dev/serial0', baud_rate=115200, timeout=1.0)
        if esp.uart is None:
            print("Failed to open UART; exiting.", file=sys.stderr)
            sys.exit(1)
        if not esp.test_connection():
            print("ESP8266 not responding.", file=sys.stderr)
            sys.exit(1)
        print("ESP8266 connected.")
    except Exception as exc:
        print(f"Initialization error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if esp is not None:
            esp.close()

