import serial
import time
import signal
import sys
import logging
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] %(message)s',
)
log = logging.getLogger('radiation')

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup(ser):
    try:
        GPIO.output(ALARM_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()
    if ser is not None and ser.is_open:
        try:
            ser.close()
        except Exception:
            pass

def _parse_radiation(line):
    if not line:
        return None
    text = line.decode('ascii', errors='replace').strip()
    if not text:
        return None
    try:
        return float(text)
    except ValueError:
        return None

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        log.error('Failed to open serial port %s: %s', SERIAL_PORT, exc)
        sys.exit(1)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)

    alarm_active = False

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                log.error('Serial I/O error: %s', exc)
                time.sleep(1)
                continue

            radiation = _parse_radiation(raw)
            if radiation is None:
                log.warning('Invalid data received: %r', raw)
                continue

            log.info('Radiation Level: %.2f µSv/h', radiation)

            if radiation > RADIATION_THRESHOLD:
                if not alarm_active:
                    GPIO.output(ALARM_PIN, GPIO.HIGH)
                    alarm_active = True
                    log.warning('Radiation level exceeds threshold! Alarm triggered.')
            else:
                if alarm_active:
                    GPIO.output(ALARM_PIN, GPIO.LOW)
                    alarm_active = False
                    log.info('Radiation level back to normal. Alarm deactivated.')

            time.sleep(1)
    finally:
        _cleanup(ser)

if __name__ == '__main__':
    main()

