import serial
import time
import signal
import sys
import os

LOG_FILE = 'co2_readings_log.txt'
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1          # seconds
SAMPLE_INTERVAL = 5       # seconds between readings

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _log_reading(value: int) -> None:
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    line = f'{timestamp} - CO2: {value} ppm\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as fh:
            fh.write(line)
            fh.flush()
    except OSError as exc:
        print(f'Error writing to log file: {exc}', file=sys.stderr)


def _process_reading(raw: str) -> None:
    try:
        value = int(raw)
    except ValueError:
        print(f'Invalid data received (not an integer): {raw!r}', file=sys.stderr)
        return
    if value < 0:
        print(f'Invalid data received (negative): {raw!r}', file=sys.stderr)
        return
    _log_reading(value)
    print(f'CO2: {value} ppm')


def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as exc:
        print(f'Error opening serial port {SERIAL_PORT}: {exc}', file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f'Serial read error: {exc}', file=sys.stderr)
                break

            if not raw:
