    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection to the GPS module."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Serial port {port} initialized successfully.")
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        return None

def parse_gps_data(data):
    """Parses NMEA GPS data and extracts latitude, longitude, and altitude."""
    try:
        msg = pynmea2.parse(data)
        if hasattr(msg, 'latitude') and hasattr(msg, 'longitude') and hasattr(msg, 'altitude'):
            return msg.latitude, msg.longitude, msg.altitude
        else:
            return None, None, None
    except pynmea2.ParseError as e:
        print(f"Error parsing NMEA sentence: {e}")
        return None, None, None
    except Exception as e:
        print(f"Unexpected error parsing GPS data: {e}")
        return None, None, None

def log_coordinates(log_file, latitude, longitude, altitude):
    """Logs the GPS coordinates to a file with an ISO 8601 timestamp."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f"{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}\n"
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
        print(f"Coordinates logged: Latitude={latitude}, Longitude={longitude}, Altitude={altitude}")
    except IOError as e:
        print(f"Error writing to log file: {e}")
    except Exception as e:
        print(f"Unexpected error logging coordinates: {e}")

def main():
    """Main function to read GPS data, parse it, and log the coordinates."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        print("Failed to initialize serial connection. Exiting.")
        sys.exit(1)

    try:
        while _running:
            try:
                raw_line = ser.readline()
                if not raw_line:
                    continue  # Timeout occurred with no data

                line = raw_line.decode('ascii', errors='replace').strip()
                if not line.startswith('$GPGGA'):
                    continue

                latitude, longitude, altitude = parse_gps_data(line)

                # Check for valid GPS fix (quality indicator '1' = GPS fix)
                if latitude is not None and longitude is not None and altitude is not None:
                    # Extract fix quality from the NMEA sentence
                    try:
                        fix_quality = line.split(',')[6]
                        if fix_quality == '1':
                            log_coordinates(LOG_FILE, latitude, longitude, altitude)
                    except IndexError:
                        print("Incomplete NMEA sentence; could not read fix quality.")
                    except Exception as e:
                        print(f"Error extracting fix quality: {e}")

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except UnicodeDecodeError as e:
                print(f"Unicode decode error: {e}")
            except Exception as e:
                print(f"Unexpected error in main loop: {e}")

    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

