import serial
import time
import signal
import sys
from datetime import datetime

LOG_FILE = 'health_readings_log.txt'
PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def log_error(message):
    ts = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f"{ts} - ERROR: {message}\n")
    except OSError as e:
        print(f"Failed to write to log file: {e}", file=sys.stderr)

def log_reading(heart_rate, spo2):
    ts = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    line = f"{ts} - Heart Rate: {heart_rate} bpm, SpO2: {spo2} %\n"
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(line)
    except OSError as e:
        print(f"Failed to write to log file: {e}", file=sys.stderr)

def parse_data(data):
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}")
    hr = parts[0].strip()
    spo2 = parts[1].strip()
    if not hr.isdigit() or not spo2.isdigit():
        raise ValueError("Non-numeric values in data")
    return int(hr), int(spo2)

def main():
    signal.signal(signal.SIGTERM, _handle_signal)
    try:
        with serial.Serial(PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            while _running:
                try:
                    raw = ser.readline()
                    if not raw:
                        log_error("No data received (timeout)")
                        time.sleep(READ_INTERVAL)
                        continue
                    data = raw.decode('ascii', errors='replace').strip()
                    if not data:
                        time.sleep(READ_INTERVAL)
                        continue
                    try:
                        heart_rate, spo2 = parse_data(data)
                        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")
                        log_reading(heart_rate, spo2)
                    except ValueError as e:
                        log_error(f"Parsing error: {e} - Raw data: {data!r}")
                except serial.SerialException as e:
                    log_error(f"Serial communication error: {e}")
                except OSError as e:
                    log_error(f"I/O error: {e}")
                time.sleep(READ_INTERVAL)
    except serial.SerialException as e:
        log_error(f"Failed to open serial port {PORT}: {e}")
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

