import logging
import signal
import sys
import time
from dataclasses import dataclass
from typing import Optional

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None

class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port: Optional[serial.Serial] = None
        self._running = False

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            logging.info(f"Connected to GPS on {self.port} @ {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self.serial_port = None
            return False
        except Exception as e:
            logging.error(f"Unexpected error opening {self.port}: {e}")
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logging.info("Serial port closed.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None

    def read_gpgga(self) -> Optional[GPS_readings]:
        if self.serial_port is None or not self.serial_port.is_open:
            logging.error("Serial port not open; cannot read.")
            return None

        try:
            raw = self.serial_port.readline()
            if not raw:
                logging.warning("Read timeout: no data received within 1 second.")
                return None

            line = raw.decode("ascii", errors="replace").strip()
            if not line.startswith("$GPGGA"):
                logging.debug(f"Non-GPGGA line ignored: {line!r}")
                return None

            fields = line.split(",")
            if len(fields) < 15:
                logging.warning(f"GPGGA field count too short ({len(fields)}); expected >=15.")
                return None

            if fields[0] != "$GPGGA":
                logging.warning(f"Unexpected talker ID: {fields[0]!r}")
                return None

            fix_quality = fields[6]
            if fix_quality == "0" or fix_quality == "":
                logging.debug("No GPS fix (fix_quality=0).")
                return None

            try:
                latitude = self._to_decimal(fields[2], fields[3])
                longitude = self._to_decimal(fields[4], fields[5])
                altitude = float(fields[9]) if fields[9] else None
                satellites = int(fields[7]) if fields[7] else None
            except ValueError as e:
                logging.error(f"Numeric conversion error in GPGGA: {e}")
                return None

            return GPS_readings(
                latitude=latitude,
                longitude=longitude,
                altitude=altitude,
                satellites=satellites,
            )

        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error parsing GPGGA: {e}")
            return None

    @staticmethod
    def _to_decimal(raw: str, direction: str) -> float:
        if not raw or not direction:
            raise ValueError("Empty latitude/longitude field.")
        try:
            value = float(raw)
        except ValueError:
            raise ValueError(f"Invalid numeric value: {raw!r}")
        if direction in ("S", "W"):
            value = -value
        return value

    def run(self) -> None:
        if not self.connect():
            logging.error("Cannot start: GPS connection failed.")
            return

        self._running = True
        try:
            while self._running:
                readings = self.read_gpgga()
                if readings is not None:
                    logging.info(
                        f"GPS: lat={readings.latitude}, lon={readings.longitude}, "
                        f"alt={readings.altitude}, sat={readings.satellites}"
                    )
                time.sleep(0.1)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received; shutting down.")
        finally:
            self.disconnect()

    def stop(self) -> None:
        self._running = False

def main() -> None:
    reader = GPSReader(port="/dev/serial0", baudrate=9600)

    def _signal_handler(signum, frame):
        logging.info(f"Signal {signum} received; requesting stop.")
        reader.stop()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    reader.run()

if __name__ == "__main__":
    main()

