import logging
from typing import List, Optional, Dict, Any

from flask import Flask, Response, request, jsonify
import serial

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(threadName)s: %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1          # seconds
LISTEN_HOST = "0.0.0.0"
LISTEN_PORT = 5000

# ---------------------------------------------------------------------------
# In-memory data store (thread-safe via lock)
# ---------------------------------------------------------------------------
data_store: List[Dict[str, Any]] = [
    {"id": 1, "name": "Task 1", "done": False},
    {"id": 2, "name": "Task 2", "done": True},
]
data_lock = threading.Lock()

# ---------------------------------------------------------------------------
# Flask app
# ---------------------------------------------------------------------------
app = Flask(__name__)


# ---------------------------------------------------------------------------
# Serial helpers
# ---------------------------------------------------------------------------
class SerialManager:
    """Context-manager serial port wrapper with idempotent open/close."""

    def __init__(self, port: str, baudrate: int, timeout: float):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._serial: Optional[serial.Serial] = None
        self._lock = threading.Lock()

    # -- context-manager protocol ------------------------------------------
    def __enter__(self) -> "SerialManager":
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    # -- public API ---------------------------------------------------------
    def open(self) -> None:
        """Open the port if it is not already open."""
        with self._lock:
            if self._serial is not None and self._serial.is_open:
                return
            try:
                self._serial = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=self.timeout,
                )
                logger.info("Serial port %s opened at %d baud.", self.port, self.baudrate)
            except serial.SerialException as exc:
                logger.error("Failed to open serial port %s: %s", self.port, exc)
                self._serial = None
                raise

    def close(self) -> None:
        """Close the port if it is open."""
        with self._lock:
            if self._serial is not None and self._serial.is_open:
                try:
                    self._serial.close()
                    logger.info("Serial port %s closed.", self.port)
                except serial.SerialException as exc:
                    logger.error("Error closing serial port %s: %s", self.port, exc)
            self._serial = None

    def is_open(self) -> bool:
        with self._lock:
            return self._serial is not None and self._serial.is_open

    def send_command(self, command: str) -> Optional[str]:
        """Send a command and read one line back. Returns None on error."""
        if not self.is_open():
            logger.error("Serial port is not open.")
            return None
        try:
            self._serial.reset_input_buffer()
            self._serial.reset_output_buffer()
            self._serial.write(command.encode("ascii"))
            self._serial.flush()
            raw = self._serial.readline()
            if not raw:
                logger.warning("No response within timeout.")
                return None
            return raw.decode("ascii", errors="replace").strip()
        except serial.SerialException as exc:
            logger.error("Serial communication error: %s", exc)
            return None


