        return Response(str(exc), status=502, mimetype="text/plain")


@app.route("/data", methods=["GET"])
def get_all_data() -> Response:
    """Return all items as JSON."""
    with data_lock:
        items = list(data_store)
    return jsonify(items)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_data_by_id(item_id: int) -> Response:
    """Return a single item by ID, or 404 if not found."""
    with data_lock:
        item = next((i for i in data_store if i["id"] == item_id), None)
    if item is None:
        return Response("Item not found.", status=404, mimetype="application/json")
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_data() -> Response:
    """Create a new item with validation."""
    try:
        new_item = request.get_json(silent=True)
        if not isinstance(new_item, dict):
            return Response("Invalid JSON body.", status=400, mimetype="application/json")
        name = new_item.get("name")
        done = new_item.get("done", False)
        if not isinstance(name, str) or not name.strip():
            return Response("Name is required and must be a non-empty string.", status=400, mimetype="application/json")
        if not isinstance(done, bool):
            return Response("done must be a boolean.", status=400, mimetype="application/json")
        with data_lock:
            new_id = data_store[-1]["id"] + 1 if data_store else 1
            new_item = {"id": new_id, "name": name, "done": done}
            data_store.append(new_item)
        return jsonify(new_item), 201
    except Exception as exc:
        logger.exception("Unexpected error in /data POST: %s", exc)
        return Response(str(exc), status=500, mimetype="application/json")


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
_shutdown_requested = threading.Event()


def _signal_handler(signum, _frame) -> None:
    logger.info("Signal %d received, shutting down...", signum)
    _shutdown_requested.set()


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        app.run(host=LISTEN_HOST, port=LISTEN_PORT, debug=False)
    except Exception as exc:
        logger.exception("Application error: %s", exc)
    finally:
        logger.info("Application stopped.")


if __name__ == "__main__":
    main()

