import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def parse_data(data):
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 comma-separated fields, got {len(parts)}: {data!r}")
    heart_rate = parts[0].strip()
    spo2 = parts[1].strip()
    if not heart_rate or not spo2:
        raise ValueError(f"Empty field(s) in data: {data!r}")
    return heart_rate, spo2

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            try:
                line = raw.decode('ascii', errors='replace').strip()
            except Exception as e:
                print(f"Decode error: {e}", file=sys.stderr)
                continue

            if not line:
                continue

            try:
                heart_rate, spo2 = parse_data(line)
                print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")
            except ValueError as e:
                print(f"Data format error: {e}", file=sys.stderr)

            time.sleep(READ_INTERVAL)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

