        ser.reset_input_buffer()
        ser.write(b'*IDN?\n')
        time.sleep(SERIAL_PAUSE)
        raw = ser.read(4096)
        if not raw:
            return Response(
                "Serial port error: no response from instrument.\n",
                status=503,
                mimetype='text/plain',
            )
        text = raw.decode('ascii', errors='replace').replace('\n', '<br>')
        return Response(f"<html><body>{text}</body></html>", mimetype='text/html')
    except serial.SerialException as exc:
        print(f"Serial communication error: {exc}")
        return Response(
            f"Serial port error: {exc}\n",
            status=503,
            mimetype='text/plain',
        )
    finally:
        close_serial()


