import serial

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400
TRANSMISSION_DELAY = 0.1


def send_command(bluetooth_port, command):
    """Send a command over the Bluetooth connection with a delay.

    Args:
        bluetooth_port: An open serial.Serial object.
        command: The command string to send.

    Raises:
        RuntimeError: If the write fails or the port is closed.
    """
    try:
        bluetooth_port.write(f"X{command}\n".encode("utf-8"))
        bluetooth_port.flush()
        time.sleep(TRANSMISSION_DELAY)
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}") from e
    except OSError as e:
        raise RuntimeError(f"OS error during write: {e}") from e


def main():
    """Main function to handle user input and send commands."""
    bluetooth_port = None
    try:
        bluetooth_port = serial.Serial(
            BLUETOOTH_DEVICE, BLUETOOTH_BAUDRATE, timeout=1
        )
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUDRATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                print("Exiting program.")
                break

            try:
                send_command(bluetooth_port, user_command)
            except RuntimeError as e:
                print(f"Transmission error: {e}", file=sys.stderr)
                break

    except serial.SerialException as e:
        print(f"Error connecting to Bluetooth device: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if bluetooth_port is not None and bluetooth_port.is_open:
            bluetooth_port.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

